/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180313-3","meetingId":"h30-c-budget","date":"2018年3月13日","dateIso":"2018-03-13","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を150件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"２９７ページ、デザインマンホール蓋設置等、３０７ページ、浸水対策事業の中の浜川雨水配水管建設工事その２（舗装本復旧）についてお伺いをします。初めに、デザインマンホール蓋設置等についてお伺いをいたします。本区でも、このプレス発表のとおり、シナモロールを使ったマンホールカードとマンホールのふたを設置するということになっております。そこでまず最初に、８９万５,０００円の内訳です。","respondent":"多並道路課長","answer":"その作成と配布の考え方ですけれども、この作成するタイミングは年に３回の予定になっているそうで、４月、８月、１２月というのが今までの、例年のスケジュールだそうです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひこれ、道路事業と下水道事業、あと観光の観点からも、魅力を発信していただきたいと思います。続きまして３０７ページ、浸水対策事業の浜川雨水管建設工事その２（舗装本復旧）についてお伺いをいたします。よろしくお願いします。","respondent":"持田河川下水道課長","answer":"来年舗装の復旧工事ということで、延長としては、影響部分を含めて１００ｍぐらいの範囲で最後に舗装をして、きれいに仕上げて終了というような予定です。","voiceIndex":8,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これはオリンピック会場になる海浜公園のところの無電柱化と、あとバリアフリー化に伴って、これから立会川駅まで整備していくと思うのですけれども、その辺の舗装について、今度どのように道路課とも連携をしてやっていくのか、整備をしていくのか、改めてお知らせをお願いしたいと思います。","respondent":"持田河川下水道課長","answer":"その他オリンピックの関連の部分につきましては、また我々と道路課のほうと調整しながら、それはそれでまたそういった、オリンピックの関連の事業という形で進めていくというような形になってあります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"浜川雨水のことはわかりました。それとあと第二戸越幹線の整備工事についてお伺いをしたいと思います。これ工事費の中で上流部のシールド工事が３億円ということで、この上流部のところは西品川公園のところが拠点になると思うのですけれども、その辺のところの工事工程がどのようになっているのか、教えていただきたいと思います。","respondent":"持田河川下水道課長","answer":"この西品川公園の利用の時期ということでいきますが、この上流部分が終わった後に下流部分まで想定してございまして、今おおむね平成３６年までは、公園のほうは下水道のほうで使わせていただくというような予定です。","voiceIndex":14,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"平成３６年度まで続くという工事の中で、この浜川のところも下水道の認知というか、啓発活動というのですか、地域の方にお知らせをしたりとか、現場見学会、浜川小学校にもこの現場見学会をやったりとかあると思うのですけれども、この第二戸越幹線のほうもそのような現場の見学会などもぜひ考えてもらいたいと思っているのですが、その辺のところもお聞かせいただきたいと思います。","respondent":"持田河川下水道課長","answer":"やはり公園のほう長く使って工事をして、地元のほうにもそういった形でのご迷惑をかけるところもあります。ぜひ工事が進むなかで、タイミングを見て地元の方をお招きして、見学会のほうも実施したいと考えています。","voiceIndex":16,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"３３３ページ、『わが家の防災ハンドブック』、３３７ページ、避難所管理費、３０１ページの勝島歩道橋エレベーター等整備、時間がありましたら３０５ページの水辺利活用事業についてお伺いいたします。これは都議会公明党の女性議員が昨年末に小池都知事に要望をして、３年前に発行された『東京防災』の足りない部分を補完する形で発行されたものであります。","respondent":"古巻防災課長","answer":"今、お話のありました『東京くらし防災』、これは東京都が３月１日から配布を始めているものですけれども、区におきましては区有施設８０カ所程度、窓口へ置かせていただきまして、なかなか評判がいいというふうには聞いております。","voiceIndex":19,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"この『東京くらし防災』には、音声コードが入っております。これも公明党が要望をしてつけていただいたものですけれども、まず１つが、この『東京くらし防災』を視覚障害者の方へしっかり情報提供をされているのかどうかというところ、それと、今度品川区が改訂をいたします『わが家の防災ハンドブック』の改訂版におきましても、このような配慮が必要ではないかと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"ちょっとどのような形でできるかというのは、まだ具体的には申し上げられないところではありますけれども、今後『わが家の防災ハンドブック』につきましては、体裁、それから内容について検討を進めていく、具体的にしていくというような段階ですので。","voiceIndex":21,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。視覚障害者団体へも、障害者福祉課と連携をとりながら、ぜひ情報提供をお願いしたいと思いますのと、あと『東京くらし防災』がかなり少なくなっているということですので、ぜひ品川区からも東京都へ増刷の要望をしていただきたいと思います。次に行きます。避難所管理費、避難所運営マニュアル更新支援費についてお伺いいたします。この内容について少しお伺いをいたします。","respondent":"古巻防災課長","answer":"でき上がった成果物ですけれども、基本的にはアドバイザーの方、それから区の職員、そして地域の方とでつくり上げていくというような形ですが、やはり今までもお話ししてきたとおり、地域の方が主体でつくっていくという形になろうかと思いますので。","voiceIndex":23,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。関連をいたしまして、避難所の備蓄品についてお伺いをしたいと思います。ここで具体的になってまいりましたので、この液体ミルクを備蓄品に加えていただきたいということを要望させていただきたいと思います。これまでの熊本地震、また東日本大震災でも、海外から寄附されたものが提供されたという経緯もありますので、今後の品川区のお考えをお伺いいたします。","respondent":"古巻防災課長","answer":"品川区としまして備蓄をというようなお話ですけれども、まだそういった基準はできましたが、国内への流通の状況でありますとか、そういったところがまだよくわからない状況ですので、そういった国の基準も含め、そのようなさまざまな状況、これを注視してまいりまして。","voiceIndex":25,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"３０１ページの勝島歩道橋についてお伺いいたします。オリンピックを目指してということではありますが、１日も早く設置をされるように進めていただきたいと思います。プレス発表の資料では、自転車走行空間の整備もあわせてというふうに書かれておりましたので、この自転車のところがどのようになっていくのか教えていただきたいと思います。","respondent":"多並道路課長","answer":"自転車レーンの考え方ですけれども、交通量が多くて車道のほうを自転車が通る形がなかなか難しいということで、矢羽根は設置せず、歩道内を通っていただくということで今考えております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは３２３ページの公衆便所について、西大井駅の公衆トイレについて伺います。そして５４７ページの災害復旧特別会計も伺いたいと思います。品川区もおもてなしトイレの整備を始めておりますけれども、ぜひこの西大井駅のトイレも改修していただきたいと思いますが、いかがでしょうか。こういう状況をどう思うのか、ぜひ改修をしていただきたいのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"委員のご指摘の西大井駅の公衆便所ですが、今実際としましては、身障者トイレという車椅子対応の洋式トイレがついているところです。","voiceIndex":30,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"本当に地域の方から切実に訴えられておりますので、いずれは洋式化というお話でしたけれども、ぜひ早く進めていただきたいと、これは強く要望しておきたいと思います。次に、災害復旧特別会計について伺いたいと思います。この災害発生後は、財源が災害復旧基金繰入金ではなくて、最終的には国の財源に変更されるのか、この場合に補正や決算で財源更正となるのか、その想定も伺いたいと思います。","respondent":"古巻防災課長","answer":"それから復旧費のほうにつきましても、これはなかなかそのときの状況によって難しいというか、算定が難しいところがありますけれども、例えば家屋の解体などにつきましても国からの補助であったり、また特別交付金などの措置がされるといったこともございましたので。","voiceIndex":32,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"改めて従来の品川区の考えでは、どの基金から取崩しで可能だと判断していたのか伺いたいと思います。予防対策や応急活動を位置づける一般会計から、このように災害救助と復旧事業費をなぜ一般会計と切り離すのか、経理の明確化と説明がありますが、同じ防災対策を予防と救助・復旧・復興とで会計を明確にする理由は何なのか伺いたいと思います。","respondent":"秋山財政課長","answer":"このようなことを、この特別会計を持って区が実際に支払う現金をいつでも出せるという状態で災害に備えているという、それが１つの品川区としてのメッセージだと考えているものです。","voiceIndex":34,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"先ほど、従来の品川区ではどの基金からの取崩しで対応するのかと伺ったので、その点も伺いたいと思います。","respondent":"秋山財政課長","answer":"従来の品川区の基金では、例えば公共施設が壊れたなどという場合の復旧については公共施設の整備基金であったり、教育施設であれば義務教育施設整備基金、また、それ以外のものであれば、財調基金等を使って財源として補正予算を組んで。","voiceIndex":36,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"もちろん迅速な支払いは災害発生後必要だと思います。しかしその説明だと、今言ったように、従来の対応でもできるのだと思います。と思うと、なぜ特別会計が必要なのか、新たな基金をつくるのかというところに、また疑問が戻るのですけれどもいかがでしょうか。","respondent":"秋山財政課長","answer":"それだけの準備を区はしているという、そのようなメッセージでありますし、それが区の事業者に対して、災害時にこのようなことを考えるかどうかわかりませんけれども、安心して事業を受託していただけると考えているものです。","voiceIndex":38,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"それをなぜ新たな基金と新たな会計をつくらなければ進まないのかと、その点を改めて伺いたいと思います。今回の当初予算には入っていませんが、この被災者の生活再建についてですけれども、長期的な復興計画にも係る災害時の生活再建のための予算は、やはり長期的な視野になってくると思うので、ここの特別会計にはなじまないと思うのですけれども、この辺についても伺いたいと思います。","respondent":"秋山財政課長","answer":"それから生活再建の予算ですけれども、今回の災害復旧特別会計ですので、復興まではこちらのほうには予算の中でも組み立てておりませんので、一般会計等で長期的なものは補正予算等議決をいただいて執行するという形になるかと思います。","voiceIndex":40,"id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"その説明ですと、この避難所の開設や運営費や輸送費、また家屋の解体や公共施設の復旧費や災害廃棄物処理費、これは一般会計に組み込んで議決をもらえば執行できるということにはなりませんか。","respondent":"秋山財政課長","answer":"一般会計の規模をいたずらに膨らますようなことにもなりかねませんので、特別の目的をもった特別会計を設置して、わかりやすく説明をさせていただいているです。先ほどご質問ありましたけれども、議会の議決をいただいてから執行ができると。","voiceIndex":42,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"今ご説明あったように、一般会計に入れて議決をもらえば執行ができるということですよね。なぜそれを切り分けるのかと、やはり疑問に思います。例えば、住宅の耐震化や、防災の備蓄は一般会計で行っております。その他諸々、償還金についても一般会計で行っております。防災対策として相互に関係しているものをなぜ災害救助と災害復旧だけ分けるのか、改めて伺いたいと思います。","respondent":"秋山財政課長","answer":"１つは一般会計の額の説明責任もあります。使わない金額、１５億円を、要するに積むということですから、これはほかの震災、耐震化等の事業とはまた違うわけです。耐震化の事業はやりたかったけれどもできなかったということです。","voiceIndex":44,"id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私もこの事業の進展はしっかりと見守っていきたいと思います。いかがでしょう。そういうものがありますので、ぜひご検討いただきたいということがまず１点。住宅まつりについてであります。以前にも何度も質問させていただいておるのですが、この消火隊の備品の中には、おそらく防災服とか、防火服があろうかと思いますけれども、フルモデルチェンジというのですか、それをお考えなのかどうなのか。","respondent":"今井土木管理課長、多並道路課長、溝口公園課長、古巻防災課長、長尾住宅課長、冨澤防災安全担当課長","answer":"委員ご指摘のとおり、広域連携という形になりますと、この４月１日から品川区、大田区も含めて９区になりますので。区としましても、その状況をよく踏まえながら、来年度予算、平成３０年度予算の中で無電柱化基本方針の策定経費ということで。さらに定期点検といたしまして、年に１回専門の委託業者のほうに発注いたしまして、遊具の磨耗状況ですとか、部品のがたつき。Ｃ級ポンプにつきましては、老朽化というようなお声を以前からいただいておりまして。","voiceIndex":48,"id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"中には明らかに塗り直した遊具や、塗装がはがれてしまっている遊具、以前は登り棒や、プーリースライドというのですか、スライダーが設置されていたが、事故防止のために取り外された遊具などがそのままになっております。住宅まつりについては、以前お伺いしたときは単費ではなく、いろいろ補助金が入っていたという認識があったので確認をさせていただきました。","respondent":"溝口公園課長、長尾住宅課長、冨澤防災安全担当課長","answer":"はやはり２６６ある公園、安全に交流をしていただく、特に遊具については子どもたちの安全・安心。そういった新しい企画など、企画を充実させていくというところも含めまして、今後主催されている団体のご意見も踏まえながら。これからもご活躍をしていただくために、先ほど委員から手当てというご提案がございましたけれども、どのようなご支援ができるのか。","voiceIndex":55,"id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"誰がどのような人なのかが全くわからないので、しっかり明確にするためにしっかりと色がついたものがいいのではないですかということで質問させていただきました。Ｃ級ポンプに関しては、もう古いものだとリコイルスターターハンドルというものが引き切れないというのですか、始動のときに。ですからそのような部分も含めて、もう早急に配備をしていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"私は都市計画費全般と防災費全般についてお聞きしたいと思います。今、都市部でも所有者不明の土地が増えていて、再開発を進めようとしたり、道路の拡幅や新たな道路をつくろうとした場合に支障を来すことが増えてきたと聞いていますが、品川区では実際どうなのでしょうか。","respondent":"高梨木密整備推進課長","answer":"そうしますと、地域の皆様と話し合いを進めていくのですけれども、どうしても合意形成の段階で権利を持つ、どこにいるかわからない方々に意見が聞けないといった形で、最初の段階ではいいのですけれども、やはり。","voiceIndex":61,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"品川区でも、この所有者不明の土地という問題が、やはりこれから大きくのしかかってくると思うのですが、これを品川区で実際に探す部署はあるのでしょうか。先ほどやはり行き詰まるというお話でしたが、ずっとたどっていけばわかっていくのでしょうか。その辺についてちょっとご見解をお聞かせください。","respondent":"高梨木密整備推進課長","answer":"ただし、追跡したところ、その転出先の自治体に問い合わせても、もう既に転出してから長い年月がたっているので、その方がさらにどこに転出したのかわからないといったような形で、なかなか所有者不明の土地については権利者に行き当たらないというのが現状です。","voiceIndex":63,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"ということは、これから、２０２５年問題もあります。団塊の世代、その方たち人口がすごく多いですが、その方たちがこれから後期高齢者になって、ますますもうその土地の所有関係、いわば相続の問題です。これに対して、何か解決するような施策というもの、また、その法律等はないのですか。それについて、ちょっとご見解と、そしてこれを対処するような法律というものはないのですか。","respondent":"高梨木密整備推進課長","answer":"その中では、報道でもありましたとおり、１０年間の使用権設定をするであるとかということで、イベントでしたり、期間限定の取組みについてはなかなか使用がしやすいような仕組みが検討されているようなのですが、我々まちづくりの部隊が行っている恒久的な利用。","voiceIndex":65,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"今、私再開発ということ、あと区内の道路も含めて、道路整備云々もあると思います。まちづくりにとっては非常に大事だという観点でお話ししています。それでこれだけ、もう７年たって、東日本大震災、７年たって大体形が見えてきた。最初の３年間はほとんど進まなかった。それは権利関係だったそうです。このまま放置していていいのでしょうか。ちょっとご見解をお聞かせください。","respondent":"今井土木管理課長","answer":"これはなかなか官民境界確定ということで、今おっしゃいました道路と民地との境をまずは決めていこうということで、都市部で先行的にやっておりますけれども、この地籍調査事業も今、これから行われますさまざまな事業の基礎となるものですので。","voiceIndex":67,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"今、地籍事業とおっしゃいました。地籍とは隣と隣、公・民の境です。その権利関係をきちんとする、登記上にもしっかり載せて、ここは皆さん民有地、公有地という区分をしているだけです。でも、そうではなくて、そこだって最後、誰が判を押すのですか。例えば民地の方、それが所有者がわからなかったら、一向に進まないですよね。でも判を押す人がいなかったらそのままではないですか。","respondent":"今井土木管理課長","answer":"現在、政府のほうでも検討されているというふうに聞いておりますけれども、マイナンバー制度で全国で一括管理をすることも進めていると聞いております。今、委員ご指摘の所有者不明土地ですね。登記簿や戸籍、さまざまな分野にわたりますので、国が持っている情報が大変多いです。","voiceIndex":69,"id":"exchange-026"},{"speaker":"須貝委員","kind":"確認","question":"やはりここは、私は所管をまたがってやる事業だと思うのですが、住民票、住所確定、そしてあとは、固定資産税のほうはまた都のほうでやるのでしょうから違うのでしょうけれども、さまざまな分野で追跡をして、きちんとその本人の、所有者の本人確認をしていかなければ、これは膨大なお金がかかってもやっていかないと。","respondent":"多並用地担当課長","answer":"ただ、これについても、都の事業計画を出して認可するとか、いろいろ一定の制度と、あとはいろいろな活用の細かいところのルールについては、またこの法制度を確定した後に、いろいろ国からガイドラインを出すという報道もありますので。","voiceIndex":71,"id":"exchange-027"},{"speaker":"須貝委員","kind":"提案","question":"この２３区でも板橋区ですか、どの程度やられているかわかりませんが、ここはこのような所有者不明土地があって、専門チームをつくって対策に乗り出している。ですが、提案として、土地所有者を探す専門チームをつくったり、そしてまたこの所有者不明土地をなくすために、土地相続時に登記をする仕組みというものをきちんと確立していかなければいけないのかなと思うのです。","respondent":"多並用地担当課長","answer":"登記の考え方も今の委員のご指摘のとおりで、そういうものが課題だということですので、追いかけるのが今の所有者の方、実際持っている方を探すのが大変ということで国で今検討が進められている。","voiceIndex":73,"id":"exchange-028"},{"speaker":"須貝委員","kind":"確認","question":"それもやはり有効に使う、使うためには、やはりその事業を円滑に進めるために、しっかりした所有者、確認をするということは大前提だと思いますので、今後その点についてはよろしくお願いいたします。今度危機管理室ではなくて国民保護担当に変わりますが、これはこの名称が区民にはすごくわかりにくい、なじみにくい名称だと思いますけれども、何かこれ対策というものは考えているのでしょうか。","respondent":"古巻防災課長","answer":"危機管理については総務課のほうで全般的に対応するというようなことで、きちんと整備をしていくということで、よりわかりやすい対応ができるような体制にしたいです。","voiceIndex":75,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"私からは２９２ページ、１項１目土木管理費、公有地の管理と、２９３ページ、シェアサイクル事業、３０７ページ、３項１目河川下水道費、雨水利用タンク設置助成事業、３２７ページ、６項住宅費、住環境改善促進事業について伺います。土木の中でも公有地の管理です。品川区の公有地の管理については、品川区公有財産管理規則にのっとって行われていると理解をしておりますが、その理解でよろしいでしょうか。","respondent":"今井土木管理課長","answer":"今、委員ご指摘のとおり、公有財産の管理については、それをもとに行っているものです。","voiceIndex":78,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"それで、この規則の中には土地の管理というものは財産の取得、保管および処分であり、保管には運用も含まれると明記されております。つまり、品川区の公有地の使い方を決める根拠は、この規則によると考えてよろしいのでしょうか。それももう１回教えてください。","respondent":"今井土木管理課長","answer":"私どもがこの公有地管理事務というところで管理しているところにつきましては、防災まちづくり部が所管します道路や公園等に関する公有地に関しまして、公有地の管理事務をしているものです。","voiceIndex":80,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。そうすると、所管それぞれあると思いますけれども、品川区として持っている基本の根拠となるのはこの規則という理解で質問を進めします。この規則の第４２条の公有財産管理運用委員会というものがあって、そこがその品川区の公有地の使い方を決定するというふうに読めるのですけれども、合議体としてはその委員会がいろいろなことを決定すると考えてよろしいでしょうか。","respondent":"今井土木管理課長","answer":"私どももまちづくり事業用地につきまして、例えば昔の水路事業、自分でご購入したいとか、売り払いを受けたいという方がいらっしゃった場合には、そこの部分につきまして、そちらの公有財産管理運用委員会のほうに付議をしている、そのような関係です。","voiceIndex":82,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"そうしますと、会議を開くというのは今課長がおっしゃったように、何かそれぞれの所管がその必要があったときに呼びかけて、招集については総務部長となっているのですけれども、そのように理解してよろしいのでしょうか。それで、その会議を開くタイミングなのですけれども、割と今課長がおっしゃったように、具体的な事例が出てきた、その時点でもう開いていくものなのか、それとも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"ですから、土木管理の範囲で結構なのですけれども、会議を開くというのはその所管の部が働きかけて、それで総務部長が決定するという手順でよろしいのでしょうかということです。","respondent":"今井土木管理課長","answer":"私どもスケジュールや開催の時期などについては、特に要望するものではございませんけれども、やはりスケジュールを含めて区民の方の売り払い等、ご要望を受けたときに経理課のほうに依頼をしています。","voiceIndex":86,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"この第４２条の委員会の決定の事項に、区民の土地、それを買うということが直接的に見えなくて、例えば行政用語の使い方の問題なのかなと思いますが、そのような売り払いの要望があったときというのは、普通財産として購入するのではないかと思いますけれども、普通財産の購入というところが読めなくて、それはこの条文でいいのか、それともほかに何か根拠の条文があるのか教えてください。","respondent":"立川経理課長","answer":"通常この運用委員会ですけれども、いわゆるいとまがないということで、年間かなりの件数、何百件も決定しなければならないというところもありますので、基本的には持ち回りでこの運用委員会を開いているところです。","voiceIndex":88,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"ごめんなさい。私、土木管理課長の答弁を聞き違えていましたか。売り払いはあれですね、区のほうですよね。私が聞きたかったのは、買ってほしいという要望があったときのということを、先ほど土木管理課長が事例に出されたと思ったので、その決定にかかわる事項がこの委員会の決定事項に入っていなかったので、それはどこで決まるのでしょうかという質問なのですけれども。","respondent":"立川経理課長","answer":"基本的に公有財産管理運用委員会につきましては、区の財産をどうするかということを決めるところですので、買ってほしいといった場合は、また違う流れの中で決定をするものです。","voiceIndex":90,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。本当に基本的な考え方がよくわからないで、今まで質問や意見を言っていたなと思いまして、改めてこの決定の流れについて伺いました。基本的には事業者が具体的な事業は行っていくということだったのですが、導入のコストは税金で行うということであれば、区としての方針とそれに対する効果測定をきちんとすべきと考えるのですけれども、それについてはいかがでしょうか。","respondent":"今井土木管理課長","answer":"シェアサイクル事業につきましては、平成２９年度２００台ということで、ＪＲ京浜東北線大井町駅東側の部分で２００台をまずは設置していこうということで、プレス発表させていただいたところです。現在これは、３月末までには２００台のラックの設置等が進む予定です。","voiceIndex":92,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"まだ社会実験中ということであれば、将来的に事業者が行っていくということなのでしょうか。私、昨年質問したときに、保険などはどこが負担するのかといったときに、事業者の事業なので、その事業者が保険に入ってそこをカバーするということだったと思うのですが、その点については、社会実験中は区がその保険なども責任を持つというように理解してよろしいでしょうか。","respondent":"今井土木管理課長","answer":"こちらのシェアサイクル事業は、平成２９年度１０月のスタート時から、イニシャルコスト、つまりこのような整備費につきましては区が都からの助成金を受けて資金を助成するもので、そして運営につきましては、全て運営事業者を区のほうで選定いたしまして。","voiceIndex":94,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。ありがとうございました。そういう意味でも、社会実験という意味の効果検証をしっかり行っていただきたいと思います。今後の方向性、どんどん導入していくのか、ここまでが適正な範囲だろうというようなことなどを、やはり区も一緒に判断していくのか、それとも事業者がどんどん判断していって、実証実験済んだ後はどんどん進めていくのか、その辺のことだけ最後確認させてください。","respondent":"今井土木管理課長","answer":"本事業は、実施主体は品川区ですので、効果検証を踏まえて、今後どのように拡大するか、または台数等についても区が判断していくものです。","voiceIndex":96,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"それが確認できてよかったです。観光客の利便性と、それから区民の住みやすいまちということを両方イメージしながら、進めていっていただきたいと思います。次に３０７ページの雨水利用タンク設置助成事業です。この時点で、トイレの洗浄水に品川区はこれだけ雨水を活用していたのだということを改めて確認しました。現時点での区内の施設での雨水活用と、それから今後の方向性ということを教えてください。","respondent":"持田河川下水道課長","answer":"これまでこういったタンクの助成事業というものは平成１８年からやってございまして、３万リットルというような形での対応というものをやっているところです。","voiceIndex":98,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"それについては理解しております。ぜひ続いていてほしいなということで伺っております。それから、区有施設に今まで雨水タンクつけられるところは全部つけたと伺っています。常に使われてこそ、治水にも合流改善にも役に立つのですが、以前使われているか確認しているかと質問したときに、その時点では、「確認していない」というご答弁だったと思います。その後確認されたかどうか教えてください。","respondent":"小林環境課長","answer":"計画を策定した課が環境課ですので、環境課から現状のほうご説明したいと思います。","voiceIndex":100,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"雨水タンクの水がきちんと使われていてこそ回転していきますので、それについての確認はぜひしていただきたいと思います。区有施設の雨水タンクです。改めて伺います。３２７ページの住宅費、住環境改善促進について伺います。少し視野を広げて、住宅確保要配慮者の住環境という視点で、住宅課としてのお考えを伺いたいと思います。","respondent":"長尾住宅課長","answer":"そのほか、ほかの課でも、いわゆる住宅確保要配慮者の中に挙げられている高齢の方もいらっしゃいますので、そういった方たちに対しての支援というものは今後も引き続き検討してまいりたいと考えております。","voiceIndex":102,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"住宅確保要配慮者ということでは幅広く捉えていただいて、ぜひ検討を進めていただきたいと思います。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"私からは２９３ページ、交通安全啓発費、３１１ページ、都市防災まちづくり事業費、３３３ページ、防災普及教育費についてをお伺いいたします。１点目に都市防災まちづくり事業費についてお伺いいたします。老朽木造建築等の除却助成について、平成２９年度の２億９,５００万円から平成３０年度は６億４,４８０万円と、４億円弱プラスになっています。","respondent":"高梨木密整備推進課長","answer":"助成期間が終わった後に知らなかったというような声が上がらないように周知の徹底、それと期間が限定だというところのご案内を徹底して行いたいと考えています。","voiceIndex":106,"id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"都の平均０.９ポイントを上回っているということで、１.５から７.５ポイント改善していただいております。木造住宅密集地域の事業実施地域に重点を置いていただきながら、事業を実施していない地域、その他の地域からもご要望の声、私も聞いておりますので、各地域におきまして、今後整備を積極的に進めていただきたいのですが、いかがでしょうか。","respondent":"高梨木密整備推進課長、溝口公園課長","answer":"ただ、まだ事業を行っている地域内でも防災広場を設置していないところもありますので、鋭意、防災広場の設置については今後も引き続き努めてまいりたいと考えています。公園の整備につきましては、今後も公園や広場、そういったものに対する地域や世代、またいろいろさまざまな要望、また幅広い需要等、そういったものをつかみながら、利用しやすい配置、またはそのような公園のない町会。","voiceIndex":108,"id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ積極的に公園整備のほうも、木密地域だけに限らず、全域で進めていただきたいと思います。２点目に交通安全経費についてお伺いいたします。区民の日常生活に支障を来したり、競技開始がおくれたりすることのないように、また区内企業との調整も必要になってくると思いますが、区内・都内での大きな行事等を見据えた区の交通安全対策について、現在どのような準備を進めているのかを教えてください。","respondent":"桑波田交通安全担当課長","answer":"これに向けまして、東京都でも交通輸送技術検討会というものが土木主管部長会のほうで設置されまして、こちらのほうは有識者でありますとか、内閣官房、国土交通省、あと警察庁、警視庁、首都高、東京都、そういったものが一丸となって、安全な輸送と交通の事故防止。","voiceIndex":111,"id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"報道のほうでは、２０２０年東京オリンピック・パラリンピック大会組織委員会が、一般道も含めた交通量を１５％程度削減することを目標として、今年の夏から企業などにも混雑緩和への協力を求めていくとされています。３点目、防災普及教育費についてお伺いいたします。そのうち２０階以上の超高層の数も、もしわかりましたら教えてください。","respondent":"古巻防災課長、鈴木建築課長","answer":"ですから、防災対策といたしましては、屋内の家具の転倒・落下・移動対策、それから備蓄であったり、そういったマンションでの在宅避難を支えるための準備、そういったことを中心に行っていくものかと考えているところです。今の補足ですが、６０ｍを超える、おおむね２０階建てにつきましては、事務所につきましては平成２８年度時点で３９棟です。共同住宅は４９棟と。ちょっと出どころの数字が違いますが、東京都の統計ではこういった数字です。","voiceIndex":113,"id":"exchange-047"},{"speaker":"横山委員","kind":"質問・要望","question":"高層マンションのほうは１０階建て以上、そして超高層のほうも区内で増えているかと思うのですけれども、積極的な防災対策を進めていただきたいと思います。これから品川区地域防災計画の修正ですとか、『わが家の防災ハンドブック』の更新のタイミングなので、手引等の記載をしていただくなど、まだ知らない方や新しく品川区に転入した方にもお伝えをしていただきたいと思います。一言お願いいたします。","respondent":"古巻防災課長","answer":"マンションの防災対策につきましては、今年度からマンションの防災アドバイザー派遣事業なども行っておりますので、今後も力を入れて、粘り強くやっていきたいと考えております。","voiceIndex":116,"id":"exchange-048"},{"speaker":"つる委員","kind":"提案","question":"３２３ページ、公衆便所費、３２１ページ、品川浦公園を初めとする便所改築・改修工事、２９５ページ、水辺千本桜計画策定、２９７ページ、目黒川桜植樹、３３０ページ、防災費、３２１ページ、小山台東公園改修実施設計委託、３２１ページ、ユニバーサルデザイン遊具等検討費について伺っていきます。公衆便所関係ですが、議会費のところでも提案をさせていただきました。","respondent":"溝口公園課長","answer":"これにつきましては新たな製品ということになっておりますので、今後いろいろなところでの使用状況、または先進事例、そういったところへのヒアリング、そういったことを通じて設置については研究してまいりたいと考えているものです。","voiceIndex":120,"id":"exchange-049"},{"speaker":"つる委員","kind":"確認","question":"オストメイトの方は、ストーマパウチからトイレでの便の出し方というアンケートの中では、座って処理をする方が５９％、立って処理をする方が４１％ということだそうであります。ですから、合理的配慮の観点で、ぜひ公衆便所・公衆トイレにも、積極的にご検討いただければと思います。次に移ります。桜関係ですが、これ昨年の予算でも確認をさせていただきました。","respondent":"多並道路課長","answer":"今後のこの水辺千本桜計画を実施するにあたりまして、まずは目黒川を中心とした水辺の桜を増やしていくということで、ゆくゆく将来的には１,０００本増やしていきたいという計画というものが我々の計画で、そういう意味では今委員がご紹介いただいたようなことが。","voiceIndex":122,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"わかりました。先行して３７本を平成３０年度に植樹ということでありますけれども、三獄橋、それから洲崎橋からということですが、その理由を教えてください。","respondent":"多並道路課長","answer":"平成３０年度に予定しております、新しく桜を植える３７本の件ですが、今年度目黒川の桜の状況というものを確認させていただきました。","voiceIndex":124,"id":"exchange-051"},{"speaker":"つる委員","kind":"質問・要望","question":"順次ということで確認ができました。２０１４年の予算のときに、目黒区にサクラ基金があると思いますが、私はそれを紹介させていただいて、品川区もクラウドファンディングなど活用して、桜の保全、植樹の推進ということで求めさせていただきましたけれども、品川区としては、この寄附についてはどのような寄附を募るのか、それを教えてください。","respondent":"多並道路課長","answer":"これは平成２０年から平成２７年で終わっている事業であるのですけれども、このようなものもいろいろ研究しながら、次の制度を検討していきたいと思っているところです。","voiceIndex":126,"id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"わかりました。最後に、これはもう何度も伺っているのですが、これは水辺でありますけれども、品川区の桜の占有率、先ほどこれ１,０００本追加すると、ユキヤナギを初め、いろいろな草木ある中で、たくさん花があふれている品川区というものが理想なのですが、五十七、八％になるという中で、駅周辺、この整備についてもぜひ引き続き検討いただきたいと思いますが、今の状況を教えてください。","respondent":"多並道路課長","answer":"ただ、桜については、かむろ坂を初めネットワークで、また水辺に来られた方が、また次の桜を楽しんでいただくということもありますから、今委員のご指摘のようなところも踏まえて、今度の計画をつくる際はそのような点も認識はさせていただいて。","voiceIndex":128,"id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"これは引き続き、また伺っていきたいと思います。次に移ります。防災費であります。避難所での備蓄物資関係についてですが、聴覚障害者への合理的配慮の観点で伺いたいと思います。既に導入している自治体、また東京都も既に配備をしているということもありますので、このアンブルボードについて配備をしたらどうかと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"現時点では特にそういったものを備えているわけではないのですけれども、避難所においては伝言ボードといいまして、何といいましょうか、静電気で張りつくようなボード、それでホワイトボードマーカー等で手書きができるようなボードについては備蓄をしておりますので。","voiceIndex":130,"id":"exchange-054"},{"speaker":"つる委員","kind":"質問・要望","question":"今はないのですが。これ２０１５年の決算のときにも求めたのですが、この一部の公園では遊具の下がやわらかい素材になっているものもあって、小山台東公園初め、今後改修等をしていく際には、今現状では土系の舗装、ウッドチップの舗装、ゴムチップ舗装等があると思うのですけれども、改修に合わせて、転落しても最悪の事態を免れるような素材にしていくべきかと思いますが、教えてください。","respondent":"溝口公園課長","answer":"そういった地域に親しまれている遊具ですので、そういったことも踏まえながら、今年度設計していく中でどういった遊具にしていくのか、そういったところを検討していきたいと考えているところです。安全の配慮です。遊具に関しては、遊具の安全に関する基準等あります。","voiceIndex":132,"id":"exchange-055"},{"speaker":"つる委員","kind":"質問・要望","question":"小山台東公園、またユニバーサルデザイン、ありがとうあります。ユニバーサルデザインとして、非常に障害のある方でも入りやすいとか、そういうことはあるのですが、その先でそこで遊べるというのは非常にいい方向性かなと思いますので、最後そういった意味で、東公園もそういったことも加味されていくのかどうか、確認をさせていただきたいと思います。","respondent":"溝口公園課長","answer":"今後いろいろ公園整備していく中で、小山台東公園も含めてそういったユニバーサルの視点、そういったものを大切にしながら、公園整備の計画、または実施、そういったものを行っていきたいと考えているものです。","voiceIndex":134,"id":"exchange-056"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひユニバーサルの視点も進めていただくのと、あと危険防止というところで、まだ順次、改修のときにという考え方はあるかと思うのですが、現状の土台などでコンクリートが少し出ているとか、そうしたところは定期巡回の中で対応をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-057"},{"speaker":"筒井委員","kind":"質問・要望","question":"実際段ボール紙管の間仕切りが避難所で使われるということになります震災時には。ぜひとも品川区からも避難所連絡会議等々に働きかけを行っていただきたいのですけれども、いかがでしょうか。なぜならば、都市型観光ということもありますので、やはり景観ということもしっかりと配慮していっていただきたいと考えておりますが、その点いかがでしょうか。以上２点、お願いいたします。","respondent":"古巻防災課長、多並道路課長","answer":"こういった訓練、やはり実際に組み立てることでどういったイメージのものかというのはわかりやすくなるとは考えておりますので、情報提供を含めて。そのような作業になってきますので、もちろんその中には景観という観点も入れさせていただきながら、検討していきたいと思っているところです。","voiceIndex":138,"id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。続いてです。東品川二丁目防災桟橋なのですけれども、地元の舟運事業者の方から、柵がなくて酔っぱらったお客様とか子どもが落下する危険があるのではないかというお問い合わせが入りまして、私も現地を見させていただいたのですが、確かにちょっと危ないかなと思われるところもありますので、安全上の柵というものもぜひ設けていただけたらなと思うのですけれども、いかがでしょうか。","respondent":"持田河川下水道課長","answer":"今お話にございました二丁目桟橋につきましても、船が着けられる部分で、柵が余り頑丈であると邪魔になるという視点もありますが、そういった部分を総合的に検討しながら、やはり安全な乗り降りができるという視点で、検討のほうを進めてまいりたいと思ってあります。","voiceIndex":141,"id":"exchange-059"},{"speaker":"筒井委員","kind":"質問","question":"舟運の運航コースについてなのですけれども、現在の舟運の運航コースは、お台場のほうまで行って着岸をするというコースがないと思うのですけれども、ぜひとも今後、さらなる舟運の広まりのためにも、五反田から目黒川へ行って、運河に出て、東京湾を越えてお台場のほうまで着岸するようなコースというものがぜひ必要かなと思うのですが、他の区などにまたがる可能性もあるのですけれども。","respondent":"持田河川下水道課長","answer":"ただ、我々としましても、やはり舟運の活性化というところもありますので、区有桟橋を使っていくことを基本に、またそういった少し広域なところについても、どのような可能性があるのかということについては、今後しっかりと検討してまいりたいと思ってあります。","voiceIndex":143,"id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"その会場への輸送という面、またいざというとき防災の何らかの補完地域としての拠点、そしてひいては八潮地区の活性化になると思うのですけれども、その東八潮の活用についていかがお考えでしょうか。新たに桟橋をつくることや、ヒルトンホテル寄りの桟橋の活用など、そういったことが考えられると思うのですけれども、その点含めていかがお考えでしょうか。","respondent":"持田河川下水道課長","answer":"そういった中で、やはり舟運というものは区としても進める中で、さまざまなハードル、検討していかなければいけないこともあるという認識ですので、そういったものを一つ一つ解決していきながら、区としての舟運の活性化、これを進めていきたいと考えています。","voiceIndex":145,"id":"exchange-061"},{"speaker":"筒井委員","kind":"意見","question":"非常にご事情あるかと思いますけれども、私非常に東八潮はもったいないと思っていまして、まだ何か未利用状態なので、ぜひ東八潮の利活用ということも含めて、舟運の活性化はぜひともよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":147,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"３１３ページの大崎駅周辺地区再開発、３１５ページ、北品川駅前広場について伺います。住友不動産、日建設計、株式会社都市ネット。再開発準備組合との話し合いなのに、そこの地域に住む住民が１人も参加していないということで、区はかねがね再開発は地元発意によるまちづくりと言っているのですけれども、これ企業主導そのものなのではないですか。企業の計画そのものではないですか。伺います。","respondent":"稲田都市開発課長","answer":"そういうところでございまして、３月１０日におきましては、ちょっと私ども情報が入っておりませんけれども、区のほうとしてはそのような形で、地域の皆様への説明を丁寧にしてくださいということで指導しています。","voiceIndex":149,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"依頼はされているということです。企業と話しているわけではないのです。そして３月中に、このような状況にもかかわらず、Ｆ南地区の都市計画決定をしようとされていると伺いましたが、これはきっぱりとやめていただきたい。準備組合の段階で話し合いが済むまで、都市計画決定をおろすべきではないと思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"新計画の説明についてですけれども、丁寧な説明を行ってくださいと常日頃から、私ども組合のほうには指導しているというところで、今後もそのような形で指導していきたいと考えております。","voiceIndex":151,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"このような再開発計画の都市計画決定は、すべきではないと強く主張したいと思います。２月２７日の建設委員会では、「現在でもパンクしている大崎駅をどうするのか」の質疑が複数の委員からありました。これひどいのではないですか。超過密の問題解消というならば、これ以上の人口集中や、さらなる超高層再開発をやめることこそ、まちづくりをつかさどる区としてとるべき対策ではないのでしょうか。伺います。","respondent":"稲田都市開発課長","answer":"少し具体的なお話をしますと、ＪＲ大崎駅とも話をしながらやってきているところですが、つい最近は改札を２つほど増やした、それからりんかい線のホームというのですか、埼京線のホームというのですか、階段部分を倍の広さに広げた。","voiceIndex":153,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですからこのようなやり方はやめるべきだと、見直すよう求めたいと思います。趣旨採択が３人、不採択４人と賛否が２分する結果となりました。３０ｍ以内にバスベイが設置されているところは。確認させていただきたいのですけれども、西側、国道側にバスベイなり、タクシー乗降ができるスペースを設けることは、法律上明確に禁止されているというわけではないということでよろしいのでしょうか。伺います。","respondent":"東野まちづくり立体化担当課長","answer":"こちら国道側、国道１５号側です。こちらにつきましては、地元の警察、品川警察署、または警視庁、それから東京都の街路計画課、そういったところと協議をした上で、こちらの国道側には都市施設としての駅前広場というものがつくれませんということで回答を得ております。","voiceIndex":155,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"回答を得ているというのは、法律上無理なのですか、明確に禁止されているのですかという確認をしたので、伺わせていただきたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"法的にできないかです。こちらですけれども、法的なところでいきますと、交差点から５ｍ以内には駐停車ができない、そのような法律があります。３０ｍといいますのは、車線変更、こちらをするにあたりまして、教則本などにも書かれているものです。","voiceIndex":157,"id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"ですから、区の判断であえて東側につくるということなのです。北品川と商店街は潤うのでしょうか。住民を追い出してまでつくる価値があるのでしょうか。「広場についても、広場というものが本当に駅の機能として必要なのかどうか。区長に伺いたいのですけれども、どうしてタウンミーティングでは一般質問と違うことを言ったのでしょうか。その場のごまかしだったのでしょうか。伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"区長の趣旨といたしましては、駅は電車の乗り降りに特化したほうがいいというようなところがございました。","voiceIndex":159,"id":"exchange-068"},{"speaker":"渡辺委員","kind":"質問","question":"３１７ページの防犯カメラ、３２１ページ、しながわ水族館、この２点で伺います。３年かけて順次設置とあります。防犯カメラ設置工事で６,８００万円余、公園の数、まずこの平成３０年度という点と、均等に３年間３等分なのかのところ、公園の数、そしてそこに台数。１台当たりのおおむねの単価、機種が統一なのか、あるいは違ってくるのか、この点も含めて教えてください。","respondent":"溝口公園課長","answer":"平成３０年度につきまして、３年間で均等割りしますと、約８５カ所の公園が対象になりますので、年次計画で８５カ所ずつ防犯カメラの設置をしていきたいと考えているものです。","voiceIndex":162,"id":"exchange-069"},{"speaker":"渡辺委員","kind":"質問","question":"人に対する、子どもを初め利用者をいろいろな意味で守っていく、と同時に、やはり最近ニーズが高いもので、ペットのマナーアップのところ、この辺に貢献できるのではないかと期待もするのですが、教えてください。それにやはり文字どおり防犯につながる実績も含めて、あるいはそれがまた未然にという意味もあるかと思いますので、その辺を教えてください。","respondent":"溝口公園課長","answer":"ただ、画像が録画できますので、公園利用者のマナーの悪い方、そういったところの実態といいますか、実際にどういう形で利用しているのか、そういったところの把握というものも可能になってくると思いますので、今後さまざま公園の中でのマナー違反。","voiceIndex":164,"id":"exchange-070"},{"speaker":"渡辺委員","kind":"質問・要望","question":"細かいことはともかく、やはりその時点での予算も含めてベストで、これがコストというものに縛られて、もったいないことにならないように、結果的にはやはりその時点のベストが防犯に対してもいいのではないかという思いで要望します。しながわ水族館について伺います。どのような仕掛けがなされているのか、自然増なのか、実態のところ、まず教えてください。","respondent":"溝口公園課長","answer":"いずれにしましても、さまざまな工夫を凝らしながら、外国人または入館者、そういったものの増加に向けて取り組んできている、そういったものの１つの成果として外国人が増えてきているというふうに捉えているところです。","voiceIndex":166,"id":"exchange-071"},{"speaker":"渡辺委員","kind":"質問","question":"そこで、今後のあり方のところで何点か聞きます。来場者の満足度、外国人の方に特化した中での向上への取組み、ひとつ教えてください。もう１点、細かい点を何点か。その点の考え方。もちろん船の利用もあることですが、それこそ少し前だったら釣り堀的なものとか、このスペースはすごくきれいですし、何か可能性が多くあるのではないかなと思うので、それぞれお知らせください。","respondent":"溝口公園課長","answer":"これにつきましては、今現在、今年ロッカーを改修しまして、大型ロッカーを入れてロッカーで対応しています。ロッカーがいっぱいであれば窓口でも一時預かりという対応、サービスをしていますので、これにつきましては引き続き対応させていただきたいと考えております。","voiceIndex":168,"id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"２９７ページの中段にあります街路灯管理費からの質問です。本区は２００８年ごろにＬＥＤ街路灯導入へ向けて実証実験を行っていましたけれども、本格実施には時期尚早という見解を明らかにいたしました。このＬＥＤ街路灯導入を見送る原因は、コスト高と、そしてまぶしい点がネックだということでした。ネックとなったのはコストと、そしてまぶし過ぎるという点だったとネット上には出ておりました。","respondent":"多並道路課長","answer":"私からはＬＥＤ街路灯についてお答えします。区としましては、平成２２年度の時期ですけれども、街路灯のＬＥＤ化ということでいろいろ検証してまいりました。今委員のご指摘のあったように、当時のＬＥＤの技術としては、輝度といいまして、まぶしさが課題と。","voiceIndex":173,"id":"exchange-073"},{"speaker":"木村委員","kind":"意見","question":"区内には約１万２,４００基弱の街路灯があると思いますけれども、いずれは全てを交換するということであります。それとまた、今ある照明というのは残すような部分というものはあるのかどうかということもお聞かせください。","respondent":"多並道路課長","answer":"５年間かけて水銀灯をＬＥＤ化していくところなのですけれども、それの後も、今お話しさせていただいたとおり、製品がＬＥＤのほうがかなり進んできているところもありますので、区としましてはその後蛍光灯やナトリウム灯についても。","voiceIndex":175,"id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"この明るいまちというものが安全をあらわし、私たちに安心感を与えてくれます。しかし、明かりをあちらこちらにつけ、明るくすればいいというわけではないと思っています。思っていますけれども、理想の夜の姿というのでしょうか、どのような姿が一番理想でしょうか。","respondent":"多並道路課長","answer":"それで、水銀灯をＬＥＤ化するときも、それを踏まえまして、例えば一般の区道が８０ワットの水銀の電灯を使っているとすれば、ＬＥＤはそれに換算して３２ワットということで使って、そのような形で電力、またはＣＯ２削減にも効果があるようなＬＥＤ化ということで進めながら。","voiceIndex":177,"id":"exchange-075"},{"speaker":"木村委員","kind":"提案","question":"人が通れば感知し、明かりがつき、一定時間で消える街路灯が、特に住宅地の路地などにあれば、それほど迷惑にはならず、女性や高齢者、体の不自由な方々が安心して路地を歩くことができると思いますけれども、センサーつき街路灯も、今現在あると言われるかもしれませんが、なければこの提案をさせていただきたいと思いますけれども、いかがでしょうか。","respondent":"多並道路課長","answer":"ただ、委員もご指摘のところは、何というのでしょう、できるところがあるのかという観点で調査させていただきたいと考えています。","voiceIndex":179,"id":"exchange-076"},{"speaker":"木村委員","kind":"意見","question":"今私が言ったのは、本当に住宅街の狭いところなどの電気のことを言ったのですけれども、大通りとか、そういうことではなくて、そういうところであれば可能かどうかということをお聞かせください。","respondent":"多並道路課長","answer":"道路でも、大体木造密集地でも４ｍの道路を確保するということで基本やっています。","voiceIndex":181,"id":"exchange-077"},{"speaker":"木村委員","kind":"質問","question":"ぜひお願いをいたします。お聞きいたしますけれども、この６行下にあります災害時消えない街路灯５０基、６,５６０万円ですが、ネット上には「消えないまちだ君」という街路灯がありますけれども、同じような製品でしょうか。そして、ネット上にはこの予算が６,８８９万円と書かれておりましたが、この違いというものはどういうところにあるのでしょうか。","respondent":"多並道路課長","answer":"今、委員のご指摘ありましたように、町田市で利用している街路灯を我々参考としています。予算については６,５６０万円ということで、これが設置費の経費です。","voiceIndex":183,"id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問","question":"交通安全啓発費から、関連いたしまして自転車事故の保険制度について伺います。昨年９月の定例会で、世田谷区の公明党区議の一般質問に対しまして、土木部長の答弁をちょっと紹介します。先日の課長の答弁だと、「情報を収集していく」というご答弁でしたけれども、世田谷区が新たに制度を開始するというこの情報をつかんでおられますでしょうか。","respondent":"桑波田交通安全担当課長","answer":"それで、本区につきましては、これまで、ほかのまだ未加入の区等にも情報の収集等も行ってまいりまして、世田谷区につきましても７月から、これは金融機関を窓口としてとりあえず実施するというような情報はつかんでおります。","voiceIndex":186,"id":"exchange-079"},{"speaker":"あくつ委員","kind":"確認","question":"品川区にも説明があったということを確認させていただきました。前の決算特別委員会で企画調整課長に確認をしまして、なぜこれ移行したときに品川区は入らなかったのかというところのご答弁で、掛金のわりには支払いのほうが多くなっていたという現状が当時あったということがある。これは特別区が保険の主体であったものですから、そういうことがあったと。そういう判断もあったということを聞いていると。","respondent":"桑波田交通安全担当課長","answer":"実績については６０２件の支払いの実績があったというところまではつかんでいるところです。","voiceIndex":188,"id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認してよかったです。最後に世田谷区で再答弁を求めた際の副区長のご答弁をご紹介します。要するに今回のこの保険、私が求めているものについての特徴というのは、まず保険料に比べて補償が非常に大きいというところ、そしてこれ、年齢にかかわらず入れるです。改めて品川区でも、できるだけ早い段階でこの区民交通傷害保険の導入について検討を進めていただきたいと思いますが、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"区につきましては、引き続き他区の状況や動向を注視しつつ、情報収集に努めて交通安全啓発を普及してまいりたいと考えているところです。","voiceIndex":192,"id":"exchange-081"},{"speaker":"あくつ委員","kind":"提案","question":"区内約５２カ所の学校避難所運営マニュアル、これインターネット上でぜひ公開をしていただきたいと思います。私ども区議会からも、さまざまなご提案をこのマニュアルに関してはさせていただきました。女性の目線、障害者の目線、高齢者の目線、子どもの目線、ペット同行のこと、さまざまなことをご提案してきました。ですからこれはお願いをいたします。このことについてご意見を伺いたいと思います。","respondent":"古巻防災課長","answer":"ただ１点、やはり避難所運営会議が主体でつくるという形をとるというところもありますので、そこは地域の方ともきちんとお話をしていく中で周知が進む、それから避難所運営会議に参加されていないというのか、直接参加されていない方についても。","voiceIndex":194,"id":"exchange-082"},{"speaker":"あくつ委員","kind":"質問・要望","question":"よろしくお願いします。これについて、これは設置物ということで、看板だったのか、ひさしという表記だったのですけれども、時間がないのでまとめて伺ってしまいますが、上からものが降ってくる、これは防ぎようがありません。こうしたことが実際に発生して、小学校５年生の子がけがをしたわけなのですけれども、この点を品川区がどうお考えになっているのか。","respondent":"鈴木建築課長","answer":"この建物につきましても、緊急の対応としてほかに落下物のおそれがあるものがないか、あるいはそのおそれがあるものについては、直ちに撤去指導したところです。","voiceIndex":196,"id":"exchange-083"},{"speaker":"あくつ委員","kind":"質問・要望","question":"すごい数の建物、基準以上のものについての報告義務だと思うのですけれども、あるので、これを例えば行政側が目視をして点検するというのは、なかなか現実難しいと思うのですが、ぎりぎりのところで、これはしっかりと見ていって、指導を徹底していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":198,"id":"exchange-084"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは３２５ページ、住宅・建築物耐震化支援事業について伺いたいと思います。熊本地震から間もなく２年、そして東日本大震災から７年がたちました。先日の質問の中で、木造住宅の耐震化は６８.３％、６８.４％、こういった数字が出されました。進んでいないなと感じます。戸別訪問などもされて頑張っているということですけれども、なぜ進まないのか、理由をどのように考えているのか伺います。","respondent":"鈴木建築課長","answer":"目標としましては平成３２年度までに９５％と。この推移でいっても、９５％達成するところの見込みは、今難しいのですけれども、着実に耐震化は進んでいるです。なかなか耐震化、あるいは建替えということになりますと、やはり費用的なところが一番大きいかと思います。","voiceIndex":200,"id":"exchange-085"},{"speaker":"石田（ち）委員","kind":"質問","question":"費用が大きい部分だと。そして諦め感もあったり、制度を知らないと。こういったところがなかなか進まない原因ということでいいですかね。ですから耐震診断や改修の対象ではなかったわけですけれども、新耐震でも倒壊のおそれがあるという調査結果なども多々出ていますが、区としてはこの新耐震も倒壊のおそれがある、危険があるというような認識は持たれているのでしょうか。","respondent":"鈴木建築課長","answer":"阪神・淡路大震災を受けて、国のほうが平成１２年に木造住宅の接合部の規定を改正いたしました。今回熊本地震においても、その新耐震、平成１２年までの建物について、その接合部について破断があった、建物が乱れたというところは、国の調査結果から出てあります。","voiceIndex":202,"id":"exchange-086"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、新耐震でもそのようなことがあるということは、危険性を認識されているということでよろしいでしょうか。震度６強で倒壊する可能性が高いとされる住宅が６１％、倒壊する可能性があるとされる住宅が２３％と。だからこそ新耐震も耐震診断、また改修、必要があれば改修等の対象に入れるべきだと思うのですけれども、いかがでしょうか。","respondent":"鈴木建築課長","answer":"熊本地震を受けて国のほうが調査をかけまして、平成２９年に、新耐震以降、平成１２年までの建物について、耐震性をチェックする指針を取りまとめてあります。今、建築課の窓口においても、その指針についてＰＲをしています。","voiceIndex":204,"id":"exchange-087"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そしてさらに工事に進むかどうか。診断というものはすごく大事です。私たち、この間ずっと耐震診断の無料化を求めてきているわけです。ですので、やはりその第一歩である耐震診断を無料にしていく、そして自分の家屋が危険なのかどうなのか、程度を知っていくということが大事だということをずっと言ってきているのですけれども、今こそ踏み出していただきたいと思いますが、いかがでしょうか。","respondent":"鈴木建築課長","answer":"この簡易無料診断を使っていただいて、診断に進んでいただいた方も多くあります。先ほどご説明しました新耐震の建物についても、基本的な考え方ですとか、状況については、場合によっては無料診断をお使いいただいて、次に進んでいただくというようなこともあります。","voiceIndex":206,"id":"exchange-088"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、この一般の耐震診断を無料にしている区も、２０１２年の時点で２３区中７区ありました。このようなことになっていきますので、防災という観点から見れば、１つの住宅も大いに公共性はあると思うのです。ですからぜひ無料の耐震診断、進めていただきたい。第一歩にしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木建築課長","answer":"今の事業支援をしっかりＰＲし、耐震化を行っていきたいです。","voiceIndex":208,"id":"exchange-089"},{"speaker":"本多委員","kind":"質問","question":"３３５ページの品川区国民保護計画変更費と、３３０ページ以降の防災費について質問いたします。最初に国民保護計画変更費なのですが、概要をお知らせください。","respondent":"冨澤防災安全担当課長","answer":"国や東京都の国民保護計画が変更されております。さらに区の組織改編への反映など、内容の見直しをする必要性が発生するため、変更するものです。","voiceIndex":211,"id":"exchange-090"},{"speaker":"本多委員","kind":"質問","question":"いろいろこの時代背景等考慮されてだと思うのですが、それで前回の計画変更が平成２４年だったということなのですけれども、いろいろと協議をしていく中で国民保護協議会がありますが、この改定の時期でこの協議会が開かれるのだと思うのですけれども、昨今のいろいろな世の中の動きを見て、何かこの協議会での活動とか、その辺については何か、その変更時だけの協議会ではなくて、何か平時のときの考えとか。","respondent":"冨澤防災安全担当課長","answer":"今、委員のほうからご指摘ございました国民保護協議会につきましては、国民保護法の第４０条第８項に基づきまして、品川区の国民保護協議会条例に基づいて設置をされた機関です。","voiceIndex":213,"id":"exchange-091"},{"speaker":"本多委員","kind":"質問","question":"わかりました。次の質問に行きますが、一般質問で高橋伸明委員がしながわ中央公園ヘリポートの開設の際、陸上自衛隊の多目的ヘリが２機発着をされたことを取り上げました。物資搬送の実地訓練というのでしょうか、そういったことを、有事のときにはこのように活用できるということがもうわかっておりますけれども、平時においての物資搬送、その辺についての考え方はいかがでしょうか。","respondent":"古巻防災課長","answer":"ヘリポートの活用という観点ですけれども、年に一遍何らか、いわゆるヘリコプターを使ったデモンストレーションのようなものができるのかどうか、ちょっとそのあたりは自衛隊のほうとも協議をしていかなければいけないとは思いますけれども、今ご指摘いただいた点につきましても。","voiceIndex":215,"id":"exchange-092"},{"speaker":"本多委員","kind":"質問・要望","question":"備えということで、本当に来てほしくない災害ですが、備えという意味でいざというときにも十分に動きがとれるように、本当に１年に一度ぐらいでいいと思うので、そういった実地訓練が必要かなと思います。２月４日からの大雪により、福井県では９の市町村、新潟県では５の市町村が、災害救助法を適用されました。次の質問に移ります。それと３３５ページの計測震度計更新費についても、概要を教えてください。","respondent":"古巻防災課長","answer":"それから計測震度計につきましてですけれども、こちら設置してから一定年数経ちましたので、今回それを踏まえまして、新しい装置に取り替えるというものでございまして、何か特別な、何といいましょうか、技術的に物すごく改善をするとか、そのようなことではありませんが。","voiceIndex":217,"id":"exchange-093"},{"speaker":"本多委員","kind":"質問","question":"すみません。協定についてももし意見があれば。今の答弁でまとめての答弁だったらそれでいいのですが、もし協定、発電機をつくる企業等との協定等、何かお考えがあれば教えてください。","respondent":"古巻防災課長","answer":"失礼いたしました。協定につきましても、ちょっとまだ具体的にそういった形での協定というものは想定していないところですけれども、お話がございましたら、どういった形で区の災害対策に対応できるか考えながら、結ぶことも検討していきたいと思います。","voiceIndex":221,"id":"exchange-094"},{"speaker":"本多委員","kind":"意見","question":"３３７ページの帰宅困難者対策経費に関連しまして、こちらのほうでも各地域の協議会、構成メンバーがさまざまで、それぞれの地域で取り組まれていると承知しておりますが、昨今、こういった帰宅困難だけでなく、平時においても区内のコンビニのトイレ等を積極的に貸し出しをしていただいていると実感するのですけれども。","respondent":"古巻防災課長","answer":"品川区としましても、さまざまな企業との、そういった帰宅困難者対策、一時滞在施設の提供ですとか、備蓄倉庫の提供ですとか、そういったことを協定として進めておりますので、今後もそういう中で、きちんと帰宅困難者対策を進めていきたいと考えております。","voiceIndex":223,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問","question":"今回シナモロールとの協力というか、協働というのでしょうか、したということで、非常にいいなと思っているのですが、今、マンホーラーというのですか、そのような方々もいらっしゃるということで、このマンホールの観光に絡めていることなので、少し款が違うかもしれませんけれども、これを阪急前に１つということだったのですが、増やしていくというお考えはないのか。これ工法はどうなっているでしょうか。","respondent":"多並道路課長、鈴木文化観光課長、高梨木密整備推進課長","answer":"この検討の中で、今の狭い道路への無電柱化というものも一緒に、技術的なことも支援を受けながら検討していこうということで、まずは基本方針を立てて。年度当初の予定としましては、今開催しております西小山のイルミネーション、こちらのほうに移設をして使う予定だったのですが。それと建替えに際していろいろお悩みをお持ちの方多くいらっしゃいますので、それについては可能な限りその場で相談。","voiceIndex":226,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問・要望","question":"マンホールに関しましては、これからいろいろ適用できることがあると思いますので、文化観光課、他部署のほうと連携を図って進めていただきたいと思います。モニュメントのほうは非常にもったいないです。不燃化１０年プロジェクトについてですが、これ非常に心配をしております。賛成者だけではないではないですか。ですから、そこの危機管理について、体制です。どうしていくのでしょうかということです。","respondent":"高梨木密整備推進課長","answer":"は委託の業者と区職員、担当との間の日々の情報共有、過去このようなことがあったと、それでもう１週間も１カ月もたっているということがないように、毎日このような対応があったがどうだ、もし余り過激な対応があるようであれば、別途またすぐに対応が考えられるような。","voiceIndex":230,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"最後に２９３ページのシェアサイクルです。去年建設委員会で富山市に行政視察に行ってまいりました。設置は行政側ということで先ほどお聞きしました。そのときに富山市のほうは全く運営費に関しては予算立てしていないということなのですが、今回品川区でされる場合は、どのような形で運営をしていただくのでしょうか。運営に対する助成であるとか、そのような考え等々はあるのかどうかを聞きたいと思います。","respondent":"今井土木管理課長","answer":"運営に対する助成は一切ございません。これは９区につきましては、運営についての助成というものは今していないと聞いております。","voiceIndex":232,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"富山市のケースなので品川区とはビジネスモデルが違うのかもしれませんけれども、ここは広告収入を得ながら、要はシェアサイクルのステーションのところに広告を出して、それの収入によって運営費用を賄っているというような流れでありました。そのような形で許容範囲を広げていけるのかどうかということを最後にお聞きしたいと思います。","respondent":"今井土木管理課長","answer":"今ご指摘のとおり、自転車のシェアサイクル、現在は品川区ですけれども、広域連携になりますと広告物の収入のほうも活用してまいります。","voiceIndex":234,"id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"私からは３１１ページ、防災街区整備事業、３３５ページ、支援物資受援体制再構築費について伺いたいと思います。なかなか全国で唯一２例というところで、簡単にできる事業ではないのかなというような見方もできるのですが、品川区でこの２つの事例が進められた背景、また理由についてお伺いしたいと思います。","respondent":"高梨木密整備推進課長","answer":"そういったことが特に荏原地域の区民の方々にも深く根づいておりまして、しっかり自分たちの住むまちをどうにかしたいというような防災意識が非常に高いといったところが、この防災街区整備事業を早期に実現に結びつけられた１つの要因ではないかと。","voiceIndex":237,"id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"この防災街区整備事業の今後の可能性について、現状どのように考えていらっしゃるかお伺いいたします。","respondent":"高梨木密整備推進課長","answer":"防災街区整備事業を行うための要件として法定要件幾つかありますが、国からの補助金を当然入れて事業を行うわけなのですけれども、その要件の１つとして、現在区で４地区、来年度から５地区事業実施予定です。密集事業と言われる事業区域に入っていることが要件となっております。","voiceIndex":239,"id":"exchange-101"},{"speaker":"塚本委員","kind":"質問・要望","question":"密集市街地の解消、危険度の解消ということで、いろいろな手法、適切な手法を活かしながら進めていただきたいと思います。この支援物資の受援体制の再構築というところで、どういったところを課題と捉えているのか。事業としてはこれは委託をされるということで、この委託の結果としての成果物というか、どういった委託をすることで何を求めているのかというところをお伺いいたします。","respondent":"古巻防災課長","answer":"そういった意味でいうと、最終的には委託ですけれども、例えば地域内輸送拠点、現状の計画でいいますと、東京都なり、国から地域内輸送拠点というところ、区役所でありますとか、大井競馬場でありますとか、そういったところを地域防災計画上では指定していますが。","voiceIndex":241,"id":"exchange-102"},{"speaker":"松永委員","kind":"質問・要望","question":"最初に３０１ページの大井競馬場前駅の接続設計委託、７４０万円について伺います。そこで、今年度のこの大井競馬場前駅の接続設計委託についてですが、ぜひ駅から勝島橋に直結する形にしていただきたいという要望だったのですけれども、この設計内容がもしわかっていたら、どのように変わるのか、その内容についてお知らせください。先ほどの質疑にもありましたが、自転車レーンについてです。","respondent":"多並道路課長","answer":"この経費としましては、来年度にエレベーターの設置をする際に、どうしてもあそこの勝島歩道橋が駅舎と直結しているところがありますので、東京モノレールに協定を結んで実施していただくのに。","voiceIndex":245,"id":"exchange-103"},{"speaker":"松永委員","kind":"質問・要望","question":"今後、東京２０２０大会が控えており、またそこにベビーカー等で来られる方、またシェアサイクルも全区展開されて、オリンピック会場周辺地区でもありますので、ぜひ歩道の整備、自転車レーンの整備をしっかりと取り組んでいただけるよう協議していただきたいと要望いたします。","respondent":"多並道路課長","answer":"オリンピック会場周辺の道路の整備ですけれども、今委員お話しのとおり、今は車道が２車線、停車帯があるところですが、そこの今ある一番左側の車線のところに自転車の専用レーンということで、２ｍの幅で設置する予定としております。","voiceIndex":247,"id":"exchange-104"},{"speaker":"松永委員","kind":"質問","question":"以前ペットの同行避難について昨年の第３回定例会で質問した際に、本区では具体的な対策が避難所運営マニュアルに明記されるよう取組みを進めていくとのことでした。平成３０年度のこの運営マニュアルの更新について、その更新された内容についてお知らせください。あわせて以前ペットとの同行避難マニュアルにある避難所は９カ所だと伺いました。現在どのようになっているのか、あわせて伺います。","respondent":"古巻防災課長","answer":"避難所運営マニュアルの更新につきましてですけれども、ペットの件につきましては、昨年度来さまざまご意見いただいているところでもありますし、またそういった意味で環境省のガイドライン等についても周知を進めていくというようなことで考えているところですが。","voiceIndex":249,"id":"exchange-105"},{"speaker":"松永委員","kind":"質問","question":"先ほども質疑の中で、避難所連絡会議のようなものが行われていると伺いましたが、年にどのくらい行われているのかお伺いします。その話し合いの内容の中に、ペットの同行避難について話し合われていると思うのですけれども、答えられる範囲でいいので、この会議の内容についてお知らせください。","respondent":"古巻防災課長","answer":"ただ、来年度につきましては、こういった運営マニュアルの更新作業もありますので、ちょっとどういった形で進めるかというのは、今後各避難所連絡会議との調整になりますけれども、そういった意味で集まって協議する機会というものはたくさん増えていくのかと考えています。","voiceIndex":251,"id":"exchange-106"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私は、３０５ページ、河川費の中で舟運社会実験結果検討委託に関連して、それから３１５ページ、都市計画費の大井町駅周辺地区再開発事業についてお聞きします。おのおの概略を教えてください。それから舟運関係です。先ほども少し質問が出ていましたけれども、定期・不定期航路の開設についての検討状況、これがどのような形になっていくのか、その２点について教えてください。","respondent":"稲田都市開発課長、持田河川下水道課長","answer":"区の用地もそちらに保有しているというところでございまして、この用地におきまして、共同検討を現在進めているです。内容的には都市基盤の検討、道路の検討、そういうところをさらに進めていきたいと考えております。舟運の定期・不定期というお話がございまして、２地点で不特定多数のお客様を乗せておろすということになりますと、これは定期航路事業という認可が必要になってくるです。","voiceIndex":256,"id":"exchange-107"},{"speaker":"鈴木（真）委員","kind":"質問","question":"舟運の関係です。これからやっていくのに、不定期のほうならば可能性があると考えていけばいいのか。例えば小さな屋形船でも入っていけるというようなことで、観光のにぎわいというものができるならいいと思うのですけれども、そこまでは考えていないのかどうかということが１点です。これに対して区がどのように評価しているのか、またいつごろまでこの計画が進んでいくのか、その点を教えてください。","respondent":"持田河川下水道課長、稲田都市開発課長","answer":"今、区としましては、いきなり定期事業、水上バスのような形というものは難しいかと思ってありますが、例えば貸切のような形で２点間でお客様を乗せてこちらに持っていくというような形の場所を増やしていくという形ですとか。そういうところで、そのような検討も今やっているです。","voiceIndex":259,"id":"exchange-108"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それからこちらの広町のほうです。逆に言うと、今度こちらに人が入るような素晴しい施設ができると思うのですけれども、これがいつごろまでやっていらっしゃるのかということが、そういう意味の聞き方だったのですが、終了時期というのはまだＪＲも発表していないのかどうか、その辺を教えてください。これを区として、この辺の道路をどのように考えているかについても教えてください。","respondent":"持田河川下水道課長、稲田都市開発課長","answer":"ですので、これを設置するにあたりましては、当然東京都のほうと防災船着場計画に基づいた形ということで協議していますし、また実際これを利用する、災害時利用する場合におきましても。そういうところも含めまして考えていくというところで、入口、あそこの１つしかないのですけれども、その辺の安全対策等はＪＲのほうにも申し入れていきたいと考えています。","voiceIndex":262,"id":"exchange-109"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"広町の計画等、先ほどお話あった区との計画、これを一体になってやっていっていただくのと同時に、大井町全体を考えたときに、今ばらばらの建物の開発、きゅりあんですとか、阪急、イトーヨーカ堂、ばらばらになっている感じが非常にしています。ですからせっかくこれだけの大きな土地と区の土地を考えたときに、Ｅ地区も一体としていい形に進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":265,"id":"exchange-110"},{"speaker":"浅野委員","kind":"質問","question":"２９７ページの道路安全施設費、それと２９９ページの旗の台駅周辺バリアフリー工事費について質問します。その方も涙ぐんでいました。今、積極的にこのゾーン３０を設置していただいておりますけれども、今何カ所ぐらい設置をしているのか教えてください。特に危険が想定されるところについては、子どもの安全を見守るなどしていただければと思いますが、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"子どもの安全対策につきましては、区のほうとしましてはヒヤリハット地図を活用した学校現場での、お互いに危険箇所を認識し合うような教育でありますとか、もしくは親子安全教室等で、親と一緒に自転車の走行について学んでいただく、もしくは学校。","voiceIndex":267,"id":"exchange-111"},{"speaker":"浅野委員","kind":"質問","question":"ゾーン３０、これは設置をされるということで、今伺いますと品川区と目黒区にもわたってというふうに聞こえたのですけれども、このような設置の仕方もあるのだということを改めて感じたところであります。南口につきましては既に障害者福祉会館のほう、こちらのほうが設置をされていると聞いておりますので、この２つの線ができれば、ある程度安心して歩きながら病院に向かえるのかなと思います。","respondent":"多並道路課長","answer":"延長としましては約１５０ｍということで、昭和医大のほうへ向かう方が安心・安全にご利用いただけるようにということで設置してまいるものです。","voiceIndex":269,"id":"exchange-112"},{"speaker":"浅野委員","kind":"質問","question":"緑色というふうに伺いました。気になっているところが、中原街道とその１本東側になりますか、細い道があります。この辺でやはり事故が起きておりますので、この辺もある意味では注意をしなければいけないところかなと思います。このような中で、区民の方、また病気を持たれている方が事故に遭わないような対策も、ぜひとも検討していただければと思うのですが、いかがでしょうか。","respondent":"多並道路課長","answer":"旗の台駅の周辺につきましては、今までまち歩き等をしていただきながら、そのバリアフリーを進める部分ということで検討していただき、特定事業という形で区だけではなく東京都の道路も含めて、ネットワークを持って整備を進めていこうとまとめているところです。","voiceIndex":271,"id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"３２９ページの区営住宅管理費、そして３１７ページの公園・児童遊園整備費、３２３ページの公衆便所整備費についてお伺いしたいと思います。区営住宅についてなのですけれども、区営住宅は多くが都営住宅を移管したものだと思うのですが、家賃の減免制度ですとか、さまざまな仕組みや運営は、都営住宅に準ずるということになっているのかについて、まずお聞かせください。","respondent":"長尾住宅課長","answer":"区営住宅の運用につきましては、区のほうで条例と規則を持って運用しておりますので、全てが都営住宅と同じではないのですが、おおむね都営住宅と同じような方式をとっているところです。","voiceIndex":274,"id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区営住宅も倍率が高くて、なかなか当たらないということなのですけれども、やっと当たって喜んだものの、連帯保証人がいなくてどうしたらいいかという相談を受けたのですが、この連帯保証人について少し伺いたいと思います。","respondent":"長尾住宅課長","answer":"連帯保証人の件です。品川区では原則的には個人の連帯保証人の方を立てていただいて、入居の手続の際に確認をしています。しかし、入居されようとされている方の中で、やはり個人の連帯保証人を立てることが難しいご事情というものをお持ちの方もいらっしゃいます。","voiceIndex":276,"id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"６５歳以上の世帯の方、また名義人が特別障害者の方、それから生活保護世帯の方、これは保証人免除申請書を出せば、連帯保証人をつけなくても都営住宅に入れるという仕組みになっているということなのですけれども、私はぜひ区営住宅でも、都営住宅と同様に連帯保証人を免除する、このような形で免除制度をつくっていただきたいと思うのですが、いかがでしょうか。","respondent":"長尾住宅課長","answer":"ご相談の際に、事前の入居が決まった後ではなくて、入居が決まる前の事前の窓口の相談などでも、そういった連帯保証人のことでお困りであれば、法人の連帯保証人のお話もご紹介しながら相談を受けているところですので、今のところそういった免除のところにつきましては。","voiceIndex":278,"id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"連帯保証人というのも、ある程度所得がなければ連帯保証人にもなれないということもありますし、またこの法人を使うということなのですけれども、この保証会社を使う場合は年間１万円、毎年１万円ずつかかるわけです。これは品川区の区営住宅としては、このような制度は移管されたにもかかわらず、なぜされないのか、ぜひしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"長尾住宅課長","answer":"都営住宅の中で住戸の中の手すり設置等を行っている事業がありますけれども、区営住宅につきましては、基本的には建替えの際にバリアフリー化であるとか、住戸内、共用部分を含めて居住環境をよくするであるとか、そういったことを対応しております。","voiceIndex":280,"id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それにまだまだほど遠いという状況なのですが、この目標をいつまでにどう達成しようという計画はないのかという点と、それからもう一つは、２０１５年のときに公園のない町会に公園を整備してほしいということでの質問をしたときには、木密の網かけ地域から整備していくというような答弁だったと思うのですけれども、これからは網かけされていない地域ということは、補助金が出ない。","respondent":"溝口公園課長","answer":"公園の整備につきましては、やはりさまざまな世代、または地域の要望、幅広い需要、そういったものを踏まえながら、また利用しやすい配置、また公園のない町会、そういったところも１つの観点と踏まえて。","voiceIndex":282,"id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これから網かけされていない町会にも公園を整備していくということでは、本当に大歓迎なので、ぜひこれを進めていただきたいと思うのですけれども、本当に公園がないために、一時集合場所にも困って、マンションの駐車場などに集まって防災訓練にも出かけるという、そのような状況になって大変公園のない町会はご苦労されていますので、私は土地を探すということも含めて。","respondent":"溝口公園課長","answer":"今後の公園の取組みです。さまざまいろいろ、地域の中でご要望があると思います。私ども公園課としては、適正な配置というものも１つの大きな視点です。そういったものも踏まえながら、公園整備には今後も引き続き取り組んでいきたいと考えているものです。","voiceIndex":284,"id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に公衆トイレについて伺いたいと思います。地域で荏原町商店街の中にある荏原橋公衆トイレが、男女とも和式トイレしかなくて、もう本当に膝や腰の痛みのある人が使えない、商店街に買い物に来た高齢者の方も使えないということで、ぜひこれを改修してほしいという要望が出されているのですけれども、改修計画があるのか、またなければぜひつくっていただきたい。","respondent":"溝口公園課長","answer":"特におもてなしトイレ事業ということで、重点的に取り組んでおりますので、まずはそれをしっかり取り組んでいきたい。だれでもトイレの設置で考えますと、１基当たり大体１,０００万円ぐらいかかるというのが、今現状です。","voiceIndex":286,"id":"exchange-120"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私からは３２１ページ、しながわ水族館から行きたいと考えています。３０人ぐらい子どもいましたけれども、大変喜んでいた。その中で多分、そのときも伺ったのだけれども、利用率は非常に低いと聞きました。そういうせっかくいい財産があるのであるから、そのようなものをいい活用の仕方をしたほうがいいと思うのだけれども、ぜひそういう活用をしていただきたいと思うのですが、お考えをお聞きします。","respondent":"溝口公園課長","answer":"水族館利用者の拡大、または知ってもらう、そういった中の一環としてツアーを組む、そういったところも１つの考え方としてはあると思います。文化観光課、観光部署とも十分連携しながら、そういったものについてはしっかり検討していきたいと考えているところです。","voiceIndex":290,"id":"exchange-121"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"あれはあれですごくよかったなと思っていますので、ぜひ有効活用していただきたいと思います。このような形の、いろいろ１年間つながるような考え方を持ってやっていきたいというか、我々もその中の組織づくりに、地域の中でいろいろ意見を言ってやっていきたいと思っていますけれども、ぜひ改めてそういう形で全体的な支援をして、水辺をこれから活性化していくよという意気込みをまず伺いたいと思います。","respondent":"持田河川下水道課長","answer":"なかなか今、全部それを統一した形で動かせているかというと、ちょっと動かし切れていないということは事実として認めたいと思いますので、そういった部分も含めまして水辺の活用、ハードだけではなくてソフトの部分についてもしっかり取り組んでまいりたいと思ってあります。","voiceIndex":292,"id":"exchange-122"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"こういう話をしていくとなると、観光協会もその１つかもしれないけれども、今そういう１つの単体のイベント等には、区もいろいろご協力をいただいて、何か最初から、スタートのときからいろいろ一緒にご意見を聞いていただいたり、一緒にこういうことをしていきますよ、こういうところはこういうクリアをしていきましょうということはやっていただいているのだけれども、面で見たときに。","respondent":"持田河川下水道課長、鈴木文化観光課長","answer":"区内、そういった観光の面からも盛り上げていくような、そういった組織体を通じまして、しっかり水辺のほう取り組んでまいりたいと思います。ご指摘の組織体ですが、今、河川下水道課長から答弁申し上げましたように、観光振興協議会のほうで水辺について検討しています。河川下水道課のハード整備に合わせまして、連携をしてしっかりと進めていきたいと考えております。","voiceIndex":294,"id":"exchange-123"},{"speaker":"石田（秀）委員","kind":"提案","question":"すみません。羽田もそのようにやるといったときは大田区が引き受けたけれども、ほかのところはきちんとデベロッパーもゼネコンもついて提案型でいったのに、ＪＲ東日本とだけは組みたくないというデベロッパーもゼネコンも多くて、なかなかそのような話がある。ぜひそれは区としていろいろやっていただきたい。伺うところによると、ＪＲ東日本は東急は余り、嫌だなという感じもあるかもしれない。","respondent":"稲田都市開発課長","answer":"そのようなところでやっているところです。ご指摘のように東急電鉄、この地区は東急電鉄が２６号線との間に通っているということにおきましては、東急電鉄を抜きにも語れないです。この広町地区に関してはそのようなことで、協議はしていくという状況です。","voiceIndex":297,"id":"exchange-124"},{"speaker":"石田（秀）委員","kind":"意見","question":"心配しただけあれかもしれませんが、優秀なスタッフが今やっていただいているので、ぜひ今のお言葉どおりやっていただければと思います。よろしくお願いします。それから最後に１つだけ、３１５ページの京急北品川駅前広場の話を少しさせてください。駅前広場計画が発表された際、地域では大半の方が賛成でした。あのようなところに交通広場は要らないだろうと。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":299,"id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"金網の部分でボールが飛び出さないような形にという地域の方々のお声があるのですけれども、そのあたりはいかがでしょうか。それから水神公園は駐輪場との関連で整備されているのですが、あそこは公園の中がほぼ歩道のような形で皆さんご利用になっていて、通行する方が多いということで、その通行の確保を十分にして工事を進めていただきたいのですけれども、いかがでしょうか。","respondent":"中村都市計画課長、持田河川下水道課長、溝口公園課長","answer":"そういった中で、このモノレール駅のキャパシティと、それから通行量、こういったものを検討していると聞いている中で。その後の土地の利用につきましては、現段階ではちょっと決まっていないといいましょうか、その段階で区としてどのような利用がいいのかということを。工事中につきましても、そういったものに配慮しながら進めていきたいと考えているところです。","voiceIndex":301,"id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ちょっと駅自体のほうは改修がないということなので、これは区のほうからも東京モノレールのほうに、その後の利用も含めて改修のほうを、バリアフリーも含めて言っていっていただきたいと思います。このようなドライブレコーダーの義務化は、トラック、バス、タクシーは国の助成がありますけれども、そういった観点から、このようなドライブレコーダーの設置助成について交通安全の観点でいかがでしょうか。","respondent":"溝口公園課長、桑波田交通安全担当課長","answer":"委員ご指摘のかいぼりで人が入ってというお話ですが、実際今現在、水質をきれいにするために硫酸銅等を入れて水質浄化している関係で、なかなか人が入ってそこを調査する、そういったところ。区としましては、企業に対しても、警察のほうと連携しながら安全教室、そういった注意喚起等を実施しておりますので、今後の車の性能の向上に合わせて状況等をよく注視しながら、今後の調査対象。","voiceIndex":307,"id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区民公園のほうは水に親しめるような勝島の海になることを要望いたします。ドライブレコーダーのほうはぜひ検討して、交通安全、防犯について寄与するような仕組みをつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":310,"id":"exchange-128"},{"speaker":"若林委員","kind":"質問・要望","question":"そのための事業であるということですが、この空間の確保というのは、具体的にどういうことなのか確認しておきたいと思います。項目で３点目に、汚泥の浚渫委託が３０３ページに載っておりますけれども、これは毎年いつ、時期はいつごろやっておられるかということを確認させてください。今後どのようなニーズを捉え、また対応されるか確認をさせていただきたいと思います。","respondent":"稲田都市開発課長、高梨木密整備推進課長、持田河川下水道課長、長尾住宅課長","answer":"平成２２年に初年度開催しているところですが、手元のほうの資料では、平成２６年度からの実績をお知らせしますと、平成２６年度。避難道路機能強化事業についてですが、この事業は広域避難場所である大井競馬場、しながわ区民公園までの避難路であります滝王子通りの幅員を。この整備のときに、やはりそういった汚泥の浚渫等を一緒に行うことで、実際に船が着きやすくなると考えてございまして。","voiceIndex":312,"id":"exchange-129"},{"speaker":"若林委員","kind":"質問・要望","question":"水辺の利活用では、このカウントの仕方は毎年同じカウントをされているのかどうか。平成２７年から平成２８年が一気に倍ですよね。２６万人から４８万人。ぜひ周辺の、そのような民間の力を、行政の方にも、またそういう組合の方にも、地域の方にも捉えていただいて、より地域が発展し、また水運、舟運を使った取組みが相乗効果でいい結果が出るように、これは要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":317,"id":"exchange-130"},{"speaker":"伊藤委員","kind":"質問","question":"私は５４７ページ、災害復旧対策費に関連をして、それから２９５ページ、水辺千本桜に関連して質問します。災害復旧のほうですけれども、これは避難所開設、運営等々の項目があります。誰がこうしていくと。その必要な手続の担保と、それからこの予算の根拠となる避難者数等の根拠はどこから来たのでしょうか。幾つか質問します。答弁お願いいたします。","respondent":"古巻防災課長","answer":"避難所の開設に関してですけれども、緊急事態の定義といいましょうか、考え方ですが、この特別会計で対応する事態につきましては、おおよそ激甚災害に指定されるような災害が発生した場合というようなことで想定をしております。","voiceIndex":319,"id":"exchange-131"},{"speaker":"伊藤委員","kind":"質問","question":"そういう、まさに緊急のときの想定だと思うのですけれども、今ご指摘がありました。こういう予算もある、それから計上もされている。ではその支払いをするときに具体的な手順をもう少し教えていただけませんでしょうか。お願いいたします。","respondent":"秋山財政課長","answer":"ある程度の機能は残っているなということで、通常の支払いですとかいうところを想定はしているわけですけれども、ただそのような緊急の事態の中で、どういう支出命令ですとか、支出負担行為とかいうところまでは、通常のルートでやるということは想定しておりますけれども。","voiceIndex":321,"id":"exchange-132"},{"speaker":"伊藤委員","kind":"確認","question":"要はそういうところなのです。これも同じような意味で、この緊急時にフル活用した、例えばどこそこの道路が緊急にあけなければいけないということについて、そこに人材を投入していくなり、そのような緊急時の判断、それから指示、命令というものは当然迅速かつ合理的に行うべきと思うのですが、それが具体的に対応できる体制はできているのでしょうかという確認をお願いいたします。","respondent":"古巻防災課長","answer":"緊急時のそういった指示命令系統につきましては、災害対策本部という組織において、それぞれ所管が対応してきちんと状況に応じた対応をしていくという形では、体制はできていると考えております。","voiceIndex":323,"id":"exchange-133"},{"speaker":"伊藤委員","kind":"質問","question":"すみません、私の質問が悪かったかもしれませんけれども、区内外のさまざまな団体と連携しているわけです。協定を結んでいますよね。だからそこの団体とうまく調整をとって、そこに必要な人材と機材を投入していく体制をつくっていただけますでしょうかという質問なので、改めて答弁をお願いいたします。","respondent":"古巻防災課長","answer":"協定、さまざま結んですけれども、まず協定に関しては、連絡先等をきちんと確認をするということもやっておりますし、そういった意味でそこでどのような連絡をとるのか、何をどういった形で協定の履行をお願いするのかということにつきまして。","voiceIndex":325,"id":"exchange-134"},{"speaker":"伊藤委員","kind":"質問","question":"目黒川が先行することは理解しました。そうしたら、例えば品川区の寄付者の名前を現場付近に掲げる、例えばしながわ中央公園も出ていましたね、寄付者の名前が。あのようなイメージを検討してみてはどうですかということ。将来は、やはりこの水辺全域も考えていくべきだと思うのですが、改めて品川区のお考えをお聞かせください。お願いいたします。","respondent":"多並道路課長","answer":"ほかの、今のご提案あったような天王洲等も踏まえながら、ご意見をお伺いしながら、このより充実させる方法については検討していきたいと思います。","voiceIndex":329,"id":"exchange-135"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは３１３ページの五反田と大崎のさまざまなコーディネート等についてと、５４７ページ、災害復旧事業費に関連して、それと３３７ページ、避難所管理費、運営マニュアル更新支援費についてお伺いします。そういった状況下において、誰がその権限を持って最終的に判断ができるのかということをお聞かせください。","respondent":"稲田都市開発課長","answer":"それからもう１個の五反田駅周辺整備方針検討業務委託、これは我々担当の間ではアクションプランなどというように呼んでいるのですけれども、五反田駅を中心としましていろいろとまちづくり、ホテル計画があったり。","voiceIndex":332,"id":"exchange-136"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"五反田地区ですが、まちづくりを得意としているところに委託というようにお伺いをしましたけれども、どのように地域の方や、例えば今五反田はそれこそ五反田バレーという新しい言葉や動きがある中で、その方たちや、また駅を中心にというのであれば、どのようにＪＲと話し合いをしていくのかということが見えてこないので、その辺をどうするのかお聞かせください。","respondent":"古巻防災課長、稲田都市開発課長","answer":"それからマニュアルについては、まだちょっと進め方等具体的にこれから業者と話していく中身ですので、形のあるものとして示していくのか、もう少しラフな資料として項目を列挙して。周辺整備方針検討におきましては、現状の課題とか、問題点とか、そういうものをまずは洗い出していくという段階で、どうやっていこうかというところを考えていくというところでございまして、そういうものも含みまして。","voiceIndex":337,"id":"exchange-137"},{"speaker":"石田（し）委員","kind":"質問","question":"五反田ですが、大崎と五反田の東のほうは連携をしているのですけれども、やはり大崎と五反田というのは割と近いのです。ですから、ぜひ総合的にいろいろと検討していただければなと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":340,"id":"exchange-138"},{"speaker":"南委員","kind":"質問","question":"３１１ページの八潮地区の将来像検討経費、２つ目は３３４ページの防災費に関して伺います。品川区は、八潮の現状をどうつかんで、どう認識しているのか、その上で将来像検討とはどのような構想をしようとしているのか伺いたいと思います。そのためにこの間どのような活動をしてきたのか、まちづくり検討経費も計上してきていたと考えていますので、この間の活動経過を教えてください。","respondent":"稲田都市開発課長","answer":"今年度、八潮地区のまちづくり検討業務ということでやってきておるのですが、まず庁内の関係各課に声をかけまして、関連する部署、１８部署ほど声をかけまして、まずは現状の課題等をお聞きしたです。","voiceIndex":342,"id":"exchange-139"},{"speaker":"南委員","kind":"質問・要望","question":"それで、そういう経過を経て今日に至っているわけですけれども、やはりこれからどうしようとするのか、何をどのようにしようとするのか、そこが一番大事なわけなのです。例えば交通問題です。したがって、そういう方々の参加、あるいはいろいろな活動をしている八潮の方々のさまざまな場面での意見を聞く場、これもぜひ設定をしていただきたいと考えていますけれども、その点についていかがでしょうか。","respondent":"稲田都市開発課長","answer":"区の関係各課においても、ハード面だけではなくソフト面についてもより検討すべきだとか、人口動向を考えてやるべきだとか、八潮地区の地域性をよく把握して検討すべきというような意見も出ております。","voiceIndex":344,"id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"管理組合も入れてほしいというか、そういう方々にも八潮のまちづくりですから、意見をぜひ聞く場を持ってほしいと思っているのですが、そこの答弁がなかったような気がするので、改めて確認をさせていただきたいと思います。地域に作成を任せていては進んでいかないという認識を持っているのかなと私は思ったのですけれども、そのあたりについて改めて伺いたいと思います。","respondent":"稲田都市開発課長、古巻防災課長","answer":"オリンピック・パラリンピックの会場が近くにあるというところにおきましても、そのような課題等々、ほかの課題もあると思われますので、そういうご意見もきちんと聞きながら、今後進めていきたいと考えております。避難行動要支援者の支援体制づくりですけれども、代表質問の中でお答えをしておりますことですが、内閣府のガイドラインに従ったものですので、地域が主体にというのは、これは変わらぬ区の姿勢でありますけれども。","voiceIndex":346,"id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"誤解なく受けとめていただきたいと思います。作成が進まない理由は、そういったこともあるのではないかと思っているのですが、その辺の区の見解を伺います。それと最後に、要支援、支援の必要な方には避難しなくても済むように、住宅の耐震化や、あるいは在宅避難を可能にする、そのような体制をつくることも大事だと考えていますので、その点についてご意見を伺います。ご答弁お願いします。","respondent":"古巻防災課長","answer":"それから避難しなくて済むという部分につきましても、これは例えば障害者の方ですとか、そういった方についてはそのようなことも含めて、家具の転倒落下防止の対策を進めるとか、そういったことも周知をしていますので。","voiceIndex":349,"id":"exchange-142"},{"speaker":"こんの委員","kind":"確認","question":"私からは、３３５ページの防災行政無線管理費、２点目が３１９ページの浜川公園改修工事、それから３２１ページの鈴ヶ森道路児童遊園バリアフリー化工事、時間がありましたらば、３３７ページの避難所管理費からお伺いしたいと思います。防災行政無線ですけれども、こちらは昨年の１１月の建設委員会でも報告をされた事業ですので、議事録も確認をさせていただきました。","respondent":"古巻防災課長","answer":"それから１７局ということで答弁をさせていただいているかと思いますけれども、増設する場所につきましては、基本的には聞き取るのが難しい地域について増設をして、今まで聞きづらかった部分を補完していこうという考え方です。","voiceIndex":352,"id":"exchange-143"},{"speaker":"こんの委員","kind":"質問","question":"要は設置場所の設定の考え方をお聞きしました。ヤマダ電機側はあるのですけれども、阪急側が実はなくて、この間の３・１１の２時４６分、あのときの放送が全く大井町駅は聞こえていませんでした。ですから、ここはどのように考えられているのか、そうしたところ、いわゆる場所の設定、その視点、こことここ、確かに聞きづらいところなのですが、そこの考え方をもう一度お伺いしたいと思います。","respondent":"古巻防災課長","answer":"今ご指摘いただきました大井町西口です。阪急側ということですけれども、確かにこのエリアについてはスピーカーは設置がされていなかったというところで、現状ではここにも増設をする予定で、今計画を考えております。","voiceIndex":354,"id":"exchange-144"},{"speaker":"こんの委員","kind":"質問・要望","question":"そのとおりだと思います。大井町に限らず、五反田はどうなのか、あるいは大崎はどうなのか、その辺のところも見ていただきながら、特に鉄道の駅というところは必須の場所かなと思いますので、これから１７局だけが増設をされる、デジタル化を全部するにあたって１７局増設ですので、それだけで果たして空白地帯は足りるのでしょうかというところが気になりますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"１７カ所の選定ですけれども、平成２７年度になりますか、事前にそういった調査を半年ほどかけてやっておりますが、そういった中でそのような聞こえづらい地域については全て確認をして、それにきちんと対応できるような計画を今立てているところです。","voiceIndex":356,"id":"exchange-145"},{"speaker":"こんの委員","kind":"質問","question":"ぜひよろしくお願いいたします。次に参ります。鈴ヶ森の児童遊園は、どこの場所をどのような形でバリアフリーをするのかということと、それから先ほどつる委員が公園のユニバーサルデザイン化の話をしましたが、この児童遊園にもそういう視点を盛り込むというのは考えられるのかどうなのか、その点をお伺いしたいと思います。","respondent":"溝口公園課長","answer":"中につきましては特に、もう一つ水飲みが古くなっておりますし、バリアフリー対応になっておりませんので、その改修をやっていくということで考えているものでございまして、必要最小限のバリアフリー化工事を今回考えているところです。","voiceIndex":358,"id":"exchange-146"},{"speaker":"こんの委員","kind":"質問","question":"それで、このユニバーサルデザインの考え方というのは、いわゆる障害者の方に優しいまちづくりは全ての方に優しいまち、そうした考え方からすると、公園は特化したところだけがユニバーサルデザインではなくて、全てのところにそうした視点を持った公園というものを、今後改修のときなのでしょうか、含めてこうした視線を持っていくことが大事であると考えますが、ご見解をお聞かせください。","respondent":"溝口公園課長","answer":"これまでも公園の段差解消ですとか、園路の段差解消、そういったものも取り組んできたところです。今後も引き続きバリアフリー、またはユニバーサルデザイン、そういった公園の整備というものは取り組んでいきたいと考えているところです。","voiceIndex":360,"id":"exchange-147"},{"speaker":"渡部委員","kind":"質問","question":"三、四年前だったでしょうか、中延小学校がかなり立派な運営マニュアルを町会の方々と協力し合ってつくっていらっしゃった。それと街路樹です。街路樹、桜に限らずさまざま考えていければと私も考えているのですが、この辺どういうことなのか。これを聞くにあたって、課長にもし教えていただければといいましょうか、品川区の街路樹、ここが自慢だぞというようなものがあれば、聞かせてほしい。","respondent":"古巻防災課長、多並道路課長","answer":"進め方ですけれども、避難行動要支援者の支援体制の補助業務でありますが、一応現状では昨年度から始めまして、５カ年で各１年間で５団体ずつの支援をしていくということで。街路樹の桜以外の管理のあり方です。健全度調査ということで計上していますのは、街路樹全部で３,９９９本とお話ししました。それを毎年４００本ずつ健全度を確認いたしまして、チェックをしていこうというのがこの経緯です。","voiceIndex":363,"id":"exchange-148"},{"speaker":"渡部委員","kind":"質問","question":"ですので、そこに千本桜を含むになっていましたから、何か大がかりな、桜に限らずなのかなと思ったので、その辺をもう１回聞かせていただければと思うのと、実は街路樹、なぜ聞きたかったか。表参道もたしかケヤキだったし、今六本木もけやき坂スタジオというぐらいですから、余り見たことはないですけれども、あそこもそうなのでしょうね。これはないです、よそに。街路樹のほうだけお願いいたします。","respondent":"多並道路課長","answer":"それ以外に今の、今後の長いスパンで並木道という考え方ですけれども、一番大きいのは都市計画道路など新しい道路をつくるとき、または再開発によって新しい道路ができるときなど、いろいろな機会を捉えながら、今の委員のご指摘の内容を踏まえながら検討していきたい。","voiceIndex":366,"id":"exchange-149"},{"speaker":"渡部委員","kind":"質問・要望","question":"桜も春先と、あときれいに赤くなった落葉前などもきれいですので、それはそれでしっかり進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":368,"id":"exchange-150"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1082#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":123130,"voices":369}},{"id":"h30-20180314-3","meetingId":"h30-c-budget","date":"2018年3月14日","dateIso":"2018-03-14","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年度品川区一般会計予算","agenda":"平成３０年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３４３ページ、帰国児童・生徒等支援費の中の日本語指導教室運営、３４５ページ、いじめ防止対策費、３５７ページ、プロジェクター運用、校内無線ＬＡＮ整備、３５９ページ、教室等照明ＬＥＤ化工事費についてお伺いいたします。初めに、日本語指導短期集中教室と事項別明細資料には書いてあるのですけれども、そのご説明を、どういった集中教室をやっているのかお知らせいただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"品川区の区立学校に在籍している帰国子女を含む、あるいは外国籍で日本語がまだなかなか、学校の授業を受け理解するのが少し難しい児童・生徒を対象に、おおむね３カ月程度を１つのサイクルといたしまして、区内の学校の教室１カ所を会場といたしまして。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本年、平成２９年度は山中小学校で開催していると思うのですけれども、これは来年もまた同じく山中小学校でやるのかどうか。それと、日本語指導が必要な児童・生徒がいらっしゃいます。その中で、平成２９年度、前期課程と後期課程の人数を把握しているのであればお知らせいただきたいのと、あと、一番多い国名を教えていただければと思います。よろしくお願いします。","respondent":"大関教育総合支援センター長","answer":"一番多いのは、中国から来ているお子さんで、小学校および前期課程でもう７０名を超えるという実質があります。","voiceIndex":6,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そうすると、外国籍の児童が多い小学校には、日本語の指導担当員、教員の方が派遣されていると思うのですけれども、平成２８年度は、お伺いしたところ、御殿山小学校だと思うのですけれども、平成２９年度において、外国籍の児童の多い小学校はどこだったのでしょうか。お知らせください。よろしくお願いします。","respondent":"大関教育総合支援センター長","answer":"今後も同じ教室を、当面の間は活用する予定でおります。なお、ただいまご質問いただきました外国語通訳、それから御殿山小学校での、日本語の難しい児童が多い学校への教員の加配ですが、今年度も御殿山小学校に、対応の教員を加配しています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今後はまた増加傾向にあるのかということは、また引き続きお聞きしたいと思います。続きまして、いじめ防止の意識向上としたいじめ根絶バッジについてお伺いいたします。それともう一つ、教室等照明ＬＥＤ化については、来年度、平成３０年度は小学校３校・中学校２校なのですけれども、学校名がおわかりになれば教えていただきたいと思います。よろしくお願いします。","respondent":"大関教育総合支援センター長、有馬学務課長、品川庶務課長","answer":"初めに、いじめ根絶に向けたバッジの活用ですが、全ての児童・生徒が、第１・第３土曜日には着けて、いじめ根絶を考えるというのは、全校で考えております。校内無線ＬＡＮにつきましては、平成３１年度に全校配備ということで、今のところ、予定しています。教室のＬＥＤ化ですが、平成２８年から８年間かけて直していこうと、おおむね考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"３４１ページの就学援助費に関連いたしまして、私立高校の授業料実質無償化の周知についてお伺いします。３４７ページ、オリンピック・パラリンピック教育推進事業、そして時間がありましたら、３５１ページの特別支援教育費に関連して、デジタル教科書についてお伺いいたします。１つ目ですが、私立高校の授業料実質無償化の周知の仕方についてお伺いしたいと考えています。","respondent":"有馬学務課長、廣田子ども家庭支援課長","answer":"私立高校の学費の軽減あるいは都立の軽減もありますけれども、これらの周知ですが、この制度につきましては、東京都等を通じて、公益財団法人の東京都私学財団というところがパンフレットをつくっておりまして、それが、毎年大体６月に。周知についてですけれども、ひとり親につきましては、子ども家庭支援課で、ひとり親対象の福祉資金の貸付けから審査まで行っておりますので、お問い合わせがあったときに周知しております。","voiceIndex":16,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"東京都のホームページを見ても、なかなか、どこをどうやって調べていけばいいのか難しい現状もありますので、今、品川区では、６月に都からパンフレットが来て周知を、子どもを通して親に伝わるということが確認され、また子育て支援担当課では、随時、窓口でその案内をしていただけるですが、その上で、品川区のホームページから東京都私学財団へリンクができるように。","respondent":"有馬学務課長、廣田子ども家庭支援課長","answer":"６月に各学校に通知する文書にも、具体的には東京都私学財団にということで、ホームページのご案内も出ているところですが、一層周知をするという意味でも、区のホームページにリンクを張れるのか、あるいは張るとしたらどこがいいのか。給付に当たる就学資金であるとか東京都の授業料軽減の制度については、現在載せておりませんので、今後、給付等につきましても、工夫して載せられるようにしていこうと考えています。","voiceIndex":19,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"オリンピック・パラリンピック教育推進事業についてお伺いいたします。そこで、これまで行ってきた成果と、オリンピック・パラリンピック後の教育の部分でのレガシーについてお伺いいたします。２月２８日に、豊葉の杜学園で、小学生が決めるオリンピック・パラリンピックのマスコットの最終発表が行われましたが、豊葉の杜学園で行われた経緯と、子どもたちの声をお聞かせいただきたいと思います。","respondent":"熊谷指導課長","answer":"しながわ」５年生から９年生用を作成・配布し、各校で活用しています。来月初めには、新たに１年生から４年生用を配布し、次年度からの活用を図ってまいります。こうしたところが成果ですけれども、一番は、子どもたちの自己肯定感が高まった。","voiceIndex":22,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"レガシーというところで、東京２０２０大会の日程に着目いたしますと、特に今回、パラリンピックの成功が大事だということを東京都が言っております。ちょうど夏休みの終わる１週間、そして明けて１週間の時期に重なっておりますが、ぜひ学校として、パラリンピックに小学生・中学生全員が授業として参加できるようなことも、今後ご検討いただきたいと思いますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"５６年ぶりに行われるパラリンピック大会に児童・生徒全員が参加し、友達とともに迫力のあるプレーを見るということは、一生忘れられない思い出となると思いますので、そうした、よりよい参加の仕方を考えてまいります。","voiceIndex":24,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"３月９日の大雨で、区内の全区立学校が休校となりました。品川区のルールとして、朝の７時の時点で警報が出ていると学校を休校にすると伺っておりますけれども、このルールをもう一度確認させていただきたいと思います。その上で、一度休校を決定しても、状況を判断し、時間をずらして学校を再開するということは検討されたのかどうか、どのような検討があったのか伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"その場合、警報が出ている場合には、子どもたちの安全を第一として、７時の段階で解除されていない場合には休校、特に指示の出なかった場合は休校という最低限のルールを、これまで校長会も含めまして、何度も基準を検討してきた経緯があります。","voiceIndex":27,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"ただ今回は、７時２１分に警報が解除となりました。先ほどの答弁ですと、混乱するからというお話ですけれども、特に小学校の低学年の児童が自宅で１人でお留守番をするというのも、とても危険なことだと思いますので、ここについては、しっかりどういうルールをつくっていくのか、検討が必要ではないかと思うのですけれども、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"当日は未明より検討をずっと継続していた１日です。なお、雨だけではなく、大雨、浸水害、そして洪水の警報も出ておりました。","voiceIndex":29,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"ただ、その後の対応がどうだったのかという点で伺っております。保護者にはあらかじめ、７時の時点で、連絡はされているということですが、一度休校を決定しても、２時間目や３時間目から、途中から学校を再開するということは、今後も検討できないものなのかどうか、ここのルールづくりについて、次回に活かすべき教訓が今回あるのではないかと思うのですけれども、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"教育という観点で、まず子どもたちには自宅学習をお願いしたという経緯が当日はございました。そして、自宅に１人でいることがなかなか難しい低学年のお子さんを心配する保護者の声は、教育委員会にも区民の声を通じていただいております。","voiceIndex":31,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"とりわけ小学校１年生・２年生・３年生、低学年のお子さんが自宅で１人でお留守番をするというのは難しいと思いますので、この対応については、しっかりと検討を進めていただきたいと強く要望しておきたいと思います。次に、いじめについての学校の対応について伺いたいと思います。こちらも、地域の方から複数、いじめについて学校に相談したけれども、最初の対応に疑問を感じたと。","respondent":"大関教育総合支援センター長","answer":"直接学校に寄せられるだけでなく、直接、ＨＥＡＲＴＳに教えていただく電話が教育総合支援センターに来ることもあります。その場合には、すぐに当該校に連絡して、同様の対応等を各校でとっていただいている、そういう状況にあります。","voiceIndex":33,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"今おっしゃったように、学校ではさまざま、力を発揮していただいていると考えています。ただ、私のところに、学校の対応はどうなのかという率直なお声を複数伺いました。例えば、学校に行っている時間なのに、どうも家の中にいると。いじられているの。」という聞き方をしたそうなのです。コミュニケーションをとるのが難しいのだと思いますという対応であり、これは少しどうなのかと、話を直接伺いました。","respondent":"大関教育総合支援センター長","answer":"必ず、どの学校でも、どの子どもにも起こり得るのです」ということを、毎年、全教員を対象に研修会も行っておりますので、今後とも、そのアンテナが鈍くならないように、対応を丁寧にするように周知をしてまいりたいと思います。","voiceIndex":35,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり、地域は子どもたちと、さまざまつながっておりますので、子どもたちのいじめに気づいたり、これはちょっとどうなのかと気づくことはあります。もちろん、地域の住民も学校を信頼しているからこそ、相談に行くのだと私は思います。改めて、地域の方々の相談を受けた時の今後の取組みについても先ほど伺いましたけれども、ぜひ学校が子どもの力になっていただきたいと思いますが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"そういった中で、今のようなお声をいただいた部分に対しても十分に、今後とも継続して対応を充実していくように働きかけると同時に、協力をお願いしていく考えです。","voiceIndex":37,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言、こうした教師の専門性を発揮するためにも、教員の多忙化の問題が大きな課題になっておりますけれども、ぜひ学校をあげて、また教師の専門性も発揮していただいて、子どもたちの力になっていただきたいと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"３４７ページ、オリンピック・パラリンピック教育推進事業全般について。３６１ページの通学安全確認業務とは何ですか。そして、ページ数が不明なのですが、生徒の部活動の大会出場に関する休みの取り扱いについてお伺いしたいと思います。しながわ」。ここで１件、お伺いしたいのが、全校でやられているわけであって、どういう形でアワード校として認定されたかということを教えていただきたいのです。","respondent":"熊谷指導課長","answer":"ただ、都全体で、都立高校も特別支援学校も含めて１２０校しか選ばれない中で、全て通ったというのは、やはり今まで全ての学校のやってきたことの中で、特にやりたいという思いが通じたのだと思います。","voiceIndex":41,"id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"もともとこの事業は、教育というのですか、本質を考えると、顕彰の有無に関係なく、障害者理解やダイバーシティ教育の一環として、オリンピック・パラリンピック教育はさらに推進するべきものと考えておりますが、今後さらに取組みを推進していくのであれば、やはりパラリンピック競技以外の、例えば聴覚障害者のデフリンピックや、知的障害者のスペシャルオリンピックスという部分にも触れていただいて。","respondent":"熊谷指導課長","answer":"それにつきましても、また指導・助言を行って、全校で盛り上げていきたいと考えています。パラリンピック以外にデフリンピック等も含めてということですが、障害者理解も進めておりますので、昨年度・今年度、２１校がパラリンピアンをお呼びして講演を行っております。","voiceIndex":43,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"どのようなシステムで保護者に情報提供しているのか、統一のシステムが必要ではないかというのが１点。児童・生徒の教育長表彰などがありますが、必ずしも大会が、休み、休校のときにあるわけではないので、やはりそういったところに出場した、勝利をおさめてきた方々に対しては、欠席扱いではなく公休扱いにするべきではないかと思いますが、いかがでしょうか。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"２１日から行われるブラインドサッカー国際大会で、荏原第六中学校、東海中学校、鈴ケ森中学校の子どもたちが、ボールボーイ等のボランティアを行うことになっております。大会等に出場した子どもの出席扱いという部分ですが、これは学校教育法第２１条１項にも照らし合わせまして、しっかりと子どもの社会活動という部分を校長が判断して出席に扱うことができるように、前向きに検討してまいります。","voiceIndex":45,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"私は、教育費全般についてお聞きしたいと思います。品川区は、今日までさまざまな教育改革や事業を進めてきました。そして、それに対して、学校教育、教育行政が十分対応できていないのか、それとも何か問題があるのか、さまざま考えますが、そもそも学校教育の原点というのは何でしょうか。そして、このように保護者の方たちが思っている、それに対してご見解をお聞かせください。","respondent":"熊谷指導課長","answer":"保護者が品川区の学校に対してあまり満足されていないのではないかというご質問がございましたけれども、実際に平成２８年、昨年度ですけれども、９１％の保護者が非常に満足しているとお答えいただいてあります。","voiceIndex":49,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"見ていて、子どもたちはどうなのですか。本来、学校教育において子どもが身につけるべき力の一つは、私は学力だと考えています。そうすると皆さんはどうなのですか。それがいまだに３割もいる。そして、学校教育において子どもたちが、やはりきちんと学力を身につけるということを、きちんとやるというのが教育行政の根本だと私は思うのですが、その点についてもう一度ご見解をお聞かせください。","respondent":"熊谷指導課長","answer":"知識・技能、そして思考力・判断力・表現力、そして３つ目、とても重要だと考えていますが、学びに向かう力と人間性、この３つを学力としております。","voiceIndex":51,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"品川区は今までも、全国有数の教育、指導をしている。それで、やはり皆さん、心配している方がいるから、３割以上の方が中学受験を相変わらずやめない。塾に行けば年間１００万円以上かかります。少なくとも、学力はこうやってしっかり定着させて、全国テストをやっても上位、１番とは言わないけれどベスト５に入るとか、そういうことすら聞こえてこない。このような現状でいいのですか。お聞かせください。","respondent":"熊谷指導課長","answer":"今お尋ねの全国学力・学習状況調査ですけれども、品川区は１位、２位、３位、４位、各教科、独占しております。ですので、秋田県、青森県、石川県と並ぶですので、６年生に関しては全教科独占。","voiceIndex":53,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"先ほどの全国学力・学習状況調査の成績ですが、それぞれの教科で何点だったのですか。９０点以上取っているのですか。違うでしょう。皆さん、全国学力テストをやってもそんなに力を入れていないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"今、課長から、トップの成績である。でも、実際、点数はご存じですよね。１００点満点中、７０点前後かわからないですが、実際そんなものでしょう。学校ではわからない。こんなことまで言われています。それは指摘しておきます。そして、少し別の角度で品川区の教育についてお聞きしたいと思います。こういう現状をどういうふうにお考えですか。それについてご見解をお聞かせください。","respondent":"大関教育総合支援センター長","answer":"いじめ問題や、あるいは不登校の問題、あるいは家庭内での虐待等、さまざまな課題は、以前より子どもたちにはあり得た状況を、これまでは学校あるいはそれぞれの機関が対応してまいりましたが、もっと有機的に、それぞれが関連して。","voiceIndex":58,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"しっかりいろいろ取り組んでいるのです。ですけれども、やはり先生も子どもと１対１でなかなか対峙できない。これは、もう随分前から、ほかの地域では１０年以上前からやっていた制度です。どうなのですか。そして、このようにどんどんいろんなものを取り入れても、先生は混乱するばかりではないのですか。地域の力がないと、もう学校教育、公教育はできないということですか。ご見解をお聞かせください。","respondent":"熊谷指導課長","answer":"やはり地域の力というのは、子どもたちを育てていくのに絶大であると思っています。地域の中の学校でありますので、学校と地域が両輪として一緒に育てていくということが本来の教育のあるべき姿であると考えています。","voiceIndex":60,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"これは国の逃げもあるのかと私は思うのです。学校でできることは学校でやる。先生にはそんなに時間があるのですか。そして現在、教員もやはり異動というのが、これは、東京都の教員ですから、品川区はしようがないですよね。異動もある。こういう状況というのは、もう本当にどうするのですか。ますます教員、また教育現場は混乱すると思うのですが、ご見解をお聞かせください。","respondent":"熊谷指導課長","answer":"学校で混乱が起こっているかというと、そうとは考えてはおりません。","voiceIndex":62,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"よく、先生が大変だ。教科書も厚くなったのです。これは誰が考えても、私は先生の負担が大きいと思うのですが、実際どうなのでしょうか。おそらく飛ばしていくのかと思うのですが、こんなに忙しくなっているなら、土曜日、今、隔週で休みをとってありますが、これだと、土曜日に出ないと到底間に合わない時間数が必要だと私は思うのですが、その辺についてご見解をお聞かせください。","respondent":"熊谷指導課長","answer":"しかしながら、本区におきましては、他区と比べまして、これまでも人的支援ですとか、それから環境の整備ですとか、そういった部分では、２３区のどこにも負けないよう準備をしてきたところです。","voiceIndex":64,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"品川区で私がすばらしいと思うのは、品川区、固有教員採用です。本当にこれは、私はもう感謝するしかないのかと思います。でも現実論、大半の教員には出入りがあります。それで、よい教員も選べるわけではない。そんな状況で、学校教育を担う人たちがそういう問題を抱えていて、何で、課長がおっしゃるようなよい教育ができるのですか。私はここは考えてやるべきだと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-027"},{"speaker":"田中委員","kind":"質問","question":"３６３ページ、２項学校教育費、１目学校管理費のうち学校給食放射性物質検査費、３４３ページ、１項教育総務費、３目教育指導費について伺います。学校給食放射性物質検査費について伺います。多くの保護者から、今年度も予算がついたことについて、よかった、安心したという声が、生活者ネットワークには届いています。給食の放射性物質検査の継続を評価します。予算減額の理由を教えてください。","respondent":"有馬学務課長","answer":"平成３０年度の予算につきましては、ヨウ素、セシウムの回数の見直しというのを行いました。従来２回行っていたものを、１回に変更した、縮減したということで、金額が減っているものです。","voiceIndex":68,"id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"福島第一原発の事故から７年たちましたが、福島県内の川では、目に見える大きさの放射性物質の粒、セシウムボールが確認されたと、３月７日に報道がありました。原発事故はいまだ続いています。４段階目の検査では、消費者がみずから測定し、確かな数値を消費者で確認し判断することを求めているのです。検査の継続はもちろん、食材の単品検査への変更という時期に来ていると思いますが、見解を伺います。","respondent":"有馬学務課長","answer":"単品検査への変更については、今は一緒に食にするものを、実際に児童・生徒が口にしたものを検査するということで対応していますので、これで十分な検査方法だと考えています。それぞれの食材一品一品ということは、今のところは考えてございません。","voiceIndex":70,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"なかなか重要性を共有できないことが残念ですが、ぜひ検討をしていただけたらと思います。関連して、福島県の裏磐梯への移動教室について伺います。教諭による実地調査を行った際に、放射線の測定も行い、その測定結果は各学校長に届いていると伺っています。測定結果を校長が持っていることが保護者に周知されるように、改めて求めたいのですが、いかがでしょうか。","respondent":"有馬学務課長","answer":"２７０カ所以上、児童・生徒が見学するところを測定しておりますけれども、一切問題ないということですので、あえてそれをわざわざこちらから言う必要はないだろうということで、問い合わせがあれば、問題ないですとは答えるということで対応しているものです。","voiceIndex":72,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"その問題がないという安全の裏づけを求めている保護者がいるので、ぜひ周知されるように。せっかくの実地調査ですので、お知らせをぜひしていただきたいと要望いたします。次に、香害について伺います。学校では、給食のかっぽう着を、当番の生徒が週末に家に持ち帰り、洗濯して持って行くということですが、かっぽう着の香りがきついなどの声が保護者などから届いていないか伺います。","respondent":"有馬学務課長","answer":"白衣に限らず、洋服も含めて、においがきついという声は聞いてはおりません。","voiceIndex":74,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"香害の問題は３つあります。１つは、においの成分、２つは、アロマカプセルなど香りを閉じ込める成分、３つ目は柔軟剤に添加されている保存料や除菌成分です。品川区でも、学校をはじめ保育園や幼稚園などの子ども施設、保健センターなどでも、香害に対する啓発が必要ではないかと考えますが、いかがでしょうか。","respondent":"有馬学務課長","answer":"やはり物には限度があると思うので、多分、その場で担任なり学年主任や、そういうところに話が出て対応しているのだと思いますけれども、現状としては、今のところ、特にそういう問題は出ていないというのが現状ですので、周知というのは。","voiceIndex":76,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、教職員の研修計画について伺います。昨年の決算特別委員会の中で、教職員の研修計画に、発達障害とＬＧＢＴの研修が組み込まれていないことに触れ、子どもたちの近くで接する教員には、特に学んでほしいと要望しました。新年度の研修計画は今、作成中ということを伺っていますが、現在、どのように検討がされているのか伺います。何か校長から報告などがあればお知らせください。","respondent":"大関教育総合支援センター長","answer":"既に、小学校および義務教育学校の前期課程の子どもたちは男女混合の名簿を使用してきておりますので、残る７年・８年・９年と進んでいくに従って、スムーズに理解が深まっていくだろうと考えております。","voiceIndex":78,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"研修計画です。今、残念ながら、通常級では合理的配慮ができていないと、保護者から声が届いてしまっている状況です。特性を、もっと２次障害の発生を防ぐためにも、子どもに接する教員に、直接的な発達障害への理解の場、学びの場を再度求めますが、ご見解をお知らせください。ですので、ぜひ教員から、ＬＧＢＴを認めているという環境づくりをしてほしいと思います。こちらも見解をお知らせください。","respondent":"大関教育総合支援センター長","answer":"それとあわせまして、子どもたちに対応する際にきちんと、養護教諭、担任、それぞれの立場の教員が子どもたちの悩みに気づいてあげられる、受けとめられる、そういった部分について教員に対して研修を進めておりますので、今後ともその部分は大切にしてまいりたいと思います。","voiceIndex":80,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"発達障害についてです。私が伺ったのは、通常級でのことでした。全ての人が認められ、一人ひとりが自分に自信を持ち成長することができるように、子どもたちの環境を整えることを強く要望します。宣言にも、「人権尊重思想の普及啓発と教育を推進することをここに誓う」と掲げられているので、ぜひ教員や子どもたちが多様性について学ぶ機会を今以上に推進していただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-035"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３４３ページ、品川区研究学校、３４７ページ、市民科・各教科充実経費、３４９ページの品川英語力向上推進プラン、３５１ページ、学校地域連携推進経費、３５５ページ、教材教具等経費についてお伺いいたします。１点目に、品川英語力向上推進プランについてお伺いいたします。４技能英語力テストでは、リスニング、聞く力が育っているという結果が出ているかと思います。お聞かせください。","respondent":"熊谷指導課長","answer":"ただ、スピーキングにつきましては、各校の英語科教員が面接官となり実施しているところですので、全体としてどういう状況にあるかというのは、まだ把握できていない状況ですけれども、それ以外の聞くこと、それから読むことにつきましては。","voiceIndex":84,"id":"exchange-036"},{"speaker":"横山委員","kind":"質問・要望","question":"スピーキング力は、いろいろな周りの動き等を見ていただきまして、ぜひ推進していただきたいと思います。今後さらにＪＴＥの資質向上に重点を置いていただくことを強く要望いたします。現在のＪＴＥの研修の内容について教えてください。","respondent":"熊谷指導課長","answer":"各グループの代表者と教育委員会の指導主事との情報交換も行ってまいります。現在も、ＪＴＥ連絡会を毎月行っておりまして、そこで各グループから集められた情報をもとに、各学級での指導力の向上を行った研修を実施しています。","voiceIndex":86,"id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、市民科・各教科充実経費についてお伺いいたします。家庭科の単位数や時間数は厳しい状況にあるかと思いますが、旬の食材を取り入れた季節の献立を学んだり、児童が身につけた知識や技能などを日常生活で活用できるよう、家庭との連携を促すなどして、工夫した指導を行っていただきたいと考えますが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"家庭科に関する内容です。委員ご指摘のように、家庭や家族の捉え方が非常に多様化しておりまして、家庭の機能にも差があるという部分は教育委員会としても認識しています。","voiceIndex":88,"id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目に、品川区研究学校についてお伺いいたします。第二延山小学校の研究主題、自立した学習者を育てる授業のあり方は、東京大学大学院教育学研究科教授、市川先生の研究室との共同研究と聞いておりますが、東京大学大学院との共同研究とは、どういった位置づけなのか教えてください。各学校において、一定期間、使用しない教材教具や備品がある場合に、学校間での融通は行われているのでしょうか。","respondent":"大関教育総合支援センター長、有馬学務課長","answer":"その成果をさらに広めていくために、今後、さらに市川先生の協力を得ながら、平成３０・３１年度につきましても、今度はさらに、考えさせる授業だけではなくて、そこをどのように教員として評価していくかという新たな課題も踏まえ。必要な場合に、各学校が相手の学校に問い合わせをして貸し借りを行うというようなことで対応をとっているところです。","voiceIndex":90,"id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"研究学校のほうなのですけれども、今、教員の指導力、そして児童の理解、それぞれ成果も上がっているということをお聞きいたしました。教材教具のほうなのですけれども、今後、教育委員会で一括して教材教具や備品の情報管理をしていただいて、使いたい学校があればそちらで使っていくというスムーズなシェアリングを進めていきたいと要望しますが、いかがでしょうか。","respondent":"有馬学務課長、熊谷指導課長","answer":"ということで、今のような、グループウエアの中で電子上のデータとして全てを掲載したということで対応しておりますので、当面は各学校にも。学校支援地域本部におけるゲストティーチャー等の確保、共有化ですけれども、今年度は、年６回のコーディネーター連絡会で、各校がお呼びしたゲストティーチャーについて情報交換しまして、情報共有を図ってまいりました。","voiceIndex":93,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"ただ、中学校区を超えて、例えばＡの地区でテニスができる方がいらっしゃって、Ｂの地区でそういう方を求めているという情報を、今、連絡会で情報の交換をしていただいているということだったのですけれども、品川区全体で、そういったボランティアの方のニーズと受け入れがもし整っているようでしたら、そのあたりをうまく調整して、段階的に進めていただきたいと考えています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-041"},{"speaker":"つる委員","kind":"質問","question":"３５２ページ、図書館費、３５７ページ、学校図書館経費、３４５ページ、ルネサンス推進事業、３４９ページ、品川英語力向上推進プラン、３４３ページ、帰国児童・生徒等支援費について伺っていきたいと思います。先日の報道で、大学の生協が行った読書時間についての調査結果で、１日の読書時間が０分と回答した学生が５３.１％。こうした中で、図書館としての果たせる役割は何か、改めて教えてください。","respondent":"横山品川図書館長","answer":"学齢期に読書の習慣をつけるために、品川図書館としましても、学校図書館へのスタッフの派遣等の支援を行って、強化に努めているところです。","voiceIndex":98,"id":"exchange-042"},{"speaker":"つる委員","kind":"質問・要望","question":"その佐藤さんは、月の読書量が３００冊以上だそうでありまして、ニュースのチェックとして、主要７紙の新聞を読むのも、朝２０分で十分だということで、これは経験のたまものかと思いますけれども、そうした中で、先ほども少し話が出たかと思いますが、２０２０年からは、大学入学共通テストで記述式問題が導入されて、自分で答えを考えて書くことになるといったことから、より一層。","respondent":"横山品川図書館長","answer":"子どもに読書について興味を持っていただくために、例えばイベントでは、先日行いましたように、本の福袋ということで、本の中身を知らせないで借りていただいて、自分が日ごろ選ばないような本をご案内するようなイベントであるとか、ビブリオバトルで。","voiceIndex":100,"id":"exchange-043"},{"speaker":"つる委員","kind":"質問・要望","question":"時代を超えて学んでいける。そして、未来について、どう生きていくか、生き抜いていくか。そうした中で、数々の図書館、５００近い自治体で、図書館が地域活性化など、あらゆる人の居場所になってきている。そうした中で、品川区もさまざま工夫をされていると思いますけれども、もちろん、品川区という地域特性もありますけれども、図書館のあり方も含めて、今後の方向性などがあれば、それを教えてください。","respondent":"横山品川図書館長","answer":"品川図書館におきましても、もちろん基本的な本を提供するという役割はしっかり守りつつも、それを外に発信し、皆さんに知らせることで、地域の方の居場所になるように、今年度につきましては、高齢者の支援をする図書館というような提案もさせていただいたところで。","voiceIndex":102,"id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"そこの牽引力が図書館にあるかと思いますので、よろしくお願いしたいと思います。学習の積み上げであるので、ただ、その上で、この春、卒業する中学３年生が、その共通テストの対象になるということも含めて、これまでの対策・対応について教えてください。英語については、英検３級の取得率は全国でも高いことになっておりますけれども、話す、書くについてもどのように指導していくのかお知らせください。","respondent":"熊谷指導課長","answer":"それに伴いまして、１６日の教育委員会でご審査いただくことになります品川区立学校教育要領におきましては、本区でもこれまでの学力・学習状況調査で課題が見られました、記述式の無回答率を減らしていくために、まず本や文章、図表やグラフなどから。","voiceIndex":104,"id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"そういった意味で、今後の世界の動向を見ても、２０世紀を生き抜くための必要な国際共通語はスペイン語になっている可能性もあるのではないかという中で、グローバル給食など、時には大使館との交流などでもいいと思いますが、スペイン語に触れる機会など、教育の先駆をいく品川区として、スペイン語を取り入れたらどうかと思いますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"現在、スペイン語を学習する機会というのはなかなかないのですけれども、ただ、これから東京２０２０大会も迎えるところですので、さまざまな国のお客様をお迎えするということも考えまして、ジュニア・イングリッシュキャンプ等で学んでいったり。","voiceIndex":106,"id":"exchange-046"},{"speaker":"筒井委員","kind":"質問","question":"第１点目、学校施設建設費についてなのですけれども、高層大規模マンションがどんどん増えております。それで、品川区民の不安の払拭、安心を与えるためにも、ここでやはり広報しながわや各種媒体で、就学人口増にはしっかり対応して、小学校建設、整備を行っているということ、大丈夫だということを、区民に広くお伝えすべきだと思うのですけれども、それに対して区はどうお考えでしょうか。","respondent":"有馬学務課長","answer":"区民に、その辺は大丈夫だということをしっかり伝えていくべきではないかというような点ですけれども、なかなかどういう機会でやるのかというのは難しい面もあろうかと思いますけれども、例えば秋に教育特集号を広報誌として出すときがありますので、そういったところで。","voiceIndex":111,"id":"exchange-047"},{"speaker":"筒井委員","kind":"質問・要望","question":"そしてまた、４年前に租税教室などをやられてきたかと思うのですけれども、そうした公民や租税教室など教室単位で行われていると考えられますけれども、実体験に基づいた教育、実践的な教育として例えばスチューデント・シティやファイナンス・パークの中で、ぜひ、そうしたことを、これはすでにやっているかもしれませんけれども、やられているのだったら、その内容と、もしやられていないのだったら。","respondent":"大関教育総合支援センター長","answer":"租税に関する教育ですが、委員より今ご案内いただきました経済体験教育プログラムとして、５年生でスチューデント・シティ、事前学習も含めますと１５時間を使って５年生が学ぶ中で、実際にスチューデント・シティ当日には、区役所のコーナーがありますので。","voiceIndex":113,"id":"exchange-048"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。私は見に行ったことがあるのですけれど、区役所があるのですから、そういったことをやればいいかと思ったのですけれども、やられているということで、そこは確認できました。関連しまして、２０１３年１１月に、租税教育を重要課題としまして、濱野区長が会長になられた品川地区租税教育推進協議会というのは、今一体どういう状況で、そして今後、どういった活動をされるご予定なのでしょうか。","respondent":"大関教育総合支援センター長","answer":"租税教室の実施状況ですが、平成２６年度より、全校で実施しております。そのほか、税に関する作文は、やはり平成２８年度には全校で実施して、今年度も実施しています。そのほか、絵はがきコンクールですとか、さまざまな形で、税について子どもたちは学んでおります。","voiceIndex":115,"id":"exchange-049"},{"speaker":"筒井委員","kind":"意見","question":"わかりました。続いて憲法教育についてなのですけれども、特に改正の部分です。憲法の内容は公民でしっかりとやられていると思うのですけれども、特に憲法改正の手続、流れというものは、客観的に憲法改正の賛否はともかく、そうした改正手続などの知識は丁寧に、今後、特に意識してやられるべきかと考えておりますけれども、憲法改正について、どのような姿勢で今後、臨まれるのか、お答えください。","respondent":"大関教育総合支援センター長","answer":"その中で丁寧に扱っておりますが、公教育として、まず現状の憲法に基づいて、どのような形で議会制民主主義は実施されているかという部分が正しく理解されるように、そこに力点を置いて、適切に指導してまいります。","voiceIndex":117,"id":"exchange-050"},{"speaker":"筒井委員","kind":"質問・要望","question":"憲法の基本理念や条文など、そうした基本的なことはもちろんやっていただきたいのですけれども、特に憲法改正についてはどうかというところをお聞きしたかったので、よろしくお願いします。","respondent":"大関教育総合支援センター長","answer":"その場合においても、適切に、教員として、公教育として、必要な助言等はしながら、調べ学習等も支援するという形で実際に取り組んでいるところです。","voiceIndex":119,"id":"exchange-051"},{"speaker":"筒井委員","kind":"質問・要望","question":"今の生徒、これからの生徒は、やはり憲法改正というのは、これからご自分の人生の中で何回かは出てくるという可能性が高いので、ぜひそうしたことも踏まえてしっかりと教育を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"３５５ページの大崎図書館移転経費、３４７ページ、学力定着度調査経費について伺います。大崎図書館ですけれども、総務費でも伺いましたが、その続きです。最後、前の質問で私が伺いたかったのは、これまで区の説明では、大崎図書館の移転のメインの理由は老朽化でした。まちのありようの変化ということと大崎図書館の移転の両者にはどんな関係があるのか伺ったので、お答えいただければと思います。","respondent":"横山品川図書館長","answer":"今般ご説明していますように、ビジネス支援施設のＳＨＩＰが移転したことに伴いまして、文教施設を北品川につくる機会がございましたので、新しい図書館を得て、そこに新しいまちのありようを加えた形で図書館の運営ができる形になりました。","voiceIndex":123,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"全然説明になっていないです。区長のタウンミーティングの発言の真意というのは、まちのありようが変化することはやむを得ないので、代替施設をつくりますから我慢してくださいということなのですか。今の説明では、何で移らなくてはいけないのか、全然説明がないではないですか。何がやむを得ないのですか。それは怒りますよ。文化と地域の歴史を何だと考えているのですか。ぜひ区長がお答えください。","respondent":"横山品川図書館長","answer":"いろいろな障害はあるかと思いますが、前向きに、これからのことを考えて、これからの子どもたちのために図書館はあるべきだと思ってあります。","voiceIndex":125,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"今回、解体費用は１億５,０００万円ですから。しかも、今、西口にちょっとした施設はありますけれども、来年の１月ですか、芳水小学校に代替施設というところもできるようですが、それまで１年間ぐらい、大崎図書館は閉まっているわけではないですか。これは完全に、自分自身が道路を推進して、その道路で図書館を動かしておいて、それが残念だというのはどうなのですか。お答えください。","respondent":"柏原企画調整課長","answer":"今、道路のお話がございましたけれども、その後の流れの中で、東京都に対して、道路の関係については協力をということに対して、我々も協力はいたしますというものを申しているわけでありまして、さも道路があって、図書館の移転ということをおっしゃっていますけれども。","voiceIndex":127,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"そういった動きが先にあった。実際に、当時の所管の部署は、建て替え費用を財政課に申請していたのですから。次に学力テストについて伺いますが、事項別明細書には、品川区立学校における学力定着度調査委託で、３,２４６万円余とあります。この委託先がどこなのか、企業名を教えてください。具体的にどんな業務を委託しているのかも伺います。学力テストの丸つけを行うのは誰になるのか伺います。","respondent":"熊谷指導課長","answer":"どこでつまずいたのかといったものがわかる分析資料等も各学校に来るとともに、子どもたちにも返却されることになっております。それから、委託契約先ですけれども、こちらにつきましては、経年で行うことになっておりまして、東京書籍です。","voiceIndex":129,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後の方向性として、毎年実施していくことで、学力の経年変化や他地区との比較を含めた分析を行い、指導改善、学力向上を図るとともに、保護者等に対しても学力等の状況について広く理解を求めていくとあります。いかがでしょうか。","respondent":"熊谷指導課長","answer":"子どもたちはわかるようになりたいと思っていると思います。比較ということではなくて、どこでつまずいたのか、また反対にどこがわかっているのか。そういったことを、しっかり子どもたちもわかり、また保護者にも伝えていくような調査結果となっております。","voiceIndex":131,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"それで、現場の教師から、年度末の時期になると、管理職から、４月のテストを見越して８割定着させておきなさいと言われるそうなのです。こうやって、子どものテストの点数獲得能力をつけないと、周りに迷惑をかけますと言わんばかりに、教師同士にお尻をはたき合わせるというのも、学力テストの狙いなのでしょうか。先ほどのような、教師を追い立てるというのも、学力テストの狙いなのかどうか伺います。","respondent":"熊谷指導課長","answer":"そういったことがないと信じたいところですけれども、そもそも学力は、学校がどうなのか、学校全体の学力がどうなのかということを問うものではなく、一人ひとりの子どもたちに、生涯にわたる力をつけていくために行うものですので、そうした意味で、今回、系統的な。","voiceIndex":133,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"事例について残念だという認識をお持ちだというのは、少しほっとしましたが、実は違うのです。これは別に、やっている人が悪いとは私は言えないと思います。これは、そういうふうに追い立てているのは教育行政、皆さんだということを強く自覚していただきたいと思います。そのことで、この学力テストは区の判断でやめるべきと求めますけれども、いかがでしょうか。","respondent":"熊谷指導課長","answer":"こちらにつきましては、これまで「プラン２１」で各学校が全校行ってきたところですので、このまま続けてまいります。","voiceIndex":135,"id":"exchange-059"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、ページ３６３の給食運営費から食物アレルギー対応、ページ３６３、保健運営費からインフルエンザ対策について、さらにページ３４５、３目教育指導費、いじめ防止対策費に関連して、自殺予防教育についてお伺いしたいと思います。昨年の決算特別委員会に引き続き、学校における食物アレルギー対応についてお尋ねします。","respondent":"有馬学務課長","answer":"そのときの対応というようなことですけれども、まずは基本的には、その場でその児童がそれを喫食しないようにするというような対応を、まず最初にとるものです。","voiceIndex":138,"id":"exchange-060"},{"speaker":"鈴木（博）委員","kind":"質問","question":"大きな事故がなく安心しました。次に、４月になると毎年、学校に提出する、学校生活管理指導表についてお伺いいたします。昨年度は食物アレルギー即時型では、除去対象にどのような食材が多かったのでしょうか。食物アレルギーの特殊型でしばしば重症になる、朝食を食べて運動した後に起こる、食物依存性の運動誘発アナフィラキシーの発生はあったのでしょうか。","respondent":"有馬学務課長","answer":"アレルギー物質の即時性型でどういうものが多かったかですけれども、人数的に多いほうから言いますと、１番がナッツ類になります。続いては魚介類、それから落花生、それから鶏卵、要するに鶏、卵関係です。","voiceIndex":140,"id":"exchange-061"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１年ごとの指導表の更新・提出というのは、継続が必要かどうか、ただ血液検査の結果を要求するだけではなくて、よくご家族と話し合って、場合によっては主治医にも照会し、きめの細かい食物アレルギーの対応が必要なので、毎年提出することになっていると思います。これに関連して、弁当持参についてお伺いいたします。この弁当対応の理由について簡単にご説明をお願いします。","respondent":"有馬学務課長","answer":"弁当持参という考え方ですけれども、基本的には児童・生徒に対しての安全安心を守るというようなことで、給食での事故を防止するため、弁当持参という取り扱いは一部、行っているものです。","voiceIndex":142,"id":"exchange-062"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"弁当持参、弁当対応を要求するときは、そこまでの対応が必要か、主治医に改めて確認することが望まれるという補足説明があります。今回の事例に関しては、主治医への問い合わせはありませんでした。これは要望で終わります。ピーナッツやクルミなど、あらかじめ給食食材から除けるものは除いておく配慮が極めて重要だと考えますが、このような対応は現在、品川区で行われているのでしょうか。","respondent":"有馬学務課長","answer":"生活指導管理表の部分につきましても、医者の意見を聞きながら、個々の症状に応じてということもありますので、そういったところはよく聞きとりをして取り組んでいきたいと考えています。","voiceIndex":144,"id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"質問","question":"現場ではなかなかそのとおりにいっていない例もあるようなので、その辺、ご指導をよろしくお願いしたいと思います。次に、民生費に引き続いて、インフルエンザの感染症における学校の対応についてお尋ねいたします。教育委員会としては、このような、症状のない不顕性インフルエンザ感染者に対し、教職員が検査を直接指示する事態をどのように捉えているか、ご説明をお願いします。","respondent":"有馬学務課長","answer":"基本的には、手洗い、うがい、それから、同じ学校でマスクがあったときには、きちんとマスクをするなど、エチケットをきちんとしてというようなことで対応しています。","voiceIndex":146,"id":"exchange-064"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今の課長のご答弁で安心いたしました。続きまして、自殺予防教育についてお伺いいたします。平成２８年１０月２８日に開催された第３８回教育再生実行会議の配付資料によれば、我が国の児童・生徒の自己肯定感が、諸外国に比べて著しく低いという結果が報告されています。なぜ日本の子どもは、みずから肯定する自尊感情が低いのでしょうか。区のご見解をお示しください。","respondent":"大関教育総合支援センター長","answer":"区の若者の自殺がやはり課題であると、教育委員会も認識しております。","voiceIndex":148,"id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"平成２９年６月２日の参議院厚生労働委員会で、自殺総合対策の更なる推進を求める決議が行われました。ＳＯＳ教育について、ＳＯＳの出し方教育等、日本自殺予防学会の提言も含めて、区としてはどのようにお考えでしょうか。","respondent":"大関教育総合支援センター長","answer":"このような観点から、教員も子どもたちの様子について把握して、担任が１人で抱え込まずに、区であれば、教育委員会、ＨＥＡＲＴＳ等とも共同で事に当たる。そして、関係機関とも連携しながら、適切な支援をしていきたいと考えております。","voiceIndex":150,"id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ＨＥＡＲＴＳに関してもお伺いしたかったのですが、時間がなくなったので、次回にまた改めてお話ししたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-067"},{"speaker":"松永委員","kind":"質問","question":"私からは、３６１ページの防災ヘルメット購入について、同じく３６１ページの児童・生徒用災害時備蓄物資購入について、関連して、各学校で行われている避難訓練について伺います。あわせて、児童・生徒用災害時備蓄物資についてですが、避難所用の備蓄と異なる物資であると思うのですが、この予算の内訳について、教職員などの学校関係者も含まれているのか伺いたいと思います。","respondent":"有馬学務課長","answer":"それで、卒業後の活用というところは、なかなか難しいのですけれども、一応、その間は貸与という形で、中学校３年間は貸しているのですけれども、ヘルメット自体というのは、耐用年数が大体３年から５年というような形になっております。","voiceIndex":154,"id":"exchange-068"},{"speaker":"松永委員","kind":"質問","question":"１年に１回はヘルメットの点検をしてくださいということも伝えられております。そこで、本区の７年生には、防災ヘルメットを渡すだけでなく、こうした説明が行われているのか伺いたいと思います。もし万が一、今されていなければ、こうした今後のヘルメットの活用について伝えるべきだと思うのですが、点検等、伺いたいと思います。","respondent":"有馬学務課長","answer":"教育委員会から業者に何か委託して点検をしているというものではございません。","voiceIndex":156,"id":"exchange-069"},{"speaker":"松永委員","kind":"質問","question":"関連して、アレルギーをお持ちの生徒について伺います。これは、２０１１年の東日本大震災をきっかけに作成されたものでありまして、これまで避難所や災害に備えた講習会などでも利用されているそうです。例えばアレルギー対応食や、エピペン、ステロイド、抗アレルギー剤などは含まれているのでしょうか。アレルギー疾患の児童・生徒・保護者への対応はどのように行われるのでしょうか。伺います。","respondent":"大関教育総合支援センター長、有馬学務課長","answer":"避難訓練についてお答えいたします。備蓄物資におけるアレルギー児童・生徒への対応ですけれども、今回買う中身につきましては、アルファ化米についてはアレルギー対応食を用意する予定です。","voiceIndex":158,"id":"exchange-070"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ、こうしたパンフレットやポスター等も活用して、皆さんに理解を求めていただければと思います。最後に、小中学校で定期的に避難訓練が行われているですが、地震発災時を想定して訓練が行われるということで、訓練内容について、児童・生徒から訓練の後のアンケートや意見というのはとられているのか、それでまた活用はされているのか、最後に伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"避難訓練の後は必ず、例えば消防署長ですとか、あるいは地域の町会長などから、指導・講評いただいたりする場面もありますし、あわせて後日、子どもの感想は教室でまとめて学校便りで紹介したりと、各校で工夫しています。","voiceIndex":161,"id":"exchange-071"},{"speaker":"あくつ委員","kind":"提案","question":"私からは、３４７ページ、市民科・各教科充実経費、３５１ページ、特別支援教育費、最後に３５３ページ、高齢者を支援する図書館づくり、認知症カフェについて伺います。市民科のところですけれども、今回、私のテーマである、教育における国連のＳＤＧｓ、持続可能な開発目標の活用について改めて伺います。これに対して、中島教育長からは非常に力強いご答弁をいただきましたので、若干ここに引用します。","respondent":"大関教育総合支援センター長","answer":"既に、鮫浜小学校あるいは城南小学校等にゲストティーチャーとしてご協力いただいている企業等もありますので、そういった取組みの紹介などとあわせて、区内の市民科推進教師の理解をしっかりと深めてまいりたいと考えております。","voiceIndex":164,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのとき校長室で我々は説明を受けたのですけれども、校長室の壁面に、ＳＤＧｓを教えている先生の写真がありました。ロゴが非常に色が目立つものですから。校長先生にお伺いしましたら、教員の中には、海外の貢献ということに非常に関心のある先生がいらっしゃって、実はうちの学校の子どもはもうＳＤＧｓについてはみんな知っていますと。もし今お答えできることがあれば教えていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"さまざまな学習の中で、これがＳＤＧｓにつながっているという意識をしている教員もいれば、知らずにしっかりと行っているのが区内の学校の現状だと考えておりますので、そういった部分を今後、研修会等を通じて。","voiceIndex":166,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"続きまして、３５１ページ、特別支援教育費に関連して、配慮が必要な子ども、そして保護者への対応について伺います。一昨年、これも平成２８年の第３回定例会で、学校におけるインクルーシブ教育ということについて質問させていただきました。２つ目は、発達障害に関するクラスメート自身の理解の必要性。この、一層進めていけるような具体的な取組みについて、ございましたら教えてください。","respondent":"大関教育総合支援センター長","answer":"これは、今年度、１年生から９年生まで、全てのご家庭にカラーのリーフレットで、さまざまな、例えばじっと座っているのが苦手な子がいますとか、通常の学級にみんないて共生社会なのだということをご理解いただくための啓発リーフレットを配布させていただきました。","voiceIndex":168,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問","question":"ほかの類型としては、頑張っているのにうまくできない子がいますと書いてあって、なぜかうまくいかない、なまけていると思われたり、わざとやっていると勘違いされたりする子どもがいます。これは全てのご家庭に配られたようですけれども、どうですかと聞きましたら、いや、知らないということなのです。繰り返します。その辺について、もう一工夫、何とかお願いしたいのですが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"今後とも積み重ねで、理解啓発として増し刷りをして、全家庭に配り続けるだけではなくて、例えば、今、ご提言いただきましたように、大きく拡大したものを使って、校長が保護者説明会で、全校保護者に対して話しかける。あるいは学年保護者会で学年主任が投げかける。","voiceIndex":170,"id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問","question":"やはり、一言添える場が必要なのかというのも感じます。最後に、このことに関しては、中島教育長に、そのとき再質問で、具体的にどういうことをしていただけるのですかとお伺いしたら、品川コミュニティ・スクールの取組みが、実はこのインクルーシブ教育の進展につながるのだというようなお話があったのですけれども、これは具体的にどういうことを想定されているのか、改めてお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"そのような形で、これは各校の実情に応じて協力していきたいと区も考えております。","voiceIndex":172,"id":"exchange-076"},{"speaker":"あくつ委員","kind":"質問","question":"最後に、時間があれなのですけれども、図書館のほうでの認知症カフェについて伺います。図書館１０館、これは全館で開催するということなのでしょうか。これは、指定管理を受けている図書館流通センターとの話し合いだと思うのですが、この業者が私はすごく好きで、本当にいつも、私自身も図書館のユーザーなので、非常に感謝しているのですが、ここについてどのようにお考えなのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"認知症カフェの図書館での実施についてご質問いただきました。実施については、とりあえず３施設で行わせていただいて、２カ月に１度の実施を予定しております。","voiceIndex":174,"id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３５３ページの教職員在校時間統計処理対応等経費に関連して、教員の多忙化について質問します。実態把握についてですけれども、一般質問で、休日のタイムカードの打刻ができるようにと質問したところ、区は、一律に勤務とは言えないということでした。では、教員の皆さんは何のために休日にわざわざ学校に来ていると、区は考えているのか伺います。","respondent":"熊谷指導課長","answer":"土曜授業日以外の休日等で、学校に来ている理由ですけれども、例えば部活動で来る場合もありますし、また授業準備で来る場合もあると思います。そのほか、研究のために来るときもあると思います。ですので、さまざま教員によって、なぜ来るかというのは異なってくるかと思います。","voiceIndex":177,"id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"どれも、やはり教員が行うべき業務だと思うのです。仕事をするために、やはり休日に学校に来ているということが明らかになりました。都の実態調査でも、土日にしていることは主に授業準備と成績処理です。中学校は部活動もありますけれども、明らかに業務をしに来ているわけですから、在校時間を把握するため、タイムカードの打刻ができるようにすべきだと思いますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"ほかはまだ押印です。もう一区あるのですけれども、出退勤システム、出勤のところだけ押しているそうですけれども、退勤は押さない。そうしたことはしない。なぜならば、出勤か否かというところを確認するために行っているからという回答でございました。","voiceIndex":179,"id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"さまざまな場所で業務はやっているということですけれども、それならば、休日のタイムカードを打刻しないということではなくて、学校ではない場所でも業務をしている人の実態も把握できるようにしていくことこそ求められていると思いますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"現実的に民間企業でも、家にいたり図書館に行ったり、さまざまな方がいらっしゃるかと思いますけれども、どれを仕事としてどれを仕事としないというのは把握が困難であると思います。","voiceIndex":181,"id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"特に、学校に行く方は、やはり先ほどもご答弁があったとおり、業務を行っているわけですから、そこはしっかりと把握できるよう、タイムカードで打刻できるようにすべきだと思いますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"そこに、来校した教員、そのほかの者も含めて、誰が何のために来たのかを記載することになっておりますので、こちらについては、管理職が必ず確認し、押印することとなっております。","voiceIndex":183,"id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に対策についてですけれども、一般質問の教員の多忙化解消を求める質問に対する答弁で、働き方改革は学校の実態を把握しながら進めており、多くの教員が負担に感じていることの第１に、調査や報告書の作成があることから、本区では調査の大幅削減を行ったとのことでした。教員が負担に感じていることの２番目、３番目は何か伺います。","respondent":"熊谷指導課長","answer":"これが負担の第１位。第２位につきましては、それぞれ違うのですが、教員に関しましては研修会等の報告書の作成、それから３番目としましては、保護者・地域からの苦情対応が負担感だと答えております。","voiceIndex":185,"id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際に忙しい。実態を見ても、遅くまで残って勤務時間が１１時間にもなっているという方もいらっしゃるということですから、そこはしっかりと是正していっていただきたいと思います。都の勤務実態調査では、平日授業、主担当と補助を合わせて、小学校は４時間２０分、中学校は３時間３０分やっています。これをしっかりと是正していく。３０人学級が一番の対策だと思いますが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"本区では、既に少人数指導や教科担任制、そして本区ならではの固有教員を採用しています。こうして複数の教員が丁寧に子どもたちを見る体制を品川区ではとっております。ですので、学級編成につきましては、国基準である義務標準法、および都の基準に基づき進めてまいります。","voiceIndex":187,"id":"exchange-083"},{"speaker":"のだて委員","kind":"質問","question":"そういった教員の配置をしているというのは非常勤ですから、公務負担も分担されないので、増やしてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-084"},{"speaker":"渡辺委員","kind":"質問","question":"３４９ページ、体力向上推進事業、３４５ページ、品川教育ルネサンス、２点伺います。特に私などがよく聞くのは、人がやることですから、学校がそれぞれあるときに、キャラクターと言ったら変ですが、人によってどうしても違ってしまう。こういう人がうちの学校は来た。そして、次年度を含めて今後、どのような形でテクニカルアドバイザーを、整えていくと言うと変ですが、改善できるのか、教えてください。","respondent":"大関教育総合支援センター長","answer":"中学校、後期課程につきましては、ダンスのプロの指導者を配置しています。課題といたしましては、どうしても個人差はあるというご指摘はありましたが、業務委託をしておりましたので、直接、学校現場の校長が指導できないという部分が課題で明らかになりました。","voiceIndex":191,"id":"exchange-085"},{"speaker":"渡辺委員","kind":"質問","question":"まさにもう把握されている中で改善のお話かと考えています。特に、何というのでしょう、縛りといいますか、個人の方のよさが出し切れていないような気もします。続いて、同じように、体力向上推進事業の中の、外部講師を招いた教室的なものは大変好評だと聞きました。伝え方もうまいし、即効性があったと。専門的な部分を考えるうまさを踏まえて取組みを拡充できたらいいのではないかという思いで伺います。","respondent":"大関教育総合支援センター長","answer":"そんな部分も認められましたので、各校の工夫はこれからますます盛んになっていくのではないかと考えております。","voiceIndex":193,"id":"exchange-086"},{"speaker":"渡辺委員","kind":"質問","question":"品川教育ルネサンスのことを伺います。その中でも項目としたらプログラミング教育です。先ほど、あくつ委員からも出ておりました。専門教科ができるわけでは決してないので、通常の取組みにどう活かすか。一朝一夕ではないという、取材といいますか、個別に伺ったときに、やはり積み上げ、それとやはり、また大もとの教えてくれる先生の先生といいますか、その辺の感想を持ちました。","respondent":"大関教育総合支援センター長","answer":"京陽小学校の実践を参考に、ほかの学校でも、スクラッチだけではなくて、さまざまな取組みがあるという認識が広がってきておりまして、次年度、６校は、学校のほうから、ぜひさまざまなプログラミング教育に取り組みたいという申請があった学校に対して、今回。","voiceIndex":195,"id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"京陽小学校で伺ったときには、やはり直接、ＩＴがどうこうではなくて、物事の本質を考える。ただ、このように話していても、これからやることですし、あと文部科学省の答申等で、２０２０年には、小学校も必修化であると。うちの学校はまだだなどと不安にならないような情報伝達と、やはりプログラミングというものの定義は、いち早く紹介が必要だと思いますが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"次年度、６校取り組むうち２校は、東京都のモデル校にも申請していますので、全都での取り組み報告等は、各学校に報告書が案内される流れを次年度は予定しております。そういった学校を徐々に増やしていくことで２０２０年度を迎えたいと考えております。","voiceIndex":197,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"３６３ページの学校給食放射能検査です。先ほどの質問の中で、本当に残念に思います。安心ではないですか。それで、なおかつ、安全だと言っているものに対して、なぜ品川区が税金を使って検査しなければならないのでしょうかというのが１つ。生活しているのに、そこで放射能のチェックをして、安全ですと、なぜ言わなくてはならないのですか。次に、３４３ページの生徒指導対策等経費、不登校対策です。","respondent":"有馬学務課長、大関教育総合支援センター長、熊谷指導課長","answer":"移動教室につきましては、確かにそのとおり、こちらから、あえてどうだこうだということは言わないような形で進めたいと考えています。そのうち、マイスクール八潮のほうで、３０名程度対応しています。そのほか、マイスクール五反田、新たにできたほうでも、３０名近くの対応をしております。ですので、一番は、自己申告でそれぞれ年３回、教員は、こういうことをしていきたい、こんなことをやっていきたいということを。","voiceIndex":200,"id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"放射能検査につきましては、そろそろ、もうやめてもいいのではないでしょうかというメッセージを伝えておきたいと思います。なので、他部署との連携も必要だと思うので、今後、そういうことをしていただきたいと考えています。働き方は、ぜひ先生方の意欲を損なわないような形で進めていただきたいと思いますが、最後に１つお願いします。","respondent":"大関教育総合支援センター長","answer":"子ども・若者計画にも参加いたしまして、やはり、ひきこもりとも関係する課題として捉えております。今後とも関係各課と連携を深めてまいります。","voiceIndex":204,"id":"exchange-090"},{"speaker":"塚本委員","kind":"質問・要望","question":"新学習指導要領についての解説が文部科学省から出ていて、このプログラミング教育の部分について、子どもたちが将来、どのような職業につくとしても、時代を超えて普遍的に求められる、プログラミング的思考を育むと、このようになっているのですけれども、まず、義務教育９年間の中で、品川区として、プログラミング的思考を育むということについての意義というものについて考えをお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"教科書が今後改訂される中で、新たにプログラミング的な思考がどのように取り入れられていくかという部分は、引き続き情報収集に努めてまいりますが、多分、発展的課題等において、デジタル教科書の一部を活用できる。","voiceIndex":207,"id":"exchange-091"},{"speaker":"塚本委員","kind":"質問","question":"そういうところの根幹的なところにおいては、教育委員会というか品川区全体として統一的に進めていくような考え方を持っていたほうが、現場の負担軽減や共通理解、各校で同じような課題に同じように苦しむなどということがないように、そういうところのメリットがあるのではないかとも思いますけれども、こういった今後の進め方について。","respondent":"大関教育総合支援センター長","answer":"そういった部分をぜひ、各校で取り組む中で、全校に広めたほうがいいものは何であるか、あるいはどのようなやり方があるかという部分は、次年度の６校の成果も踏まえまして検討してまいりたいと考えております。","voiceIndex":209,"id":"exchange-092"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。私が考える上では、外部との連携という意味では、結構プロフェッショナルなレベルの、単にパソコンに詳しいとか、ある種の機材がいじれるなどということよりも、先ほどから申し上げていたプログラミング的思考というところの育みというところを外さないようにしていくにあたって、外部のプロフェッショナルな知識を持っている人たちに協力を求めることが必要かと思います。教えてください。","respondent":"大関教育総合支援センター長","answer":"品川コミュニティ・スクールを通じて、もしかすると、地域の方、保護者の方の中で、非常に堪能な方もいらっしゃるかもしれません。そういった方の協力を得る、そのような学校もあろうかと思いますので、状況に応じて柔軟に対応してまいりたいと考えます。","voiceIndex":211,"id":"exchange-093"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。これは、よろしくご検討いただきたいと思います。それで、家庭教育学級のことに絡めての質問になるのですけれども、いわゆるプログラミング教育を今後進めていく上で、保護者の理解というのも一面、必要な部分かと思っています。","respondent":"大関教育総合支援センター長","answer":"さまざまな機会を通じて、保護者、地域の方々に成果を広めてまいりたいと思います。","voiceIndex":213,"id":"exchange-094"},{"speaker":"大倉委員","kind":"質問・要望","question":"ページ数はわからないので、学校教育の中でダンスというところと、先ほど松永委員からもありましたが、避難訓練、あわせて防災訓練について伺いたいと思います。現在、ダンスが取り入れられて数年たちますが、授業内容、大体の時間とその目的を改めて伺いたいと思います。先生が小学校で、特になかなかダンスをやったことがないという中で、どのようになっているでしょうか。","respondent":"大関教育総合支援センター長","answer":"中学校および義務教育学校後期課程におきましては、体育の中でダンスを１０時間学ぶことになっておりまして、各校に対してテクニカルアドバイザー、ダンスのプロの指導者を６時間配置して、教員とダンスのプロとで子どもたちにダンスを教えるのが、高学年。","voiceIndex":216,"id":"exchange-095"},{"speaker":"大倉委員","kind":"質問・要望","question":"研修などは、やっているのかどうかというのを教えていただきたいのと、本当に今お話にもありましたが、今、子どもたちはいろんなところでダンスをやっていて、私の知っている限りでもかなり多くの方がやっているかというところで、先生が楽しんでダンスを教えられるというのが、子どもたちにとっても、このダンスの取組みに関しては。","respondent":"大関教育総合支援センター長","answer":"教員の意見といたしましては、やはりダンスが必ずしも得意な体育教員ばかりではありませんので、その支援としてテクニカルアドバイザーを配置しているといった状況です。","voiceIndex":218,"id":"exchange-096"},{"speaker":"大倉委員","kind":"質問・要望","question":"わかりました。例えばダンスで、今、品川区でもシティプロモーションで、「Promise～シナガワにきっと～」の踊りをやっているという中で、そういったものの活用などというのは、品川区の学校でやっていくと、これがさらに広がっていくのかなどということも思っているのですが、そのことについてお知らせいただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"ご提案いただいた区のシティプロモーションの内容等につきましては、例えば児童・生徒会の子どもたちが、あれを見て、自分たちで何か学校の発表会の中で取り組もうとしている、そういった場面も考えられますし、校長連絡会で、見せたこともありますので。","voiceIndex":220,"id":"exchange-097"},{"speaker":"大倉委員","kind":"質問・要望","question":"学校の避難訓練、防災訓練について伺いたいのですが、避難訓練は実施、毎年行われていると思うのですが、その状況について教えていただきたいのと、防災訓練についても行っているのでしょうか。お知らせください。もし行っているのであれば、どういった内容で行っていて、回数と、また地域ごとに内容がもし違うような取組みが行われているのであれば教えてください。","respondent":"大関教育総合支援センター長","answer":"例えば、親子で一緒に出る中で、実際にＡＥＤ訓練をやったり消火活動をやったりという地区もありますし、あるいは日曜日という状況もありますので、それぞれのご家庭のご都合など、いろいろな部分があるので、ご案内だけにとどめて、教員が何名か参加して。","voiceIndex":222,"id":"exchange-098"},{"speaker":"大倉委員","kind":"質問・要望","question":"今、品川コミュニティ・スクールも言われて、地域とのつながりというところでさらに進んできている中で進めていっていただきたいと思っているのですが、子どもたちのアイデアを活かした公園というのを品川区も既にやられている中で、例えば子どもたちのアイデアを活かした防災訓練や、子どもたちのアイデアを聞きながら、今ある既存のＮＰＯとも連携した防災訓練を目指して。","respondent":"大関教育総合支援センター長","answer":"どういう状況にあろうかは学校ごとに中学校区ごとに、さまざまな状況もあろうかと思いますので、引き続き地域の方のお声も聞きながら、子どもたちの教育にとって何が一番重要かというものを考えながら進めてまいりたいと考えています。","voiceIndex":224,"id":"exchange-099"},{"speaker":"大倉委員","kind":"質問","question":"まさに子どもたちの防災意識の向上というところで、なかなか防災訓練をやるところがなくて、実際、地域の町会・自治会でやるのが多いのかというところで伺いました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"３４５ページの連合行事費についてお聞きしますが、その前に、先ほどの須貝委員の質疑で、関連で１つだけ質問させてください。先ほど答弁で、９１％の保護者が満足しているという答弁がありまして、その９１％の一人として少し質問したいと思います。私ごとだったので、これまでは控えてきましたが、今日は特別に聞かせていただきたいと思います。そういうケースもあるということです。","respondent":"熊谷指導課長","answer":"通塾率、塾に頼っていない生徒ですが、東京都が３０％なのに対し、品川区は塾に頼っていないのが３２％ぐらいの割合でおります。","voiceIndex":228,"id":"exchange-101"},{"speaker":"本多委員","kind":"質問","question":"ちなみに、小学校のときの担任の先生が、今日、理事者席にいらっしゃいますので、ただただ感謝するばかりで質問に移りたいと思います。３４５ページの連合行事費なのですが、音楽鑑賞教室、連合体育大会、学習成果発表会、特別支援学級連合学習発表会、連合作品展、それぞれ毎年、連合行事に取り組まれているのですけれども、それぞれの昨今の状況と、平成３０年度の計画について概要を教えてください。","respondent":"大関教育総合支援センター長","answer":"次年度におきましても、非常に保護者、地域の方からも期待されている内容ですし、学校にとっても、１つの行事に向けて、子どもたちが一丸となって、目的を持って練習していくという、非常に重要な連合行事は今後も教育委員会として支援してまいりたいと考えております。","voiceIndex":230,"id":"exchange-102"},{"speaker":"本多委員","kind":"質問","question":"センター長のそれぞれの行事に対する熱い思いが伝わってきました。それで、それぞれのやはり行事が充実して、一生のいい思い出になっていただければと思いますが、それでいろんな経験を踏まえて、自信や達成感や悔しさや、次へのステップとか、そういったところを聞きたかったのですが、最後にこれだけ教えてください。その点だけ、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"歴代の記録は冊子という形で配布しています。","voiceIndex":232,"id":"exchange-103"},{"speaker":"浅野委員","kind":"質問","question":"私からは、３５９ページの校舎等整備、３６５ページの電波障害対策、これは城南小学校です。時間があれば３５７ページの学校ホームページ経費について質問します。防犯カメラ取替工事費ですけれども、小学校５校、中学校１校、義務教育学校２校ということですが、今回の取りかえの理由について教えていただければと思います。この防犯カメラにいたずらをされたとか、そういう例があれば教えてください。","respondent":"品川庶務課長","answer":"学校の防犯カメラの件ですが、学校の防犯カメラは平成１８年ぐらいから導入しております。ですので、最近、ここ二、三年なのですけれども、ハードディスクの障害が原因で、カメラが壊れるという例が大分出てきております。","voiceIndex":236,"id":"exchange-104"},{"speaker":"浅野委員","kind":"質問","question":"いたずらとか、そういうものは今のところないと伺いました。そういう中で、ハードディスクですけれども、やはり振動とか、そういうことには弱いと言われております。３６５ページの電波障害対策、それと、時間があれば３５７ページの学校ホームページ経費について質問します。影響する世帯数ですとか、今現在、もう既に地域の方と協議されているのかどうか、その辺について教えてください。","respondent":"篠田学校計画担当課長","answer":"それで、これから先の対応なのですけれども、基本的に対策工事につきましては、学校の改築工事自体、始まっているのですけれども、本体が立ち上がる前、新しい年度に入りましてから、７月から１０月あたり、個別にそれぞれ対象となるお家を回りまして。","voiceIndex":238,"id":"exchange-105"},{"speaker":"浅野委員","kind":"質問","question":"すみません。少し聞き取れないところもあったのですけれども、業者については決まっているという内容だったのかどうか、少し聞き取れなかったので、この点を１つお願いしたいと思います。工事自体については７月から１０月にかけて交渉するということですけれども、実際にこれを対応するのは、ケーブルテレビ品川なのか、それとも違う業者なのか、その辺についても教えていただければと思います。","respondent":"篠田学校計画担当課長","answer":"それで、対象の工事、７月から１０月までという形で申し上げたのですけれども、こちらはやはり専門の業者がそれぞれのお宅を回りまして、ケーブルテレビとつなぐような形で対応をとっていくということになったものです。","voiceIndex":240,"id":"exchange-106"},{"speaker":"浅野委員","kind":"確認","question":"７月から１０月にかけて交渉するというお話ですけれども、学校も高層化というのでしょうか、高く建てるような傾向がどうしても見受けられますし、またそのほうが効率的だというのもあるかと思います。次にいきます。３５７ページの学校ホームページ経費について質問します。そこに実際に書かれていないケースも、今日の時点で確認しましたら何件かありました。","respondent":"大関教育総合支援センター長","answer":"ここがたまたま写真を入れかえたり、さまざまな理由で一旦工事中になっているタイミングで、たまたま見ていただくと、そういうケースもあるかもしれませんが、それが回数を重ねてしまうと、多分、信頼を失うことになろうかと思いますので、ここはまた引き続き学校に対して。","voiceIndex":242,"id":"exchange-107"},{"speaker":"南委員","kind":"質問・要望","question":"３５５ページの指定管理者運営委託について質問したいと思います。それで、募集要項に出ている、留意事項が書かれているところがあるのですけれども、その関係で少し伺いたいのと、私はやはり守秘義務や法令順守等々の部分については、業務要求基準書のほうにしっかり書くべきではないかと思っているのですが、募集要項のほうに書いてある意味についても教えていただきたいと思います。","respondent":"横山品川図書館長","answer":"決定の後は協定書を取り交わして、情報管理についてもしっかりとしていただくように図っていく予定です。その要求書に基づく提案の中で、研修制度についてもそれぞれの事業者からご提案をいただいております。","voiceIndex":245,"id":"exchange-108"},{"speaker":"南委員","kind":"質問","question":"それで、その内容について、やはりどの程度のものなのかを区としてチェックしなければいけないのではないかと思っているのですけれども、その辺について、また守秘義務はもちろんですけれども、図書館業務に関するさまざまな法令等々が、品川区の条例もそうですけれども、たくさん、募集要項のほうには書いてあるのですが、それも全部チェックしているという認識でいいのかどうか伺います。","respondent":"横山品川図書館長","answer":"今回のご質問で、研修についての確認ですが、運営に当たりましては、必ず月次で報告書をいただいておりますので、研修の進行についてもご報告いただいておりますし、また月に１回、地区館長会議という形で、口頭での確認とあと指導等も行っていっているような状況です。","voiceIndex":247,"id":"exchange-109"},{"speaker":"南委員","kind":"確認","question":"確認したいと思います。しかし、区が指定管理者選定に当たっては、労働法令や雇用・労働条件への配慮の規定を課しているというふうになっていると理解するのですけれども、こことの関係では、ころころ変わっているというところの実態があるのかどうか、つかんでいるのかどうか、またそういう状況についてどういう理由かというのを、品川区として把握しているのか、できていないのか、その辺について伺います。","respondent":"横山品川図書館長","answer":"委託の件ですが、清掃のほかに機械設備の管理についても委託しています。職員について、人材として重要だという点については、公共図書館においても共通の認識でおりますので、どういう人がどういうところにいらっしゃるかというのは常に報告をいただいて把握しています。","voiceIndex":249,"id":"exchange-110"},{"speaker":"南委員","kind":"質問・要望","question":"そうであるならば、好きな仕事をやめるということは、例えば家族もろとも転勤するとか引っ越しするとか、特別の事情がない限り、私は頑張って働いていただけるものだと思っているのですけれども、そうではなくて、ころころ変わる状況が、どういうことかはわからないけれども、そういう実態についてきちんと把握して、正すべきところは正すというふうな指導をしていかなければいけないと考えていますので。","respondent":"横山品川図書館長","answer":"委員ご指摘の法令の明記につきましては、この後、指定管理につきまして協定書を交わす予定ですので、協定書がいわゆる契約書になりますので、そちらに法令を改めて項目立てて契約するような形で運びたいと思います。","voiceIndex":251,"id":"exchange-111"},{"speaker":"南委員","kind":"質問","question":"最後に、利用者懇談会というのを、最近というか、ここ１０年ぐらいなのか、期間は忘れてしまったのですが、やっていたのがなくなって、ずっと経過が来ているということで、指定管理になって３年、今回また新たな指定管理になっているのですが、やはり私は、利用者懇談会というのはもう一度再開するべきだと思っているので、その点についての認識を伺いたいのですけれども、さまざまなモニタリングだとか。","respondent":"横山品川図書館長","answer":"そういう意味で、広くご意見をいただいて運営するに当たって、利用者懇談会が有効に機能できるかどうかについて、これから検討してまいりたいと思います。","voiceIndex":253,"id":"exchange-112"},{"speaker":"南委員","kind":"質問・要望","question":"直接聞くということは、全然質が違う、次元が違うと思いますので、今までのことをきちんと、どこがまずかったのかを精査して、やはりしっかりと開催していただけるように努力していただくことを要望したいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":255,"id":"exchange-113"},{"speaker":"石田（秀）委員","kind":"確認","question":"私は、３４１ページ、クラブ・部活動等経費、あと３４７ページ、合同部活動、あとは外部指導員、中学生の部活動について、特にスポーツで、必ずいろいろスポーツに携わってもらって、中学の部活動をよくしてほしいという意味合いで質問します。本人は信念を持って続けてきたけれども、これには子どものことがどこにも書いてないではないですか。そういう確認ができているのか。こういう資格を取っていく。","respondent":"大関教育総合支援センター長","answer":"その部活動の内容にもよりますが、やはり土曜日、日曜日に大会等があるような部活動ですと、１人では難しいので、やはり複数の教員が顧問団に入ることで、それぞれ輪番のような形で引率をやったりしているような実情があります。","voiceIndex":257,"id":"exchange-114"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひよろしくお願いします。本当に中学の部活動はぜひよろしくお願いしたいと思います。これは、もうこれでやめます。資格もぜひチェックしてもらって、先生方にはそういう、特に子どもたちの体のこととか、いろいろなトレーニングの方法など学んでほしいと思います。これはすごいことで、多分これより後の事故なので、この寄附してくれたヘルメットをかぶって助かったという理解でいいでしょうか。","respondent":"大関教育総合支援センター長","answer":"ないお子さんに対して寄贈いただいて、全員がかぶるようになったというのが現状です。","voiceIndex":259,"id":"exchange-115"},{"speaker":"石田（秀）委員","kind":"質問","question":"非常にいいことで、話を伺ったら、毎年、入ってくるお子さんの分はいただけるみたいな、寄贈していただけるということだと、６年生は持ち上がって７年生になるので、中学生になってもかぶる。せっかくそういう形で、今、命も守れたということであれば、中学生に対しての指導、これから３年かかってもいいわけですけれども、そういう指導・啓発というのはどうお考えでしょうか。","respondent":"大関教育総合支援センター長","answer":"今、６年生までがヘルメットをかぶるという習慣がようやく定着してまいりましたので、校長会とも協力いたしまして、引き続き４月以降、今度は７年生はやはり引き続きヘルメットをかぶり、自分で自分の命を守ろうという呼びかけは。","voiceIndex":261,"id":"exchange-116"},{"speaker":"石田（秀）委員","kind":"意見","question":"ぜひよろしくお願いします。最後に３４７ページ、地域の歴史・文化学習についてお願いしたいと思います。これは、どこかで、例えば小学校４年生は全員やる。授業の中でもいい。そうすれば、学校の先生も地域のことを覚えるわけで、それが小学校３年生でも、４年生でもいいけど、どこかの学年でしっかり、全生徒がやるというような形をとってほしいと思うのですが、お考えをお願いします。","respondent":"大関教育総合支援センター長","answer":"中学生以降も、その伝統文化をどう守っていくのかを考える単元が市民科にはありますので、小・中学生、義務教育学校をあわせまして全校で、次年度は取り組めるように考えております。","voiceIndex":263,"id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"順番が前後しますが、３４５ページ、区立学校教育要領ですが、一般質問でもお尋ねしたのですが、そこの中で、中間報告やパブリックコメントを求めることは必須と考えていない、捉えていないということですが、なぜそういうふうな状況になったのか、示さなかったのかという理由がわからなかったので、改めてお尋ねいたします。公開することについてどのような課題があるのでしょうか。２つお尋ねします。","respondent":"熊谷指導課長","answer":"９年間を見据えてというところで、国がつくっております小学校用の学習指導要領、そして中学校用の学習指導要領を、９年間見通せる形で改めてつくり直したものですので、学習指導要領の中間答申でパブリックコメントをとっているということを踏まえて。","voiceIndex":267,"id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"教育要領は、教員の方々百数名、そして専門の方をというお話がありますが、やはり多くの区民の方のご意見を伺い、そして議会にも状況を説明し、そしてよりよい形で進めていく。そういったことが、議会や区民の方と進められていくべきだと思っています。なぜ、せっかく全学年でやったのに、改めて公表して議論を深めていこうと考えないのか、私にはわからないので、その点をもう一度お願いします。","respondent":"熊谷指導課長","answer":"区の学力調査ですけれども、これまで４年生と７年生で、かつて学力調査の結果を示してきましたけれども、ちょうど、こちらにつきましては最初に、国が始める前、都が始める前から、この調査を行ってきたというところがありますので、その中で、区の全体として。","voiceIndex":269,"id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれお話を伺いました。よりよい教育を進めるためにも、全体像を見て深まった議論をする必要があると私は思っています。教育委員会は、学校には学校公開をしろといって現場には公開を求め、そして新学習指導要領は初めて前文がつくられ、その中で、開かれた教育課程というキーワードも出されています。ぜひ、今の２点については明らかにしていっていただきたいと思っています。お尋ねします。","respondent":"熊谷指導課長","answer":"中心となる教員が出てしまうことにつきましても、まずは必異動ということがありますので、対応していきたいと思います。","voiceIndex":271,"id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"これについて、さまざま確認させていただきたいと思います。４つお聞きいたします。学級閉鎖の基準を教えていただきたいと思います。これもお聞きします。２つ目に、今回、９年生の学級閉鎖がないと報告では出ておりますけれども、この理由をお聞きしておきたいと思います。３点目に、インフルエンザによって重症化、また合併症など、重篤化してしまった事例はありますでしょうか。以上４点お聞きします。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"そのほか、手洗い、うがいとマスク等の、それ以外の部分につきましては、国からの通知にもありますけれども、インフルエンザにかかった場合、薬を服用する・しないにかかわらず。必ずしもそのとおりだという証明が区内でできているわけではございませんが、歯磨き指導をしていることによって、うがいをする習慣が高まることで、やはりインフルエンザ、風邪等が予防されるのではないかなどが。","voiceIndex":274,"id":"exchange-121"},{"speaker":"若林委員","kind":"質問","question":"続けて、９年間を終えて、ちょうど高校受験の時期になります。それから、続けまして、今年度からインフルエンザ等で高校受験ができなかった生徒に対する、追検査を区立高校においてはするということが発表されておりますけれども、既に３月９日、予定どおりであれば行われていると思いますけれども、品川区では追検査を受けた生徒がいらっしゃるかどうか、把握されているかお聞きしたいと思います。","respondent":"有馬学務課長","answer":"同じ学級で二度、三度と頻度が多くなれば、例えば７時間目を設定するということもあるかもしれませんけれども、基本的にはその中で対応はできていると考えています。給食の食材につきましては、一応、学級閉鎖による場合は、２日目以降の分については返金。","voiceIndex":279,"id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"それで、毎年、これだけの、今般の文教委員会でも、ますの数としては７５ますの臨時休業、学級閉鎖、学年閉鎖は入っていますけれども、そういう状況がある。それから校長会や事務局の中でも、今後、学級閉鎖を中心にしたインフルエンザの対応の仕方については、ぜひまたもう一回、原点に戻って議論していただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":281,"id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問","question":"私は３４０ページ、教育総務費、それから３５４ページ、学校教育費、それから３５７ページ、ＩＣＴ教育推進に関連して質問します。その方に、品川区の教育改革についていろいろ聞いてみました。改革だけに特化して、教育は基本的に後回しではなかったのではないかと指摘はありましたけれども、最も大切なことは改革の精神を、今の教育長はじめ、品川区がどう受け継いで発展させていくのか。お願いいたします。","respondent":"熊谷指導課長","answer":"今、委員からご指摘がございましたように、平成１１年度にスタートした「プラン２１」ですけれども、やはり教職員の意識改革、そして学校教育の質的転換を目指して進めてきたものです。その結果、開かれた学校づくりですとか特色ある学校づくりが進んだところです。","voiceIndex":283,"id":"exchange-124"},{"speaker":"伊藤委員","kind":"質問","question":"例えば、教育の専門家の方々の意見も評が分かれました。もちろん、教育そのものが答えがないものであるのはわかるのだけれども、やはり前教育長があれだけの改革をしてきて今の品川区がある。それで、今度それをどう、さらに発展していくかということについて、何というか、例えば教育次長などから改めて答弁をお願いしたいのですが、いかがでしょうか。","respondent":"本城教育次長","answer":"そういう意味で、「プラン２１」から続けてきた今の品川教育ルネサンスを、より具体化するのが今のプロセスで、そのために、教育委員会としては全力を尽くしていると考えているところです。","voiceIndex":285,"id":"exchange-125"},{"speaker":"伊藤委員","kind":"質問","question":"これから質問する内容は、所管としては健康推進部の所管、出張型健康学習、中学生だから、ふれあい授業でありますけれども、中学校での事業展開なので、ここであえて質問します。だから、いじめ撲滅はもとより進めていってほしいのだけれども、こういう命の大切さ、尊さを生徒に直接伝える教育は、私は絶対に必要だと思うのですけれども、品川区のお考えをお聞かせください。お願いいたします。","respondent":"大関教育総合支援センター長","answer":"赤ちゃん触れ合い事業だけでなく、さまざまな形で、それぞれの発達段階に応じて、命の大切さは引き続き深めてまいりたいと考えております。","voiceIndex":287,"id":"exchange-126"},{"speaker":"伊藤委員","kind":"意見","question":"どんなものにもかえがたい教育です。だから、私としてはできれば区内の全中学校でこういう授業を展開していただいて、繰り返しますけれども、通常の授業を削らなければいけないことはわかるのだけれども、やはりそれは、大きな意味では、いじめ撲滅に関係して、展開できると思うのですが、改めて答弁をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"その際に、準備のためにお母さんが小さな赤ちゃんを連れてきてくれて、その面倒を見て実際に子どもたちが触れ合っているのが、各校、実際にありますので、非常にその効果はあると認識しております。","voiceIndex":289,"id":"exchange-127"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、今の答弁を理解する部分はあるのだけど、できれば区内中学校で展開していっていただきたい。だけど、そういうことを踏まえていくと、私立の某中学校と公立の中学校をたまたま見たものだから、非常にその差があったということを、さまざまな思いをしながら質問しているわけで、改めてＩＣＴをフル活用した品川区としての授業展開が急務と考えますけれども、品川区のお考えと計画をお聞かせください。","respondent":"有馬学務課長","answer":"１人１台にはなりませんけれども、有効に各授業で電子黒板と一緒に、そういうタブレット型の学習ができるような環境は順次整えていきたいと考えております。","voiceIndex":291,"id":"exchange-128"},{"speaker":"伊藤委員","kind":"質問","question":"ＩＣＴ化の波というのは、まずとまることはないわけですが、確かに順次進めていることはわかるけれども、生徒一人ひとりがそれを持っていないということは、ご自宅にあるかもしれませんけれども、例えばワードやエクセル、それからパワーポイントを使って自分のプレゼン資料をつくっていくということは、避けて通れない道でありますから、ぜひ品川区の教育現場でそういうことを取り入れていただいて。","respondent":"大関教育総合支援センター長","answer":"まだ現状においては差がありますが、ただし、区の施策として、各学校をアピールする内容を実際に児童・生徒自身につくってもらおうというプロモーションを投げかけて。","voiceIndex":293,"id":"exchange-129"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、３５７ページ、学校ＩＣＴ活用経費について、３４１ページ、義務教育学校標準服費に関連して制服について、それと３５３ページ、図書館運営費に関連して電子書籍について、３４７ページ、市民科についてお伺いします。制服についてです。初めにお伺いしたいのが、品川区において、電子書籍、電子図書館の考え、またこれまでの検討状況をお示しください。とりあえずそこまででお願いします。","respondent":"有馬学務課長、大関教育総合支援センター長、横山品川図書館長","answer":"活用については、委員がおっしゃるとおり、音声ですとか図形の展開ですとか、いろいろ使えるということで、有効だということは認識しております。これまでも、アクセス・リーディングおよびデイジー教科書ということで、個別の配慮が必要なお子さんにつきましては対応してきている実態があります。一貫校の時代に標準服というのをつくっておりますけれども、その当時、開設する前に特に準備委員会設置みたいなことがございまして。","voiceIndex":296,"id":"exchange-130"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"２０１７年度の調査の中で、整備率ランキングというのがあって、品川区を見たら５５.６％という整備率です。ほかに幾つかの２３区の自治体が１００％という整備率だというのも確認したので、その点はぜひ頑張っていただければと思います。公正取引委員会が中学校の制服に関して７つの提言というものを発表しております。座間市での少女など、悩みの投稿につけ込んだ、９人の殺害事件もありました。","respondent":"有馬学務課長、横山品川図書館長、大関教育総合支援センター長","answer":"ただ、中学校のほうの数字は例えば６０周年記念で変えたなどということもありますので、販売店の価格等はきちんと見ていきたいと考えています。先ほどお伝えしましたように、コンテンツの数がそろって、浸透が進んだ状況で、改めて正式に検討・導入させていただきたいと考えています。そのようなプランなども、今、教育委員会としては検討している最中です。","voiceIndex":301,"id":"exchange-131"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは何で始めたかというと、図書館流通センターからオファーが来て、２年間、無償で試行としてやってくださいということで、渋谷区と連携して、そういうことを行っている。なので、ぜひ検討していただきたいと思います。なので、できる限り早く、導入とは言わずに検討をどんどん進めていっていただきたいと思いますので、よろしくお願いいたします。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":305,"id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"特別支援教室、いわゆる通級を利用されている子ども、児童・生徒の数、それから特別支援学級を利用されている児童・生徒、そして特別支援学校に通われている区内の児童・生徒の人数をそれぞれ教えていただきたいのと、あと、今、特別支援学校に行く子が多いと保護者の皆さんからも声が寄せられているのですけれども、利用の傾向や特徴があれば少し伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"傾向といたしましては、特別支援学校の場合、スクールバスがありますので、やはりそちらがある中で、いろいろ選ばれた中で、そちらを利用される保護者もいることもありますし、あと、やはり手厚く一人ひとりの対応をしている学級も。","voiceIndex":307,"id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"確認","question":"ほかの区には行かれていないということでしょうか。これを確認したいのと、あと特別支援教室、平成２８年度から全ての区立小学校、また義務教育学校の前期課程で実施され、平成３０年度からは中学校もということですけれども、訪問指導教員は何名いて、１名の方が何校受け持っているのかというのも教えてください。","respondent":"大関教育総合支援センター長","answer":"したがいまして、単純に計算するならば、教員１名当たり１０名のお子さんを担当しながら、ただし週１回程度訪問したときに、それぞれの学校にいるお子さんに丁寧に対応しているというのが、特別支援教室の内容となっております。","voiceIndex":309,"id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問","question":"子どものころからの交流が大変重要だと述べられています。品川区の特別支援学級ですけれども、以前からもお話は出ているのですけれども、校内での配置が、人目につかないような場所にあると。それで、今、全ての特別支援学級がそうだとは思いませんけれども、やはり校内での配置場所を改めて考え直す、そして学校全体で支えるという環境を整えていくべきではないかと思うのですけれども、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"こういった部分は、お一人おひとりの障害の程度・状態に応じて、個別対応はこれからも続けてまいりたいと考えております。","voiceIndex":311,"id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひお願いしたいと思います。平成３０年度に新たに２カ所の特別支援学級が設置されるというふうに予算書にもなっているのですけれども、新たに学級を設置するという経緯というのでしょうか、全校に置いてほしいという親御さんからの意見等もあったりするのですけれども、こういった学級を新たに設置するというところでの、どうしてそうやって進んでいくのかという経緯を伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"そういった中で、そのときの児童・生徒の実態等を踏まえながら配置はしておりますが、それぞれのお子さんごとに、非常にさまざまな障害の程度・態様や発達段階もありますので、私どもの１つの考え方としては、東京都の場合には。","voiceIndex":313,"id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"わかりました。特別支援学級は、場所の問題、改築等でもということでしたので、今、改築計画がまた進んでいる学校もありますので、ぜひ考慮していただきたいと思います。それから、特別支援教室についても、当事者の状態や教育の場としてふさわしい環境を整えることを求めて、次の質問にいきたいと思います。この予算の変化の経緯と理由を伺いたいと思います。なぜＣ評価になったのか伺いたいと思います。","respondent":"有馬学務課長","answer":"事務事業評価の結果で、放射性物質検査がＣ評価だですけれども、この間、いろいろ、こういった議会の場でもそうですし、内部でもそうですし、放射性物質の検査をどう取り扱うかということは内部でも検討してきております。","voiceIndex":315,"id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問","question":"予算から見ても縮小が図られていることもわかります。そして報告書には、教育委員会からの意見として、廃止も含めた検討が必要であるとあります。ですので、この報告書を見ると、区は何だか親の不安が落ち着いたというふうに捉えられるような文言もあるのですけれども、現在の原発がどうなっていると区として考えているのか伺いたいと思います。","respondent":"有馬学務課長","answer":"教育委員会からの意見、縮小、廃止を含めた検討が必要であるということは、やはり、これまで５年間やってきた実績で、一度も検出されていないということを踏まえて、あとはそれぞれの流通段階において。","voiceIndex":317,"id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり、原発事故を受けて区もやっていただいている事業だと思います。それで、一度も検出されていない。事故原因の究明も進んでいません。そして、事故を終わったことにして再稼働を突き進めるといった、本当に許せない国の政治もあるわけですけれども、そういうことで、しっかりと安全確保のために検査を続けていくということ、廃止せずに続けることを改めて強く求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":319,"id":"exchange-139"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３４７ページ、特色ある教育活動経費、２点目が３４９ページ、マイスクール運営費、３点目が３６１ページ、児童・生徒用災害時備蓄物資購入、関連して学校防災マニュアルについてお伺いしたいと思います。ページ順不同でいきます。不登校特例校というのはどのような施設なのか。東京都が特例校を推進する背景というのはどういうところにあるのか。その辺をお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"ただし、学校として行うことになりますと、教育課程の内容、例えば時間数等も非常に縛りが出てくる。あるいはどのように運用するかは、今後、今回、調布市が行う特例校がモデル的に進める中で、その成果、課題も含めて注視してまいりたいと考えております。","voiceIndex":321,"id":"exchange-140"},{"speaker":"こんの委員","kind":"質問","question":"特例校はわかりました。そうなると、今度は不登校とひきこもりということの関係で少しお聞きしたいと思うのですけれども、平成２８年の内閣府の、若者の生活に関する調査報告書によりますと、現在、ひきこもりになったきっかけは何ですかというアンケートに対して、主な回答の上位が、不登校、それに続いて次が、職場になじめなかったという、この２つが上位を占めているという結果が出ているようなのです。","respondent":"大関教育総合支援センター長","answer":"その発表会をみんなでやろうではないか。やってみた。できたという部分を大切にして、ここ数年、毎年、音楽ホールを活用して、非常に大きな成果を上げているところです。","voiceIndex":323,"id":"exchange-141"},{"speaker":"こんの委員","kind":"質問","question":"そのお子さんのやる気、やりたいことを見つけてあげる。そうした手法の１つが音楽の活動だと思います。そこへ通えるお子さんは、何とかその子の姿を見れて対応がわかるのですが、そうではないお子さんに対しては、やはり、他の所管、関係機関とも連携していく対応が必要かと思いますけれども、こうした場合もＨＥＡＲＴＳが対応するのか、あるいは他課と連携することもしているのか、現状を教えてください。","respondent":"大関教育総合支援センター長","answer":"学校の家庭訪問に合わせて、例えばＨＥＡＲＴＳのカウンセラーが夕方、家庭訪問をする中で、「じゃあ今度行ってみない」ということで、紹介して、児童センターにうまくつながった、そんなケースもあります。これは引き続き、関係各課との連携を進めてまいりたいと考えています。","voiceIndex":325,"id":"exchange-142"},{"speaker":"こんの委員","kind":"質問","question":"時間がなくなってしまいましたが、避難所の学校防災マニュアルについて１点だけ。この防災マニュアルは各学校が作成されていると思いますけれども、在校時、いわゆる授業が行われているときに発災した場合、先生たちはこのマニュアルどおりにはいかない想定外の対応の訓練、先生たちの訓練はどのようにされていますでしょうか。","respondent":"大関教育総合支援センター長","answer":"子どもたちの毎月の避難訓練以外に、校内研修として、各校は、予定どおりには動かないケースを、わざと管理職が想定して行います。","voiceIndex":327,"id":"exchange-143"},{"speaker":"渡部委員","kind":"質問","question":"いよいよ款別審査も最後になりました。３点お伺いします。順番にいきますが、まず最初に、今日、朝、質問でもありました、強いて言えばルネサンス推進事業、３４５ページなのでしょうか。そのような中で、今回、お話を伺ったところ、やはり教育委員会にも区にも、多分、私たちの方にも、いろいろな問い合わせがあったのも事実かと思います。","respondent":"大関教育総合支援センター長","answer":"年々、異常気象といいますか、やはり急激な天候の変化で、大雨警報が発令される回数も増えてきている実態もあります。そこへの基準については、今後、学校現場の声、あるいは今回お聞きした声等も含めて、今後の課題と考えておりますので、検討を進めてまいりたいと思います。","voiceIndex":330,"id":"exchange-144"},{"speaker":"渡部委員","kind":"質問","question":"承知いたしました。３６３ページの学校給食の放射性物質検査費は、民生費の中でも同様のことはお話しさせていただきました。今回、予算化されていて、民生費の中でお話は伺ってまいりましたが、改めてここの考え方、先ほど来の質問と同じかもしれませんが、私自身は、例えば何か不測の事態等が生じたときに１回検査をするというような意味での予算立てでも今年はいいと思っています。","respondent":"有馬学務課長","answer":"平成３０年度、もうこれは不用ではないかというお話しですけれども、予算として計上はさせていただきましたので、２３区の状況や出荷制限の状況など、我々が今まで判断してきたものを総合的に勘案して、確かに心配したら切りがないということもありましょうが。","voiceIndex":332,"id":"exchange-145"},{"speaker":"渡部委員","kind":"質問・要望","question":"それで、私たちはかねてから、区の固有教員の有用性を評価させていただいていて、代表質問でも申し上げたとおり、やはり教育は人ですから、何とか予算化いただいて、今後、各校に最低１名は配置をいただきたい。義務教育学校には２名置いていただきたいという思いがあります。改めて、いかがでしょうか。区の固有教員のメリットもお伝えいただきながら、その辺を教えていただけますでしょうか。","respondent":"熊谷指導課長","answer":"そういった中で、品川コミュニティ・スクールを進めていく上でも中心的存在ですので、採用の増員につきましては、調整もさまざまあるかと思いますので、今後の課題として検討してまいりたいと思います。","voiceIndex":334,"id":"exchange-146"},{"speaker":"渡部委員","kind":"質問","question":"ここ数年、６月１日から募集が始まるということは、比較的早い段階で、チラシができ上がってホームページにも掲載されますよね。最後、もう一点、お伺いします。もう簡単に聞きます。篠田課長は１回も立っていないので、学事制度についてです。平成３１年度、どのようなことを行っていくのか。できれば、このときぐらいにこういうふうに動ければというようなビジョンがあればお話しいただけますでしょうか。","respondent":"篠田学校計画担当課長","answer":"この平成３０年に関しましては、そういったさまざまな調整を含めた制度検討をした上で、早ければ平成３１年度の、例えば学校選択に間に合うような形でうまく制度化ができれば、平成３２年度からは新たな制度のもとに学校がスタートできるかと考えておりますけれども、何分。","voiceIndex":336,"id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1084#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":122959,"voices":339}},{"id":"h30-20180315-7","meetingId":"h30-cm03","date":"2018年3月15日","dateIso":"2018-03-15","committee":"厚生委員会","time":"午前１０時００分～午前１１時４４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４２号議案 品川区国民健康保険条例の一部を改正する条例","agenda":"第４２号議案 品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"国民健康保険の都道府県化については、２月２７日の委員会でも所管事務調査でもあったので、状況も理解をしているつもりです。当日、請願も２本出ていましたから、国保の全体のあり方も十分、話は理解したつもりです。改めて、今回、品川区として統一保険料方式に入ることの利点と今後の課題の点を２つ教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"それに向かって標準保険料率は考えております。そして、その中で、今申し上げたような２３区統一のメリット。品川区としては、標準保険料に関しては、２３区全体としてやっていきたいという賛同のもとに考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"統一化に反対するものではないのですが、今の中でもう一度、確認させていただきたい。医療費の高額化と統一化することのつながりが直接よく理解できなかったので、そこをもう一度、お願いします。","respondent":"三ッ橋国保医療年金課長","answer":"今回、まさに高額療養費分は保険料に算定しておりますので、その意味で、これから国民健康保険料は国保が抱える財政運営の基盤安定化という部分では、国保にかかわっている方、国保の方が払っていくことが一番大きい部分です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問","question":"医療費の適正化はぜひお願いしたい。今、私の中で理解していないところがあるので、また改めてお聞きしたい。課題としては、医療費の高額化。これは国保全体の課題です。統一化による課題と考えたときに、これはあまりない。さっきおっしゃったメリットだけと判断していいのか。","respondent":"三ッ橋国保医療年金課長","answer":"今回、２３区統一の考え方のもとにおいて、独自に対応する区もあります。例えば法定外繰入金は２３区として６年間と考えておりましたけれども、それよりも早く、独自で考えられる区もありますので、各区の考え方を反映できる部分では、メリット、デメリットがあります。","voiceIndex":11,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"法定外繰入金も６年間ということで、それは了解したつもりです。もう一つ、今回のことではなくて、全体の確認なのですけれども、基礎賦課額の賦課割合がある中で、所得割対均等割を今回、６１対３９から６２対３８に変更する基準は何でしたか。","respondent":"三ッ橋国保医療年金課長","answer":"それを全体として、２３区の中で按分いたしまして、先ほど申し上げましたが、品川区はどうしても所得割の高い方がいらっしゃいます。所得割が高いために、各区に按分したときに６２対３８となっております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"若林委員","kind":"質問","question":"所得の低い区は保険料が高くなるという意味になってしまうのでしょうか。それから、保険料率を考えた場合に、法定外繰入が大きくあって、この前の質疑で３区、統一保険料を適用しないというところは、法定外繰入の６年間を採用しないところが統一保険料を採用しないと理解をしていいのか。その辺の法定外繰入と統一保険料の考え方に何か関連があればお聞きしておきたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"法定外繰入金は本当に難しい部分があります。一般財源から投入する部分もあります。なるべく保険料率を上げないように加味しながら解消していきたいと考えていますが、国は解消すると言っている方向性ですので、２３区としては６年間と考えております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"若林委員","kind":"質問・要望","question":"法定外繰入を６年間で解消しないところは、イコール、統一保険料によらない、独自の保険料率を設定すると理解していいのかを確認させていただきたいと思います。そこから足したり、引いたり、割ったり、掛けたりする算定式が一切示されないで、こうなったから１００分の７.３２等という答えが出されて、いろいろ激変緩和もやって、ご理解くださいという説明にずっとなっているわけです。","respondent":"三ッ橋国保医療年金課長","answer":"ここは指標ではなく、６年間がネックになっているわけではないと考えております。資料の部分ですけれども、国保運営協議会、今年、第１回目は勉強会をいたしまして、その部分では、国保、保険料とはというところから、ものすごく時間をかけて、考え方を説明しております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"若林委員","kind":"確認","question":"第１回目の国保運営協議会で詳細な数字をもとに、責任ある立場の方々が勉強をされて、理解をされて、そして承認されたわけですから、数字がなくても、それはそれでよしとするという立場ではあります。保険料が上がっていくことが当然、想定されるということで、これは都の委員会なのですかね。この６年間が終わった後の激変が生じないよう配慮するというのはどういう意味か確認をさせてください。","respondent":"三ッ橋国保医療年金課長","answer":"例えば交付金であったり、また、収納率などの見込みなどが加味されていませんので、それらの差し引きが１１５億円あり、それぞれ賦課総額は２,１４２億円と、２,００６億円になります。こちらをもとに所得割総額、算定用所得総額、所得割率が出されます。","voiceIndex":19,"id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"より丁寧にわかりやすく、委員会また区民に対して情報提供を引き続き行っていただきたいと思います。最後に、参考資料1)の(2)のなお書きについて、東京都が示す各区の収納率を反映した標準保険料率は、基準ではなく、参考値として捉えるとあるのですけれども、各区の収納率を反映したものを都もあえて標準保険料率として、参考値として提示しているのです。参考までに、ここはどんな数字なのか。","respondent":"三ッ橋国保医療年金課長","answer":"今回、都が示しました標準保険料率ですけれども、品川区では７.６０が基礎分です。そして、支援金分が２.２６となっています。均等割額ですが、４万３,２２７円となっております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"にもかかわらず、国保運営協議会に出された資料も示されず、なぜ、こんな少ない資料になってしまったのかをお聞きしたいです。委員会に必要な資料はぜひ出していただきたいと思うのです。肝心なところが入っていないではないかということを１つずつ指摘しながら、国保運営協議会に出された資料は委員会でも出してほしいと言ったわけです。そこのところをまずお聞かせいただきたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"確かに国保運営協議会の資料については、委員、ご指摘のように、ホームページに今現在はきちんとアップしている状況ですけれども、いろいろな理由がございまして、見られないときもあった状況にありますので、きちんと対応してまいります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"資料が少なければ少ないほどわかりにくくなってしまうので、ぜひ、来年度は、少なくとも国保運営協議会の資料はきちんと出すようにしていただきたいと思います。例えば、今回の出された資料の右側の上のところに4)均等割軽減の対象となる世帯の拡大とあり、２７万５,０００円となっていますけれども、これは５,０００円増えたわけですが、どういう世帯が拡大されるのか、これだけだとわからないわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"},{"speaker":"石田（秀）委員長","kind":"質問","question":"鈴木ひろ子委員。質疑の内容に入っていただくのはいいのだけれども、それが作為的にどうとか、資料をもらったときに、委員長、差し戻してくださいという話があって、私も、差し戻せばよかったわけです。だから、そこは踏まえて、内容に入っていただいて質問していただくのはいいのだけれども、あるない、作為的なというところは委員長の責任なのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。だから、前回もそういうことで申し上げましたので、理事者の方にも、ぜひ、今後に向けて改善をしていただきたいということでよろしくお願いしたいと思います。中身に入らせていただきます。ここの中で、先ほども申し上げましたけれども、肝心な国保の加入世帯数と人数、平成２９年度との差がどれくらいなのかが書かれていないので、それをぜひお聞かせいただきたい。","respondent":"三ッ橋国保医療年金課長","answer":"１人当たりの保険料ですが、品川区は１３万２,９２４円です。それから、納付金の総額ですが、先ほど申し上げました、全体の２,００６億円というのは品川区ではなくて２３区全体でございまして。","voiceIndex":27,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２９年度も５,０００円と１万円ずつ、それぞれ上がっていて、去年、聞いたときは９８世帯と８６世帯を対象として拡大する見込みという答弁だったのですけれども、今年も同じくらいの拡大の見込みなのでしょうか。５,０００円ずつ、１万円ずつ、わずかな金額で拡大になっているのですけれども、国としても軽減の世帯を拡大したいという思いでこういう方針をとっているのでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"これらは国の考え方で、国全体として考えておりますので、これからの方向性は今現在では見出されていない状況です。","voiceIndex":30,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"わかりました。そういうことで法定外繰入を段階的に解消するということにしているわけですけれども、平成３０年度については６％分を丸々品川区の法定外繰入で一般財源から繰り入れるという考え方でいいのかを確認させてください。そして、平成３０年度に繰り入れる法定外繰入金は幾らになるのか、平成２９年度の法定外繰入金は幾らだったのか、その差額が幾らなのかも教えていただけたらと思います。","respondent":"三ッ橋国保医療年金課長","answer":"法定外繰入金に関しましては、丸々一般財源となっております。それから、平成３０年度につきましては１１.９億円でございまして、平成２９年度は１３.６億円でございました。","voiceIndex":32,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"今年、その２５％、法定外繰入で出していた分を今年は全額、法定外繰入からなくして、保険料に算定することになるということになると思うのですが確認です。今年、４分の１の２５％分の値上げになると、平成３０年度の法定外繰入で削減される、法定外繰入の高額療養費分はその２５％となるので、私の計算では３億４,２５０万円ぐらいになるのですけれども、そういうことでいいのかを確認させてください。","respondent":"三ッ橋国保医療年金課長","answer":"したがいまして、高額療養費が今回、平成３０年度から幾らとは特に出しておりませんので、計算はできません。","voiceIndex":34,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、課長が言われた法定外繰入を今までしていた審査支払い手数料、出産育児一時金の３分の１、葬祭費、保険事業費等の総額は、今度、それを法定外繰入ではなくて保険料算定にしていくという考え方になると思うのですけれども、その総額は幾らになるのでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"そういう内容を加味していき、廃止した項目を挙げしますと、例えば高額医療費共同事業の拠出金であれば１３.４億円とか具体的に言えるのですけれども、その細かい部分の考え方が変わってしまっているので、そこの部分は算定しておりません。","voiceIndex":36,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今まで出してきた高額療養費はわかったのですけれども、それ以外の法定外繰入で、これから６年間でなくしていくという、今まで出してきた法定外繰入は幾らなのかをはっきりさせておきたいと思ったので、そこのところをお聞かせいただきたいです。東京都で法定外繰入をしなかった場合の１人当たりの保険料試算を出しています。その額も教えていただきたい。","respondent":"三ッ橋国保医療年金課長","answer":"法定外繰入金の部分ですが、今回からの考え方というのは、賦課総額の中の９４％、つまり６％が法定外という意味合いなのです。したがいまして、高額療養費とか出産育児一時金というのは、もう既に保険料に入っているのです。ですので、違った考え方になっていくのです。","voiceIndex":38,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。結局、平成２９年度の１人当たりの保険料は１２万６,２００円くらいですから、法定外繰入をなくした場合の東京都の試算では１５万８,５００円、そこまでに６年間でしていく方針です。その額ということの確認をさせていただきたいと思って、今まで数字を出していただきました。その分は、今回、国からのお金はどれぐらい、どういう形で来ているのかも教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"これは激変緩和後となっております。保険者支援金です。今まで低所得者対策として実施しておりました１,７００億円の部分ですが、今回、保険者支援金につきましては、同等と見ております。その数値については、もう一度、確認させてください。","voiceIndex":40,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回の激変緩和措置も６年間ではないですか。品川区から法定外繰入を６年後にはなくしてしまう、６％の分を丸々なくしてしまう。これは納付額には入っていない額と聞いたのですけれども、これもなくなってしまうと、保険料として納める納付額に入ってくることになるのでしょうか。そうすると、さらに負担が増えてしまうことになるのではないかと心配なのですけれども、その点はいかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"先程ご質問のありました２０１０年の保険料ですが、このときの国保運営協議会の資料によりますと、所得割率が８.０９％、均等割額が３万９,９００円、１人当たりが９万４,４７９円となっております。","voiceIndex":42,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、１,７００億円分の財源は、品川区に今までと同じような形で入ってくるということでいいのですか。これは多分、一般財源に入れていたと思うのですけれども、今回の３億円も一般財源に入るという考え方でいいのか。それからあと、国からの激変緩和措置である７,１００万円、これは品川区の分ということで、品川区に入るのですか。","respondent":"三ッ橋国保医療年金課長","answer":"例えば先ほどの激変緩和の金額、また、どの部分に入ってくるのかですけれども、国からの保険者支援金１,７００億円の部分ですが、例えば調整交付金、定率国庫負担金、また前期高齢者交付金などがございまして、その関係の激変緩和の部分です。","voiceIndex":46,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今までもすさまじい値上げが続いてきたわけです。経年的に見ると、４００万円の４人家族で保険料が４９万２,６６５円、世帯主の所得ではなくて収入が５００万円の家族は保険料が５８万円ですから、本当にこれだけ高いのに、１人当たり３万数千円も上げられるとなると、どうなっていくのだろうと恐ろしい思いがするのです。","respondent":"三ッ橋国保医療年金課長","answer":"今回、国保の制度改革は、本当に長い間、考えられてきて、いよいよ平成３０年度からの改正となります。この背景には、国全体の国民の医療費の増加も大きくかかわっております。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと同時に、国保料の引き下げのところで、子どもの均等割の減免制度をぜひつくっていただきたいと思うのです。都議会でも、昨年３月、子どもの均等割減免制度の創設を国に求める意見書を出しています。おそらく、区長会でも要望していると思います。品川区から、ぜひ、多子世帯への均等割減免制度を改めてつくっていただきたいと要望したいのですけれども、いかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"実際に、具体的にどうやっていくかは、まだ検討にはなっていませんが、子どもの均等割と申し上げますのは、考えなければならない１つのテーマだと考えていますので、今後、検討をしてまいります。","voiceIndex":50,"id":"exchange-022"},{"speaker":"若林委員","kind":"確認","question":"今ので１つ確認。子どもの均等割、いろいろ議論が進んでいくのですけれども、そこの減った保険料を誰が補填するのかという考え方に当然なるのです。その財源も議論をされるということなのですよね。確認です。","respondent":"三ッ橋国保医療年金課長","answer":"ただ負担がそのまま保険料に来てしまった場合も、一方で考えなければならないことだと思いますので、慎重に考えてまいりたいと考えています。","voiceIndex":52,"id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"先ほど国保加入世帯数を言っていただいたのですけれども、加入者の職業構成、構造的な問題と言われていて、自営業とか無職の方、あとは被用者、雇われて働いている方、圧倒的に非正規が多いということなのですが、品川区の割合がわかれば教えていただきたいです。","respondent":"三ッ橋国保医療年金課長","answer":"基本的には、国保は社会保険でない方、中小企業の方等が加入されます。ただ、職業構成で割合というのは、手元にはございません。","voiceIndex":54,"id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"構造的な問題ということで、低所得者、高齢者が多いということなので、品川区ではどんな感じになっているのかを伺いたかったのです。この間の予算のところでも、平成２８年度の目標は９１.６８％だったのですけれども、平成２９年度はどういう目標でやられてきたのか。それから、平成３０年度、新たにやっていくところでは、この目標はどう考えられているのかを教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"目標収納率は非常に難しい問題でありまして、本来ならば目標を１００％と掲げたいのですけれども、なかなか１００％にならない現状があります。２３区の中で１位の状態で、今、９１.６％が現状です。１％上げるのも本当に大変な状況なのです。","voiceIndex":56,"id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１％上げるのも大変と。平成２８年度の前は、たしか８９.何％という目標だったと思うのですけれども、２％上げているということで、大変だという中でも、それだけ収納率を上げてきた。この間、東京都から入ってくる成績別交付金があります。この間も１億６,０００万円ほど入ってきたと思うのですけれども、これは今後、新制度になったもとでどうなっていくのか伺いたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"東京都からの収納率向上にかかわる取組み成績別交付金は、今後も特になくなることはございません。平成３０年度につきましては、収納率の部分で、納付金の品川区の部分から差し引かれますので、今後、収納に関しては、また取り組んでまいります。","voiceIndex":58,"id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"保険料を支払うというのは保険制度を支えていく上でも大事なのですけれども、今、問題になっているのは高すぎて払えない状況です。それがさらに引き上がる。そして、差し押さえ件数もすごく多いです。この間も紹介しましたけれども、渋谷区は１０件しかやっていないですが、品川区の滞納者数は渋谷区より少ないのです。ですので、差し押さえの考え方を伺いたいのです。","respondent":"三ッ橋国保医療年金課長","answer":"例えば分納計画を組んだり、窓口で丁寧に説明して、いろいろなご事情を聞いた上で、差し押さえに至る経緯もありますが、決して被保険者の皆様の状況を加味しないということではなく、一人ひとりの状況をきちんと伺いながら丁寧に説明して。","voiceIndex":60,"id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"一人ひとりの状況を把握する、確かに収納は大切です。やっていただきたいことです。先ほど課長もおっしゃったように、一人ひとりの状況をつかんでどうやったらいいか考えていけば、収納できる状況も生まれてくるのに、とにかく払わないと差し押さえしますというおどしまがい、実際にこういったこともあるわけです。それがさらに増えていくのではないかと思うので、その考え方を伺いたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"低所得者対策としても、１,７００億円、国からも、全体として低所得者対策は実施している状況です。ただ、確かに地方自治体として、区として一人ひとりの対応をしていく中で、さまざまな状況があるのは実情として把握しております。","voiceIndex":62,"id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"丁寧な、ぬくもりある対応をすれば収納につながるということは本当にあるので、ぜひ、そこをお願いしたい。それと、前々から私たち共産党はお願いしているのですけれども、ブースです。低所得者対策をされているとおっしゃるのですけれども、だったら値上げしないでという感じなのです。ですので、ぜひ、プライバシーを守れるブースを国保でもつくっていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"国保制度の安定化が第一条件に入っていると思います。いろいろな課題はまだまだあると思いますけれども、自民党として賛成します。ただ、質疑の中にもありましたが、医療費の削減とか、この制度を区民の方にどのように伝えていくか。我々、質疑をしていても非常にわかりにくいところなので、何かコンパクトに、皆様に理解してもらって保険料を納めてもらうというところをぜひ考えていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"質疑の中での意見も含めて申し上げさせていただきましたので、また今後の国保の保険料をいろいろ考える際の参考にさせていただきたいと思います。今後、６年間が１つ大きな焦点になってくるということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"条例に対しては反対です。今でも高すぎる保険料が払えないということで、保険証を持たずに、病院にもかかれず手遅れになるという問題も起こっています。そういう中で、法定外繰入は、今までの分は継続をしていく。そして、高額療養費分ももとに戻して、引き下げこそ必要だと私は求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-032"},{"speaker":"大倉委員","kind":"質問","question":"賛成です。いろいろ議論もされて、お話も伺いまして、均等割等の軽減といったことも今後、議論になっていく。これから品川区もいろいろ考えていただいて、取り組んでいただくのと、先ほどもおっしゃっていましたが、制度が変わったというところを区民の皆様にしっかり周知していただいて、進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3502#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":24757,"voices":75}},{"id":"h30-20180319-3","meetingId":"h30-c-budget","date":"2018年3月19日","dateIso":"2018-03-19","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時１３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を109件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"交渉力について伺います。よりニーズに合った、より時代に合った取り組みを求めて質問します。次です。１６３号線、ＪＲ東海道新幹線等高架下工事、西品川一丁目地区市街地再開発の竣工に向けて、歩道トンネル完成のおくれ、区、組合、ＪＲ三者協定、進行管理とあわせ交渉力が求められます。会派委員からの要望で、広町地区の再開発、ＪＲ東日本への協議、区の強いリーダーシップを求めました。質問します。","respondent":"中山企画部長","answer":"この間も、例えばしながわ中央公園の設置に至る民間からの用地取得、あるいは、国有地の取得による福祉施設の設置等を進めてまいったわけでありますけれども、民間と競合するような場合に、価格の競争、あるいはスピードというふうな関係で。","voiceIndex":2,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"先ほどの目黒川のデッキですとか、高架下の１６３号線の歩道ですとか、区が組合に対して指導したり進行管理する部分かもしれませんが、やはり求められるのは交渉力だと思いますので、引き続きのご努力をお願いしたいと思います。私たち議員も結果が求められておりまして、一生懸命やるだけではだめで、やはり結果が求められるので、本当に大変な部分だと思いますが、ぜひご努力をお願いしたいと思います。","respondent":"榎本総務部長","answer":"部署単位の取り組みとしましては、職場企画研修というものを通じまして、所管ごと必要な研修をできるように実施をしております。","voiceIndex":4,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"私は、今から２５年ほど前に、アイスホッケー日本代表の監督を務められました田名部匡省さんの話を聞く機会がありまして、ずっと忘れられない印象に残る言葉があります。このことはチームに限らず組織全てに共通する」というものでした。先ほど、横の連携というところで組織の部分だと思うのですが、再度お伺いします。成功のもとであったり、人生の糧であったり、その点につきましてもお聞かせください。","respondent":"榎本総務部長","answer":"やはりうまくいかない部分、進め方がうまくいかない部分については、再度そういうチームが集まって行っていったりとかということで、失敗の経験ということなのですけれども、大きな失敗となる前の小さな失敗の段階で、軌道修正なり。","voiceIndex":6,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"プロジェクトチームによって組織力で取り組むということを教えていただきました。失敗の部分につきましても、人間ですからいろいろな失敗、経験が必要かと思います。次の質問に移ります。２００８年４月にふるさと納税制度が誕生し１０年になります。オール東京としてです。制度が続く以上、流出抑制の対策を講じ、あわせて区外への品川の魅力発信に向け、最大限努めていくという点を確認させてください。","respondent":"中山企画部長","answer":"したがって、ご質問にもありましたように、東京都や関係区市町村との連携ということも含めて、今後、ふるさと納税についての、ある意味での見直しについてはしっかりと区として主張していきたいと考えておりますけれども、一方では。","voiceIndex":8,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"流出抑制につきましては、本当に毎年数億円流出されている現状に対し、しっかりと何か対策をしていただきたいと思います。今のご答弁でも大分見直しが、若干ではありますが、一歩ずつ進んでいる感を受けましたので、引き続きのご努力をお願いしたいと思います。名物、人、物。あわせまして、観光大使ももっと登用するべきです。観光大使は多くてもいいと思うのですが、その点についてはいかがでしょうか。","respondent":"中山企画部長","answer":"広い意味での品川の魅力という中に「人」というものがあるということを申し上げましたけれども、そのようないわゆる有名な方、これは区のご出身だけではなくて、例示にもありましたような、何らかの関係で品川区に縁のある方、品川区の魅力を発信したり。","voiceIndex":10,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"本当に名物、人、物、それぞれ大事かと思いますが、人の登用もぜひ前に進めていただきたいと思います。次の質問に行きます。２月２日、東京都の小池知事は、２３区の大学定員増を抑制する国の動きに対し、理不尽かつ不合理な規制として緊急声明を出しました。この点につきましては、ふるさと納税同様、東京の富裕論への狙い撃ち、ジャブ、ボディー、１つ１つ手を打たないと、きいてしまうと思います。","respondent":"榎本総務部長、堀越地域振興部長","answer":"具体的には、平成２９年から４つの大学のまず学生の活動ということで、学生が集まりまして、どのようなことができるか、どのようなことをしたらいいのかというディスカッションを開始しております。産学連携につきましては、区内中小企業、大学などの教育機関や研究機関と連携いたしまして、新技術の研究開発や新製品の開発など、協働で取り組む事業への支援を通じ、技術者の人材の育成、それから新産業。","voiceIndex":12,"id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"次の質問に移ります。工期は、平成２９年度から平成３４年度末の６カ年ほど。下流部は引き続き子供の森公園横からシールド工法で整備し平成３６年度で完了見込ですが、とても重要な事業です。質問します。１、都からの受託事業の今後について。４、子どもの目線。税外収入の観点からも、区内に１つもないバッティングセンターの整備について、前向きにお考えいただけないものでしょうか。お聞かせください。","respondent":"松代防災まちづくり部長","answer":"例えば、第二戸越幹線で使用する西品川公園では、地元説明会を５回実施しまして、公園の約半分を工事ヤードとして使用する一方、トイレや防災倉庫など必要な機能は移設しまして、残り半分は従来どおり公園として利用できるようにしております。","voiceIndex":15,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"浸水対策はとても必要で重要な工事ですので、本当に充実を図っていただきたいと思います。次の質問に移ります。質問します。３、これまでのゆうぽうとは２,０００人規模、区政に関連して、北島三郎さんの公演などをはじめプロの登用や、きゅりあん大ホール１,２００人のメリットを同じように考えられないのか、未来志向でさらなるチャレンジ、ベターよりベストを求め質問いたします。","respondent":"藤田都市環境部長","answer":"協議会準備会との意見交換についてですけれども、品川区文化芸術振興協議会準備会ですが、「文化芸術を通じた魅力のあるまち」、こちらを実現するための、平成３０年５月の協議会設立に向けた準備会だということを認識しています。","voiceIndex":17,"id":"exchange-008"},{"speaker":"本多委員","kind":"質問","question":"ゆうぽうと、郵政は、最初はスペースを貸さないというところから、交渉力によって、この４００人から５００人の規模のホール建設まで実現されたことは本当に交渉力の成果だと思います。平昌オリンピック・パラリンピックの壮行会では、大田区総合体育館が４,０００人規模でやられたということで、すばらしいなと感じました。そういうことが品川区でもできたらと、素朴に感じて質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"品川区議会自民党・子ども未来を代表して、本多委員に引き継ぎ、総括質疑を行います。初めに、品川区のＩＣＴ化推進についてお伺いいたします。そこで、質問いたします。区内業務の中でも比較的ＩＣＴ化しやすい部署、例えばこれは款別質疑でも質問させていただきましたけれども、介護現場等、費用対効果等を勘案しながら進めていくべきと考えますが、いかがでしょうか。ご見解をお聞かせください。","respondent":"中山企画部長","answer":"３点目の介護現場等で費用対効果を踏まえながらの推進というご提案でありますけれども、例えば、ご質問にもありましたタブレットを活用したような動きというものを進める中で、これは研究課題になりますけれども、介護の現場にそういうものを持って、訪問先の情報であるとか。","voiceIndex":21,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"意見","question":"今の答弁を聞いておりまして思いましたのは、単独のシステムは、おっしゃるとおり、今あるのです。なので、長期基本計画ということであるけれども、やっぱりそういうものを今度はＩＣＴ化を活用してそれぞれのシステムに横串を刺していくといったらいいのか、そういうことを検討してみたらいかがかと思うのですが、改めて答弁をお願いいたします。","respondent":"中山企画部長","answer":"ご提案のように、それぞれの仕組みが有機的に連携して使いやすくなる、このような課題の認識の中でしっかりと取り組みを進めてまいりたいと考えております。","voiceIndex":23,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"意見","question":"さて、今、政府は働き方改革を進めているわけであります。先ほどお示しした本庁舎内の大規模なシステム改修は、積極的なクラウドの活用によって、例えば区の職員等が、将来、セキュア端末を外に持ち出して、品川区の職員のワークスタイルを変更するためのシステム改修であると私は思うわけであります。改めてこれらのことに対する品川区の見解をお聞かせください。お願いいたします。","respondent":"榎本総務部長","answer":"したがいまして、国が進めるマイナンバーの利用促進の状況、それから、ＩＣＴ機器のコスト面の課題、さらには、高齢者等のデジタルデバイドへの対応などを把握しつつ、総合的に進めていく必要があるというふうに考えているところです。","voiceIndex":25,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"提案","question":"平成７年の阪神・淡路大震災後、私ども自民党で神戸市にお伺いさせていただきました。その反省をもとに、品川区でも、都市型災害対策が見直されましたが、平成２３年の東日本大震災でも、想定外の被害が発生し、さらなる対策が求められたわけであります。さて、災害時における品川区と区内各種団体との協定は、自動販売機の無償提供に関する協定等、確認できただけで１９団体であります。","respondent":"曽田災害対策担当部長","answer":"これら区の行う応急対策において、委員が示されました災害時協定締結団体と適切に連携するためには、災害の全般状況や個々の災害の状況、現場のニーズ、あるいは協定締結団体との協定に基づく支援内容、そして現実に派遣可能な参加規模、これらを踏まえまして。","voiceIndex":27,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"例えば行政単位、警察、消防、自衛隊のところについては、はっきりと連携がとれると思うのですけれども、各種団体はどうしても相手が民間でありますから、そこのところの連携が十分にとれていかないと、せっかく協定を結んだにもかかわらず、万が一のときに生かされないと非常にもったいないと言ったらいいのでしょうか、大変なことになると思われますので。","respondent":"曽田災害対策担当部長","answer":"来年度改訂を予定している「わが家の防災ハンドブック」にご指摘の避難所等における防犯対策を記載することについては、非常に大切なことだと考えておりますので、都や他自治体での事例も踏まえて検討していきたいと考えております。","voiceIndex":29,"id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"品川区の家庭支援等についてお伺いいたします。品川区が個々に収集している乳幼児の情報をもとに、児童委員、民生委員、町会等とさらなる連携強化を図り、区の支援が必要と推測される家庭等に積極的な支援策を展開すべきと考えますが、いかがでしょうか。品川区として児童虐待根絶宣言等を行う等、具体的な行動を行うべきと考えますが、いかがでしょうか。お考えをお聞かせください。","respondent":"福島子ども未来部長","answer":"こうした取り組みを重層的に講じるなど、児童虐待防止の啓発を進め、また家庭への支援を進めていきたいと考えております。宣言につきましては、今後、児童相談所移管が想定されておりますので、それを具体的に進めていく中で検討してまいりたいというふうに考えております。","voiceIndex":31,"id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問・要望","question":"現場はそういう制度をおつくりになって、さまざまな努力を傾注していることはよく知っておるわけであります。ですけれども、こういう事例が起きる。ですから、今の部長の答弁はまさにそのとおりであるし、それは展開していただきたいし、さらに前進していただきたいと思うのだけれども、こういう事件が起こってしまう。だから、そこのところに行政の見落としがあるのではないか。","respondent":"福島子ども未来部長","answer":"もちろん事件が起こらないようにということで万全な体制を組んでいるところです。先ほども申しましたように、地域での取り組みが一番大切だと考えておりますので、さまざまな機関の者が集まりまして、地域での見える関係、直接的な対応を図っていきたいと思ってあります。","voiceIndex":33,"id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひよろしくお願いいたします。改めて今回の予算特別委員会で我が会派の議員が質問、指摘を行った内容は、全て区民の直接、間接的な声を代弁しております。それを尊重して予算執行に当たってくださるよう改めてお願いいたします。以上で、自民党・子ども未来の総括質疑を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"こうした社会を目指す中で、中高年のひきこもりの長期化などにより、８０代の親と５０代の子どもが高齢化し、支援につながらないまま孤立する８０５０問題や、これまで繰り返しその支援策を求めてきた介護と育児に同時に直面するダブルケアなどの課題の複合化や、制度の狭間の問題なども浮き彫りとなっています。そこで、地域共生社会とはどのような姿が理想とされているのでしょうか。","respondent":"永尾福祉部長","answer":"第３期品川区地域福祉計画策定に当たりましては、地域の方々が主体的に地域の生活課題を把握し、解決につなげる地域力の強化を後押しするということが大きな課題になっておりまして、１３地区の地区懇談会をそれぞれ２回、関係機関、関係団体。","voiceIndex":37,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"そこで、改めて地域福祉の推進をはじめ、品川区にとって社会福祉協議会はどのような位置づけにあるのかお知らせください。福祉人材や地域福祉の担い手の確保、育成等を図るには、さらなる社会福祉協議会への支援、そして現場の司令塔である支え愛・ほっとステーションへ障害部門などにも対応できる職員の人員配置などの支援が求められると考えますが、ご見解をお知らせください。","respondent":"永尾福祉部長","answer":"来年度、それを取り組んでみまして、様子を見まして、また今後のことを検討していきたいというふうに考えております。","voiceIndex":39,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"過日、高齢者施策の中長期的な指針となる新たな高齢社会対策大綱が決定されました。高齢社会対策大綱には、２０２１年に実施される中学校学習指導要領社会科に、少子高齢社会における社会保障の充実・安定化の意義を理解することが明記されることを踏まえ、その周知を学校等で行うとあり、学校教育の場でも、その周知が求められていますが、それぞれどのように取り組まれるのかお知らせください。","respondent":"本城教育次長","answer":"委員ご指摘のように、今回の学習指導要領の改訂によりまして、社会保障の充実、安定化について学ぶことが、学習指導要領上、明記されたことから、今後はいずれの教科書におきましても、その記載がなされることが見込まれますが、品川区におきましては。","voiceIndex":41,"id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"２０１６年の決算特別委員会で、健康寿命を延ばして健康と要介護の間の状態であるフレイル、高齢者の虚弱に対する取り組みとして、健康づくりへの動機づけが今後ますます重要と指摘し、改めて健康マイレージ、ヘルスケアポイントの導入などを求めていたことから、来年度、健康ポイント制度がスタートすることを歓迎します。","respondent":"永尾福祉部長","answer":"区では、リハビリ専門チームを設置しておりまして、医師や理学療法士、また区の担当者をメンバーとしておりますけれども、毎年１回から２回、介護予防事業の検証や介護予防関係者のスタッフの研修等を実施しております。","voiceIndex":45,"id":"exchange-021"},{"speaker":"つる委員","kind":"質問・要望","question":"地域共生社会の理念に資するものと本会議でご答弁いただいた旧小山台住宅跡地を活用した地域共生社会のモデルケースとなる拠点づくりを全国に先駆けて着手し、冒頭に引用しました高齢者問題世界会議を東京都や近隣自治体と協力して、品川区にも会場を誘致することを国に働きかけ、品川区の取り組みが世界に発信される機会としてはいかがでしょうか。","respondent":"永尾福祉部長","answer":"次の小山台住宅跡地の関係につきましては、委員会のほうでもご説明申し上げておりますけれども、地域共生社会の理念に資するものというふうなことも今検討しておりまして、地域のにぎわいや防災機能の強化とともに、子育て支援や福祉、高齢も含めた複合施設を検討しています。","voiceIndex":47,"id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ会議については積極的に検討をいただきたいと思います。次に、ＡＥＤによる救命体制の拡充についてお尋ねいたします。今年度、住宅街にあり、比較的深夜帯まで営業している区内公衆浴場全てにＡＥＤが設置されました。そこで、まず、改めて自治体が設置等における根拠としている法令等は何か。現在の区内の設置台数についてお知らせください。","respondent":"西田健康推進部長","answer":"この中に平成２５年９月９日、一般財団法人日本救急医療財団がまとめたＡＥＤの適正配置に関するガイドラインがございまして、これを参考にし、ＡＥＤの効果的かつ効率的な設置拡大を進めるよう示されているものです。","voiceIndex":49,"id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"厚生労働省から２０１３年に出された今ご答弁ありましたＡＥＤの適正配置に関するガイドラインが本年中に改訂される予定と伺っていますが、その中でも示されているように、さらなる効果的かつ戦略的な配備と管理が求められます。そこで改めて、３００ｍごとの設置を目指した住宅街への設置および２４時間誰もが利用できる環境の整備を求めます。それぞれご所見をお聞かせください。","respondent":"西田健康推進部長","answer":"ＡＥＤの住宅街への設置、２４時間対応というお尋ねです。現在、品川区内において、駅前や繁華街などでは、おおむね３００ｍ間隔で設置されておりますが、住宅街については、公共施設や事務所などが少ないため、ＡＥＤの設置が進んでいない現状があります。","voiceIndex":51,"id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"そこで、区内の少年野球やサッカーなどのスポーツ団体の指導者に行っているスポーツ指導者養成事業にＡＥＤの研修を盛り込んではいかがでしょうか。ＡＥＤの設置されていない場所などで練習等を実施する際に、希望に応じてＡＥＤを貸与できる仕組みを検討されてはいかがでしょうか。ご所見をお聞かせください。","respondent":"安藤文化スポーツ振興部長","answer":"少年サッカーや野球など各種少年スポーツ団体がホームグラウンドとして使用する場所には、既にＡＥＤが設置されてありますが、ＡＥＤを設置するだけでは、委員ご指摘の突然死や心停止となった場合に救命することはできず、重要なことは。","voiceIndex":53,"id":"exchange-025"},{"speaker":"つる委員","kind":"意見","question":"学校でも毎年１００名程度の児童・生徒の心肺停止が発生し、ＡＥＤが活用されずに亡くなられた小学校６年生の悲しい事例もあります。そこで、区内の幼・小・中・義務教育学校における設置場所と設置台数について、同ガイドラインにあるように、５分以内に心停止発生場所で使用できる配置となっているのか、また、教職員の連携体制や対応訓練についてお知らせください。","respondent":"本城教育次長","answer":"ＡＥＤの増配置等についてですが、過去の使用実績や現在も規模の大きな学校におきましては、既に複数台数設置していることから、今のところは配置数を増やす具体的な計画を持っているものではございませんが、教員による訓練等を通しまして。","voiceIndex":55,"id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"昨年３月に公示された国の中学校学習指導要領保健体育では、日本ＡＥＤ財団の要望もあり、授業で心肺蘇生を学ぶことが初めて明記され、付属の解説には、胸骨圧迫、ＡＥＤ使用などの心肺蘇生法、包帯法や止血法として直接圧迫などを取り上げ、実習を通して応急手当てができるようにすると明記されています。突然死をゼロにするためには、第一発見者となる可能性の高い児童・生徒への救命教育は重要です。","respondent":"本城教育次長","answer":"心肺蘇生トレーニングを救命教育に取り入れることにつきましては、現在、教員研修用としまして、教育委員会として各学校に練習用トレーナーを貸し出しており、児童・生徒用の購入につきましては、効果や導入費用等もよく検討しまして。","voiceIndex":57,"id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"ＡＥＤについては、今ご答弁いただいたこととあわせまして、体系的な学習が大切であるという指摘もされておりますので、ぜひ積極的に検討していただきたいと思います。今後、今質問させていただきました質問の内容が、それぞれ前向きに検討されることを期待いたしまして、以上で私の質問を終了いたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-028"},{"speaker":"たけうち副委員長","kind":"提案","question":"初めに、防災対策について２点伺います。品川区でも、近い将来、必ず起きると言われております首都直下地震によりまして、８００名近い多くの方が犠牲になるとの被害想定が出されている中で、さらなる防災対策の強化が求められております。そこで質問の１点目は、避難所の強化について伺います。改めて更新に合わせての公開、情報提供を要望しますが、それぞれご所見を伺います。","respondent":"曽田災害対策担当部長","answer":"今回、避難所マニュアルの更新支援に至った経緯であります。区内全５２の避難所のうち４７避難所で避難所運営マニュアルを作成していただいておりますが、整備状況に差があり、全般としては不十分な状況にあると認識しています。","voiceIndex":61,"id":"exchange-029"},{"speaker":"たけうち副委員長","kind":"提案","question":"区議会公明党として、これまで何度も要望してきた女性の目線、要配慮者の視点、また、ペットの課題等についてもしっかりとマニュアルに盛り込んでいくことが確認されました。ここで、事前に委員長に了承いただいております資料を提示させていただきたいと思います。款別審査でも要望しましたが、都に対して増刷を要望していただきたいと思いますが、区内での配布の拡大についてお考えをお聞かせください。","respondent":"曽田災害対策担当部長","answer":"「東京くらし防災」の現在の配布状況であります。現在、区内における配布については、区有施設８３カ所、都施設や民間事業所９７カ所に配布場所が設定されており、そのうち区施設では７,３００冊の配布を予定しておりますが、実際に配布した部数は把握できておりません。","voiceIndex":63,"id":"exchange-030"},{"speaker":"たけうち副委員長","kind":"提案","question":"その際には、款別でも提案しましたが、視覚障害者に配慮した音声コード、こちらもぜひ導入するよう改めて要望いたしますが、それぞれご所見を伺います。私は平成１９年第３回定例会で、体育館の冷暖房の設置について提案して以来、会派としても要望してきましたが、こうした都の動向を注視しながら、空調設備、冷暖房機の設置に向けて検討するよう、改めて要望しますが、ご所見を伺います。","respondent":"曽田災害対策担当部長、本城教育次長","answer":"改訂します「わが家の防災ハンドブック」への「東京くらし防災」の反映についてですが、「東京くらし防災」だけではなく、「東京防災」や他自治体のハンドブックなども参考に。ただ、その一方におきまして、避難所としての屋内運動場の快適性等を高めることや、あるいは、特に最近では、学校の授業、部活動におきましても、真夏の体育館利用時に熱中症の危険性が高まっていることもあり。","voiceIndex":67,"id":"exchange-031"},{"speaker":"たけうち副委員長","kind":"質問","question":"ぜひ音声コードについてはよろしくお願いします。体育館については、小・中学校とは違いますが、戸越体育館で、来年度、後づけでつけられるということも伺っておりますので、その動向も見ながら、費用対効果の考え方もありますけれども、必要だと思いますので、ぜひよろしくお願いいたします。次に、地域危険度の改善について伺います。","respondent":"藤田都市環境部長","answer":"地震災害に対する認識を深め、地域の方々の防災意識を向上させることや、震災対策におけるさまざまな事業を実施する地域を選択する際に活用することが目的とされてあります。","voiceIndex":70,"id":"exchange-032"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"地域の防災に対するこうした活動が調査に加味される項目ではないということは承知しておりますが、どうしてこのような形で西大井三丁目、また大井地区がこうした結果になったのか、改めて教えていただきたいのと、また、今後、出石町会と隣接地域への丁寧な説明が必要だと思いますが、いかがでしょうか。今回の結果を踏まえて、今後、大井地区でのどのような対策が必要なのか、それぞれご所見を伺います。","respondent":"藤田都市環境部長","answer":"こうした地域の防災まちづくりを区として支援しています。今回の地域危険度調査の内容につきましては、こうしたまちづくり検討会の中でもお知らせをいたしまして、具体的な事業手法については、地域の皆さんと話し合っていく考えです。","voiceIndex":72,"id":"exchange-033"},{"speaker":"たけうち副委員長","kind":"提案","question":"ぜひとも丁寧な説明と、また早急な対応策をご検討いただきたいと思います。ここで提案なのですけれども、今回の西大井三丁目、災害時活動困難度が品川で唯一ランク５と最大となっておりまして、今ご答弁あったとおり、防災広場等の整備が必要になってくると思います。そして防災広場等の整備を積極的に図ってはいかがでしょうか。ご所見を伺います。","respondent":"藤田都市環境部長、中山企画部長","answer":"今後、地域における事業の導入を見据えまして、具体的な道路拡幅あるいは防災広場の設置に向けた計画策定を区として引き続き支援をしていきたいと考えています。今後の活用につきましては、現段階では未定です。この土地の活用については、今後も国の動向を注視しながら情報収集を進めてまいりたいと考えています。","voiceIndex":74,"id":"exchange-034"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"企画部長のご地元の地域ですので、ぜひお願いしたいと思いますが、１,６００m2といいますと、非常に広い土地です。西大井三丁目の出石町会は、西大井に６町会ある中で唯一会館のない町会です。活動に際してさまざまなご苦労があろうかと思いますので、こうした公邸、状況等を踏まえながら、可能ならば会館に近い形での活用も視野にご検討いただきたいと思いますが、ご見解を伺います。","respondent":"中山企画部長","answer":"ただし、国有地につきましては、区が優先的に取得する場合に、活用方法について、例えば福祉だったり、防災であったり、条件が付される場合があります。この辺の国の動向もよく注視しながら、情報収集をしっかり行っていきたいと考えています。","voiceIndex":77,"id":"exchange-035"},{"speaker":"たけうち副委員長","kind":"確認","question":"ぜひ情報の収集をよろしくお願いいたします。次に、防犯対策について２点伺います。初めに、特殊詐欺対策の強化について伺います。款別審査で確認しましたが、現在、特殊詐欺対策として、希望者に無料貸与で自動通話録音機を配布していると聞いておりますが、この効果と、また、新年度の予算の台数について伺います。","respondent":"堀越地域振興部長","answer":"自動通話録音機の効果ですけれども、これで被害を完全に防げたというのは、なかなか立証するのは難しいところもありますけれども、区内を含めまして都内におきましても、これまで機器を設置した世帯からの被害報告は出ておりませんので。","voiceIndex":79,"id":"exchange-036"},{"speaker":"たけうち副委員長","kind":"提案","question":"そしてさらに、警視庁では、先月の２月５日以降の１日ごとの区別の被害件数と、また全体の１日の被害総額をツイッターで配信しております。品川区では、２月１５件、また３月では１５日までで１１件と、昨年を上回るペースで被害が確認されております。交通安全協議会には議会から参加しておりますが、この生活安全協議会への議会からの参加も提案いたしますが、それぞれご所見を伺います。","respondent":"堀越地域振興部長","answer":"生活安全協議会への議会からのご参加についてですが、こちらにつきましては、町会、防犯協会等の代表の皆様からの構成となっています。各委員はじめさまざまご意見を伺いながら、こちらについては検討させていただきたいと考えているところです。","voiceIndex":81,"id":"exchange-037"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"ぜひともよろしくお願いします。卑劣な詐欺でなくなってしまうことのないように、警察だけではなく、しっかりと区も総力を挙げて取り組んでいただきたいと思いますので、よろしくお願いいたします。２点目は、子どもたちの安全対策について伺います。来年度から「児童見守りシステム」に名称が変わると聞いておりますが、理由について教えてください。","respondent":"堀越地域振興部長","answer":"本システムは全国でも先進的な取り組みです。それから、児童に対する犯罪の被害の防止、この抑止効果として大きな効果を発揮しているというふうに思ってございまして、そしてこの協力者の方々、児童の保護者を中心とした協力者の存在が大変重要であるというふうに認識しています。","voiceIndex":83,"id":"exchange-038"},{"speaker":"たけうち副委員長","kind":"提案","question":"先日、会派でシステムの稼働状況を視察させていただきました。以前に提案し数年実施された協力者対象の講習会も、最近では実施されていないようですが、区として協力者に対する意識の向上についてどのように考えているのか伺います。あわせて、年間十数件起きております協力者の緊急通報ですが、こうした通報があった場合には、メールで配信するなどの情報共有を図るよう提案いたしますが、ご所見を伺います。","respondent":"堀越地域振興部長","answer":"そのため、ご紹介いただいた協力者通信を年に１回もしくは２回、協力者の方へ送付しまして、まもるっちの取り組みの状況について周知しているほか、平成２７年度と平成２８年度は、一斉送信テスト、一斉送信による緊急連絡テストも実施しています。","voiceIndex":85,"id":"exchange-039"},{"speaker":"たけうち副委員長","kind":"質問","question":"ぜひよろしくお願いします。そこで、例えば、支え愛・ほっとステーション、また認知症の見守りボランティア等、新たなボランティアとして活動いただけるような環境づくりと、今後の周知啓発等の仕組みづくりについて、ご所見を伺いたいと思います。","respondent":"堀越地域振興部長","answer":"ただ、いずれにしましても、防犯意識を地域全体で高めていくという観点で、高齢者福祉、福祉関係の部署とも連携をして、こういった本システム以外のボランティアの方の活用について、例えば先ほどの答弁の繰り返しになりますけれども。","voiceIndex":87,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"修復型のまちづくりへの転換を求めて質問します。これが本当にまちづくりといえるのでしょうか。１つ目は、巨大道路２９号線についてです。今のまま住み続けることを求めて、昨年、住民は認可取り消しを求める裁判に立ち上がりました。これまでまちを築き上げてきた住民を立ち退かせるのは、まち壊しではないのか伺います。改めて、２９号線によって立ち退きを迫られる建物棟数、世帯数をお聞きします。","respondent":"藤田都市環境部長","answer":"これを予防するためにまちをつくることは極めて重要です。区といたしましては、東京都と連携し、災害に強いまちづくりを進めてまいる考えです。","voiceIndex":92,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"燃え広がらないまちのために、もといた人を根こそぎ追い出すのが、まち壊しなのでしょうか。２９号線によって壊されるものはほかにもあります。商店街や町会も２９号線によって分断されます。まちをめちゃくちゃにするのが２９号線です。２９号線は、住民の絆や文化を壊すものではないか伺います。区が魅力の１つとする商店街が壊されるのがまちづくりといえるのでしょうか。伺います。","respondent":"藤田都市環境部長","answer":"都の道路整備にあわせまして、区として、例えば戸越公園駅周辺の商店街の皆さんとは、まちのにぎわいの継続とさらなる発展のために、こういった方々を支援しています。お互いに知恵を絞り合い、まちづくりの検討を進めているところです。","voiceIndex":94,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"２９号線は、区長が進めてほしいと東京都に進言し、防災を口実に進められたものです。しかし、この道路は延焼遮断帯の考え方自体が防災にならないのではないでしょうか。そんなもののために住民の生活を壊すのはやめるべきです。防災を口実にして住民を追い出すことがまちづくりなのですか。伺います。無理やり不燃化領域率を上げるため、２９号線で住民を立ち退かせるものではないのか伺います。","respondent":"藤田都市環境部長","answer":"木密地域の皆様方が住み続けられるように、都と区が連携して進めているのが木密地域不燃化１０年プロジェクトです。","voiceIndex":96,"id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"防災を口実にして守るべき住民を追い出しているのが実態です。効果をなさない、住民を追い出し生活を壊し道路をつくるのは、まちづくりではありません。まち壊しの２９号線に６００億円の税金が投入されようとしています。住民を立ち退かせ、まちを壊す２９号線の撤回を求めます。防災ならば６００億円の税金を耐震化や感震ブレーカー設置など、抜本的に進めるために使うことを求めますが、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"木密地域を燃えない、燃え広がらないまちにするために、個々の建物を燃えないものにする、あるいは初期消火などに対する防災訓練の実施、また、スタンドパイプや街頭消火器の配置、燃え広がらないために延焼遮断帯を形成する特定整備路線の整備など。","voiceIndex":98,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"防災のまちづくりを進めると言いますが、その耐震化や感震ブレーカーの設置をさらに抜本的に進めるよう、２９号線の税金投入を変えていただきたいということです。住民を立ち退かせ、まちを壊す２９号線は撤回すべきです。しかし、本当に防災になるのでしょうか。超高層ビルは防災の課題を増やすものではないか伺います。防災などを口実に住民を追い出す再開発のどこがまちづくりなのか伺います。","respondent":"藤田都市環境部長","answer":"品川区の中、さまざまな特徴を持っているまちはありますが、商店街と隣接するような場所では、地域の商店街とも連携をし、それぞれ特徴を持ちながらまちづくりを進めているものです。","voiceIndex":100,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"款別審査で、１９番地区では超高層でなければならないのかと質問し、区は超高層でなくても地域課題の解決方法はある。建て替えは可能と答弁。なぜこのような手続になったのか伺います。手続の改善を求めます。例えば、北品川では、再開発につなげるための北品川駅前広場と道路計画に対して、再開発でない別の道が求められています。超高層再開発でどこでも同じような顔のまちにしてよいのか伺います。","respondent":"藤田都市環境部長","answer":"当初、説明の中で、縦覧だけではなく意見書についても誤って２週間としておりました。これについてはすぐ気がつきまして訂正をし、地区内の方には３週間行いますということで、改めてお知らせをし、執行したものです。","voiceIndex":102,"id":"exchange-046"},{"speaker":"のだて委員","kind":"提案","question":"しっかりとそれがわかるように説明をしていただき、住民の意見を汲むのであれば、その意見をしっかりと反映させて、件数としても出していくべきだと思います。道路と超高層のまちづくりからの転換を求めます。スクラップ・アンド・ビルドの再開発ではなく、よいところは残しながら、問題のあるところを直していく修復型のまちづくりを提案しますが、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"これにより開発の手法もさまざまあるというふうに考えてあります。いずれにいたしましても、品川区のまちづくりマスタープランに掲げます地域の課題の解決に向け、将来のまちの実現を進めていきたいというふうに考えてあります。","voiceIndex":104,"id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域の課題の解決方法はさまざまあるということですから、超高層開発からまちづくりの転換を求めたいと思います。区は、再開発などで新しい人を呼び込むことばかり考えています。昨年１１月に行われた区長のタウンミーティングでは、区民から障害者福祉の改善を求める発言がありました。施設が少ないこと、また必要性を求めているにもかかわらず、なぜ区がみずから施設をつくろうとしないのか伺います。","respondent":"永尾福祉部長","answer":"障害者施設の増設についてお答えいたします。荏原地区の施設の必要性につきましては、区としても認識しています。条件に適合した土地や近隣の方々のご理解などの課題を踏まえ、検討しています。施設については、区立、社会福祉法人立、民間事業所立とさまざまな形態があります。","voiceIndex":106,"id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区には、障害者福祉を２３区最低レベルにしてきた一方で、ため込み基金は９３７億円もあります。２９号線を含む区内の３本の特定整備路線には８８３億円、再開発にはこれまで１,３６０億円の税金をつぎ込んでいます。住民を立ち退かせ、まちを壊す道路と超高層開発ではない、よいところは残し、悪いところは直していく、修復型のまちづくりへの転換を改めて求めて私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、羽田空港の低空飛行計画の撤回を求めて質問したいと思います。そこで、品川区に大きく３点伺います。確認いたしますが、濱野区長は、一度も国土交通大臣に会っていないということでよろしいのでしょうか。伺います。区長は、実は大臣には会っていなかったと、なぜ発言から４カ月もの間隠してきたのか、その理由を伺います。なぜこの事実を２年間も隠してきたのか、それぞれ３点伺います。","respondent":"藤田都市環境部長","answer":"大臣に会ったという話から４カ月後に発言を訂正したというようなことですけれども、先ほど答弁したとおり、会ったという発言があったわけではございませんので、私としては、区長が国土交通省に参り、事務次官や審議官とそれぞれお会いした際に。","voiceIndex":110,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、区長の発言から訂正まで、なぜ４カ月もかかったのか、隠してきたのではないかという質問です。そしてもう１つは、この区長が国土交通省と会っていたこと自体が、なぜ２年間も隠されていたのか、しっかりとご説明ください。","respondent":"藤田都市環境部長","answer":"そこの中で、当日、４月のほうは私も同席していますけれども、このときの動きが大臣に伝える、あるいは審議官とお話をするというようなことで動いていたので、私としては、そういうような解釈をしていたので、特に改めての訂正の話はしていなかったです。","voiceIndex":112,"id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"それが今になって、実は会っていなかったとは一体どういうことですか。部長に伺いますが、区長の記憶違いを部長が知ったのは一体いつなのか伺いたいと思います。そして、議会で質問されているのに、なぜ部長は４カ月もの間、区長に聞くことをしなかったのか、その理由も伺います。そして３点目、議会の質問とは、行政をチェックする民主主義の根幹です。率直に区長に反省を求めますが、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"私どもといたしましては、甘受するというようなお話もございましたけれども、あくまでも国際社会を維持発展させていくために羽田空港の機能を強化することについて一定の理解をするもので、それ以外の部分について、何ら理解であるとか。","voiceIndex":114,"id":"exchange-052"},{"speaker":"中塚委員","kind":"確認","question":"４カ月間質問したにもかかわらず、確認したのが１週間前とはどういうことですか。議会を何だと思っているのですか。区長の反省はないのですか。伺います。","respondent":"藤田都市環境部長","answer":"しっかりと議会の皆様方には、その後の区長が国土交通省に行った後に、国のほうから示された環境影響への配慮の方策、これが一定の区長が行ったときの成果の１つであるというふうに捉えてありますので、その方策についてはしっかり議会のほうに報告をさせていただいたところです。","voiceIndex":116,"id":"exchange-053"},{"speaker":"中塚委員","kind":"提案","question":"全然質問に答えていない。１週間前に確認はした。これに反省はないのですか。次の質問をします。国策ということであるので、これを甘受するとしたら、品川区にとって別のメリットをしっかりと提示してほしいと提案して、今、交渉しているところと二度も計画容認を発言しています。低空飛行はやめてほしいとの住民の民意をなぜ区長は無視をするのか伺います。計画容認の撤回を求めますが、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"区といたしましては、日本の経済、あるいは国際社会を維持発展させていくために、羽田空港の機能を強化することについては一定の理解をしているというところまでです。それ以外の部分で何ら容認をするようなものでもございません。国も区の立場をそのように捉えているものです。","voiceIndex":118,"id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"理解を示したのは機能強化であって、それ以上のものではないと、品川のこの役所の真上を飛ぶことではないとおっしゃいますけれども、こんなごまかしは通用しません。区長の発言は、品川区の見解ではないのでしょうか。伺います。部長は区の方針と異なることを区長が述べたとでも言いたいのでしょうか。それとも、この発言、区長はこちらも訂正するのでしょうか。それぞれ伺います。","respondent":"藤田都市環境部長","answer":"品川区としては、機能を強化することの必要性と、ルート案については、この間、分けて話をさせていただいているところで、国もそれは十分認識をしています。","voiceIndex":120,"id":"exchange-055"},{"speaker":"中塚委員","kind":"質問","question":"機能強化とルート計画の話を分けているなど、そんなごまかしは通用いたしません。これは飛ばないほうがいいが、それでも国策としてなら受けるかわりに品川区にメリットを示してほしいと交渉ということです。区長がここまではっきりと低空飛行を容認しながら、部長は了承していないと真逆のご説明、一体何なのですか、この答弁は。ご説明ください。","respondent":"藤田都市環境部長","answer":"は国に、この不安の払拭のためにしっかりと説明を行っていただきたいというふうに考えてあります。この不安の払拭に向けた具体的な国からのお話がないというようなことであるのだとしたら、このまま進めることについては納得をしかねるものというふうに考えてあります。","voiceIndex":122,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"ひどい騒音、落下物、墜落事故のリスク、資産価値の低下と、区民が区長に対して国に求めてほしいことは、受け入れではなく、計画の撤回です。区長が反対すれば計画はとまるのです。最後に、これほど重大な区長と国土交通省との交渉について、この資料が品川区には一切存在しない問題について伺いたいと思います。伺うのは、本当に何も記録も資料も作成されなかったのか、それとも廃棄されたのか伺います。","respondent":"藤田都市環境部長","answer":"区として要望事項をまとめるとなると、国としてそれだけに対応すればよいということにもなりかねないので、あえてペーパーをつくらず、大くくりのお話を今回の要望では伝えたところです。","voiceIndex":124,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"区が国に要望するときにメモもなくなど、そのようなことがあり得るでしょうか。同席する職員は、区の会議も当日の交渉もメモをとり、資料を残して記録するのが部長の仕事ではないでしょうか。それなのに区長は、メモを手にすることなく、見ることもなく、記憶の中だけで区の大事な要望を国に伝えたのですか。このようなことは行政を監視する国民の権利を奪うものだと思いますけれども、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"要望の趣旨ですけれども、区民の皆さんの不安の払拭について、国として具体的な対応、こういったものはかねてから区あるいは議会のほうからも要望を既に国に求めていたものです。今回の区長の要望で、今までの区や議会からの要望を念押しをする形で改めて実施したものです。","voiceIndex":126,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"区長が国土交通省に行くのに、何の資料も作成しない、交渉の中身の記録も残さない、このようなことがあり得るのでしょうか。改めて伺います。そして、先ほど聞きましたが、こうした公文書をつくらないことは、行政を監視する国民の権利を奪うものではないのか聞きましたので、しっかりお答えください。","respondent":"藤田都市環境部長","answer":"私どもといたしましては、しっかりとその中身を国土交通省に伝え、国土交通省から、取りまとめた環境影響への配慮をした方策を受け取ったこと、これが要望の結果であり、そのことをしっかり捉えて今後も進めていくべきというふうに考えてあります。","voiceIndex":128,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"２つ目の質問は、権利を奪うものではないですか。２回も聞きましたよ。","respondent":"藤田都市環境部長","answer":"先ほどもご答弁申し上げたとおり、その会議のさまざまな形態により、メモや記録の作成はするものです。その中で必要なものについて、私どもとしてしっかりと残していく、その姿勢については変わりがあるものではございません。","voiceIndex":130,"id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは行政を監視する議会や住民の権利を奪う重大問題です。ならば、この部長決定に間違いはなかったのか、本当に資料がないのか、上司である区長や副区長に調査を求めますが、いかがでしょうか。それとも、品川区はこのようにさまざまな交渉を行うときには、全く資料をつくらない、この行政運営とは一体誰の指示なのか、誰がこのような文書をつくらなくていいなどと部長に指示をしたのか伺いたいと思います。","respondent":"藤田都市環境部長","answer":"１つ１つの事務の執行については、所管のほうに任されているものでございまして、私のほうで進めているものです。","voiceIndex":132,"id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"私の質問は、部長決定への調査です。改めて伺います。そして、この部長に指示をしたのは誰ですか。伺います。","respondent":"藤田都市環境部長","answer":"１つ１つの事務の執行は所管に任されている話ですので、私のほうで行ったものです。","voiceIndex":134,"id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"その指示をしたのは誰ですか。この部長決定が間違っているのではないかと、この調査を求めているのです。これは上司にしかできません。いかがでしょうか。","respondent":"藤田都市環境部長","answer":"私に仕事を任されていて、その仕事に関することを私の権限で行ったものです。ですので、間違いはございません。","voiceIndex":136,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区長が国と交渉する際に、何の資料も作成しないとは、議会も区民にもチェックをさせないという隠蔽です。なぜ国との交渉の中身を区が一切隠す必要があるのでしょうか。国には資料はあるのです。区に資料がなかったのか、あったのか、部長決定に対する調査と、そして今後、行政が国などに要請する場合は、行政運営に当たって記録の作成の徹底を求めますけれども、いかがでしょうか。","respondent":"藤田都市環境部長","answer":"今後、国土交通省に要請する場面があれば、その１つ１つの内容に応じて、そういったものをつくるべきか、そうではないのかということについて、１つ１つの事象に照らし合わせて判断されるべきものだというふうに考えてあります。","voiceIndex":138,"id":"exchange-064"},{"speaker":"中塚委員","kind":"意見","question":"今年は品川区長選挙が９月に行われます。低空飛行に反対しない区長を区民は許しません。今回の交渉について記録をつくらない、こんな密室政治を許しません。民意に背く、民主主義に背く、そうした政治は許さないと指摘します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-065"},{"speaker":"木村委員","kind":"質問","question":"品川、大崎、大井、荏原の４地区、１３カ所で実施し、区民の皆さんが主体的に健康づくりにかかわるきっかけを提供、身近な地域で健康づくりの活動を推進している委員の皆さんについてお聞きいたします。お聞きいたします。平均年齢はどれぐらいで、最高齢の委員は何歳ぐらいでしょうか。この推進委員たちで長く活動されている方々は、どれぐらいの年数を活動されているのでしょうか。お聞かせください。","respondent":"西田健康推進部長","answer":"平均年齢は７２.８歳。最高齢の委員は９４歳ですが、今年の３月末で引退ということを聞いております。それから、推進委員で長く活動されている方々ということですが、活動が２０年以上にわたる方が９名、１０年以上の方が５３名、最長の活動歴の方は２６年です。","voiceIndex":142,"id":"exchange-066"},{"speaker":"木村委員","kind":"質問","question":"多くの方が参加されていますけれども、やはり女性の方が大変多くいらっしゃるということであります。そして、最高年齢が９４歳ということでありますから、大変すばらしいことだと思います。この推進委員会の方々の任期は何年間でしょうか。そして、この指導される指導員自身が、まずは健康でなければいけませんけれども、指導員たちが日ごろから心がけていることは何でしょうか。","respondent":"西田健康推進部長","answer":"再任可能で、特に定年は設けてございません。それから、指導員自身が健康でいるための心がけですが、１つは、推進委員みずから健康づくり事業に参加し、健康体操、ウォーキングなどを定期的に実施していることが健康維持にとって大きな要因になると思います。","voiceIndex":144,"id":"exchange-067"},{"speaker":"木村委員","kind":"質問・要望","question":"大変多くの方が長年推進委員として活動しているとお聞きしました。これからも区民の皆さんの健康を守っていくためにも、よろしくお願いしたいと思います。次に、しながわ健康プラン２１と、この推進委員の活動の関連性についてお聞かせください。今後の課題として、健康づくり推進委員の皆さんの高齢化が挙げられると思いますけれども、どのような形で支援していくのか教えていただきたいと思います。","respondent":"西田健康推進部長","answer":"解決策の１つは、やはり健康づくり推進委員自身が楽しめる要素を増やしていき、例えば、委員同士の懇親会や交流会などを実施したり、研修会などを実施して、負担を軽減したり、楽しんだりという取り組みは進めてきたところです。","voiceIndex":146,"id":"exchange-068"},{"speaker":"木村委員","kind":"質問・要望","question":"地域エコ活動推進事業「しながわ家庭エコチャレンジ」からの質問です。近年のエネルギー消費の増大に伴う地球温暖化の防止には、事業者だけではなく、各家庭でのＣＯ２削減が求められています。この授業を通して行政としては子どもに家庭エコとは何なのか、何のために行っていくのか等、未来の大人たちに学ばせ、どのように社会で活躍してほしいと望んでいらっしゃるのか、お考えをお聞かせください。","respondent":"藤田都市環境部長","answer":"平成２２年度から実施をしており、当初は児童３５％ほどでしたけれども、平成２９年度は約１万人、６６％の子どもが参加し、参加率は上昇してきているところです。","voiceIndex":148,"id":"exchange-069"},{"speaker":"木村委員","kind":"質問","question":"ぜひお願いしたいと思います。次に、“もったいない”プロジェクトからの質問です。お聞きしますが、本区が行っている事業、“もったいない”プロジェクトは、区民にどれだけ浸透し、どれだけ関心を持っていただいているとお考えでしょうか。人は余った食料をなぜ廃棄するのか、なぜ次へと考えられないのでしょうか。どのように行政としてこれから指導されるのかお聞かせください。","respondent":"藤田都市環境部長","answer":"食品ロス全体といたしましては、平成２９年１月に実施した環境に関する区民アンケートでは、食べ残し、消費期限切れなどで食品を廃棄しないよう、食品の購入や調理に配慮しているかどうかという質問に対しまして、こうしたことを行っている方が７５％。","voiceIndex":150,"id":"exchange-070"},{"speaker":"木村委員","kind":"質問","question":"駅周辺等放置自転車対策事業からの質問になります。歩行者や車椅子利用者の安全な歩行、円滑な緊急活動の妨げになるだけではなく、火災や犯罪発生時の緊急車両等の交通障害、さらには３０年以内に７０％以上の確率で起きると言われている首都直下地震に対しても、まちの整備、すなわち避難経路確保が大事だと思います。お聞きします。","respondent":"松代防災まちづくり部長","answer":"附置義務につきましては、百貨店やスーパーマーケットなどの施設を設置する場合、店舗の面積に応じた駐輪場の設置を義務づけているところです。","voiceIndex":152,"id":"exchange-071"},{"speaker":"木村委員","kind":"質問","question":"決して他人事ではなく、私たち自身も注意をしていかなければなりません。放置自転車等を解消することは、今や本区においても大変重要なことと思います。お聞きいたします。少なくとも私はそう思いますけれども、行政としてはどのようにすれば、そのような考えを起こさせず、放置させない対策が行えるのか、それとも放置自転車解消など到底無理な話とお考えなのか、ある程度本音でお答えください。","respondent":"松代防災まちづくり部長","answer":"区におきましては、関係機関と連携したキャンペーンの実施や指導、警告、撤去活動を行うとともに、駐輪場の整備に努めているところです。撤去台数を見ますと、平成１８年度には２万９,５０３台あったものが、平成２８年度には１万２,１６６台まで減少しております。","voiceIndex":154,"id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"そうすると、約５,０００万円の費用がかかることになります。もっとほかのところに使うべきと思いますけれども、本区のここ数年の推移は、どのように変動しているのでしょうか。１日大体数千台の自転車が区内で使用されていると思いますけれども、現在の条例にどのような規定を追加すれば、放置自転車が少なくなるとお考えでしょうか。よいお考え、対策があれば最後にお聞かせください。","respondent":"松代防災まちづくり部長","answer":"今後の自転車の利用状況を踏まえ、放置自転車の減少に向けて検討するとともに、これまで続けてまいりました放置自転車対策をしっかりと継続してまいりたいと考えております。啓発、撤去、駐輪場の整備の各対策を今後もしっかりと進めてまいります。","voiceIndex":156,"id":"exchange-073"},{"speaker":"大倉委員","kind":"質問・要望","question":"木村委員に引き続きまして総括質疑をします。災害にしっかりと備え、被害を少しでも抑え、区民の命、そして財産をしっかりと守りながら、安心安全の確保を適切に行っていく取り組みの観点から、防災の非常用発電機の設置と負荷運転について伺いたいと思います。そこで伺います。避難所においては、全避難所設置に至っているのかどうか、また、至っているのであれば、経緯と考え方について教えてください。","respondent":"榎本総務部長","answer":"それぞれ避難所の活動の中で必要なものがあるということで設置をしているものです。","voiceIndex":160,"id":"exchange-074"},{"speaker":"大倉委員","kind":"確認","question":"１年に一度の総合点検に、負荷運転をすること、また、消火活動に必要なスプリンクラーや消火栓、ポンプ等を動かすための最低３０％以上の出力の確認点検も義務づけられております。実施がなされていない施設においては、消防法の規定による、よらないにかかわらず、区民の安心安全のためにも早期に点検を実施すべきと考えますが、区のご所見を伺います。","respondent":"榎本総務部長","answer":"ただ、負荷運転につきましては、例えば２４時間施設であっても、仮に全部の施設を停電させなければいけないという形があったり、どういう形で負荷運転ができるかという問題もありますので、それも含めて消防機関との協議を行い、そういう試験ができるよう努めてまいります。","voiceIndex":162,"id":"exchange-075"},{"speaker":"大倉委員","kind":"質問・要望","question":"しかし、先ほど述べたとおり、阪神・淡路大震災から２２年、大きな震災が、ここ数年複数回発生しており、東京都においてもいつ発生してもおかしくないという状況でありますから、ぜひ早期の対応ということをお願いします。区民の安心安全の視点に立って、未実施のケースについても改めて早い対応を求めたいと思いますが、いかがでしょうか。早めに実施することが必要と思いますが、いかがでしょうか。","respondent":"榎本総務部長","answer":"国においても負荷運転の実施方法について、さまざま検討しているというふうに聞いておりますので、その動向を踏まえて、できるだけ早く負荷運転をできるようにしていきたいと考えています。","voiceIndex":164,"id":"exchange-076"},{"speaker":"大倉委員","kind":"質問・要望","question":"次に移りたいと思います。シティプロモーションについて伺います。そこで、品川区のシティプロモーションへの取り組みや考え方について質問をさせていただきたいと思います。品川区においても、多くの情報をもとに自己分析を行い、長所や短所を見極めるとともに、そういった分析結果的に基づいた中長期的なシティプロモーション戦略を策定することは非常に重要と考えますが、区のお考えをお聞かせください。","respondent":"中山企画部長","answer":"ただ、ご指摘のように、やはり先に向けた視点、中長期的な視点も必要かと考えていますので、当面、オリンピック・パラリンピックに向けての発信の強化は課題ではありますけれども、その先に向けての検討、今後の例えば長期基本計画の位置づけも含めて。","voiceIndex":166,"id":"exchange-077"},{"speaker":"大倉委員","kind":"質問","question":"ぜひお願いいたします。その中で、子育てや教育に対して有益な事業、品川区は実は独自の施策である取り組みがあるといった情報など、区外に対してよりよいシティプロモーションにこうしたことはつながっていくのではないかと考えておりますが、各課との連携を進めていき、さまざまな品川の一番の発見や独自の取り組み、政策を発信していくというシティプロモーションについて、区のご所見を伺います。","respondent":"中山企画部長","answer":"そういう点では、シティプロモーションの所管課と関係の区全体の各所管との連携を踏まえながら進めていきたいというふうに考えてあります。","voiceIndex":168,"id":"exchange-078"},{"speaker":"大倉委員","kind":"意見","question":"各課と連携をしていく中で、さまざまな品川の一面が見えてきて、それがまたシティプロモーション担当を通して、まちのにぎわいやシティプロモーションにつながっていけばいいと考えていますので、ぜひその辺の取り組みもお願いいたします。以上で、民進党・無所属クラブの総括質疑を終わらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":170,"id":"exchange-079"},{"speaker":"須貝委員","kind":"質問","question":"無所属品川を代表して総括質疑を行います。特別区民税についてお聞きします。毎年この区民税が大きく増えています。なぜ増えているのか、その理由を教えてください。この状況を区ではどのように分析しているのか、そしてこの区民税が増えたのは、区の政策によって生み出されたものですか。もしそうならば、どのような事業が成功したのでしょうか。教えてください。","respondent":"秋山財政課長","answer":"私から、区民税の件についてお答えをします。増えている大きな要因は、納税者数の増ということ。それから、所得環境の改善というのも寄与しているというふうに考えてあります。納税者の増ということで、こちらについては、区民の数が増えているというのが大きな原因だろうと。","voiceIndex":173,"id":"exchange-080"},{"speaker":"須貝委員","kind":"質問","question":"子育てに関しては、かなり東京の中では品川区は成果を上げているということで、区民の声もよく聞きます。評価されたということなのでしょうか。ですが、その一方で、ふるさと納税制度の返戻品競争により、区民税は減収となっています。新年度の減収見込額と、今までの累計減収金額を教えてください。そして、このふるさと納税とはいかなるものかも教えてください。","respondent":"榎本総務部長","answer":"この制度の趣旨はわかっておりますけれども、やはりふるさと納税の目的が明確に伝わっていない部分がありますので、そういったものの周知にきちんと努めるということと、各自治体においても返礼割合を３割以下にするようにということで、総務大臣の通知等が出ておりますので。","voiceIndex":175,"id":"exchange-081"},{"speaker":"須貝委員","kind":"質問","question":"毎年このような大きな金額、ますます増えているわけです。この金額が減収している。そして、もう累計で３０億円を超えてしまう見込みが出ています。本当にもったいない話だと思います。このお金があれば、支援を行えたはずの区民の方は大勢いらっしゃるわけです。このようなことでいいのでしょうか。そして、減収を抑える、抑制するべきだと私は思いますが、何か対策はとっていますか。教えてください。","respondent":"秋山財政課長","answer":"ふるさと納税そもそもの理論は理解するとして、返礼品競争に陥っているということについて、国に対して昨年も総務大臣に対して直接申し入れを行う等、国に対して制度の改正、改善を要求していくということと、それからまた、１つは。","voiceIndex":177,"id":"exchange-082"},{"speaker":"須貝委員","kind":"質問・要望","question":"確かに特別区長会において、国にいろいろこういう制度に関して異議を申し立てて改善してくれと要望している。それはわかります。ですが、実際にこれだけの金額を流出しているということは、私は考えなければいけないのではないかと思います。教えてください。区議会も、行財政改革について議論をしています。教えてください。","respondent":"秋山財政課長","answer":"各事業部、所管部が、１つ１つの事業を効率的に効果的に行っている中で工夫をして歳出の金額をなるべく抑えていってサービスを維持するということが必要だというふうに考えています。","voiceIndex":179,"id":"exchange-083"},{"speaker":"須貝委員","kind":"質問","question":"その中でこういう金額に対して、累計３０億円の金額が流出している。他の自治体とタッグを組んで、そして返礼品をもっと豪華にするとか、それを区民に提供するとか、そういうやり方をして、やっぱり減収を少しでもとめるというのが、区でやらなければいけない大事な施策だと思いますが、どうでしょうか。そして、区民からお預かりした大切な税金を区民のために使うべきではありませんか。教えてください。","respondent":"秋山財政課長","answer":"私どもとして、１つは、ネット経由の寄附などのチャンネルを増やすというようなことであったり、クレジット納付であったりとか、それから、今年の予算ではシナモロールのぬいぐるみ等、そういうブランディング等の価値を使って、品川区への寄附。","voiceIndex":181,"id":"exchange-084"},{"speaker":"須貝委員","kind":"質問","question":"これ、家計だったらどうなのでしょうか。国がこういうやり方をして間違った制度、本来は早くやめさせるべきだと私は思います。ですが、国がこのまま放置しているなら、やっぱりそれに対して我々も対抗する。次に、シティプロモーションについてお聞きします。そもそもシティプロモーションの始まった理由を教えてください。そして現在、幾つの自治体が実施しているのか教えてください。","respondent":"中山企画部長","answer":"そして区民の方への郷土への愛着心であるとか、シビックプライドといわれるような誇りにつながるようなものも育てていく必要がある、こういうことで始めたものです。全国の自治体のプロモーション数は、申しわけありませんが把握してございません。","voiceIndex":183,"id":"exchange-085"},{"speaker":"須貝委員","kind":"意見","question":"今、全国でシティプロモーションが本当にバブル化して、相当数の自治体が参加しているということです。税収も増えています。このような状況でシティプロモーション事業は、私は必要ないのではないか、もう既に完結していると思うのですが、ご見解をお聞かせください。そして、自治体のアピール競争もバブル化した今日では目立たないし、もうやめるべきではないかと思うのですが、ご見解をお聞かせください。","respondent":"中山企画部長","answer":"それと、この理由も後段に申し上げた区民の方の愛着、あるいは品川区の誇りを持っていただく、こういう点については、これは人口の動態とはまた別に品川区の魅力を区民の方にもしっかり掘り起こしていただき、また、品川区への愛着を高めていただく。","voiceIndex":185,"id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"これは全国の自治体の検証はしっかりやっているのでしょうか。だから、この品川区に来るのではないでしょうか。そして、人口減少が起きるというお話ですが、品川区、この２３区が、大震災でも起きない限り、ここが減少するということは、地方はもう完全に衰退してしまうという状況ではないですか。そのようなことは、ちょっと考えればわかると思うのですが、その辺についてご見解をお聞かせください。","respondent":"中山企画部長","answer":"今、区ではメディア認知度と言っておりますけれども、マスコミやいろいろなメディアで品川区をどれだけ知ってもらっているかということを少し統計的にとってみようということでありますが、５０％ぐらい、これは実は全国自治体の中で非常に高いのですけれども。","voiceIndex":187,"id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"魅力発信、足りないということですよね。それならば、私は、一番手っとり早いのは、ふるさと納税、返礼品競争ではないですか。そうしたら、多くの方に品川区の魅力を見てもらうなら、まずホームページに来てもらって、多くの方に区の状態はどうなのだとか、そういうことを見せる、そういうことが私は手っとり早いと思うのですが、それに対して最後にご見解をお聞かせください。","respondent":"中山企画部長","answer":"財政課長がお答えしたように、単純な返礼品競争に加わるのか、これは区としてはそういうスタンスではありませんけれども、ふるさと納税というものを通じて品川区の魅力を通じ、例えば物ではなく、品川区に足を運んでもらうきっかけにするというのは。","voiceIndex":189,"id":"exchange-088"},{"speaker":"須貝委員","kind":"質問・要望","question":"さまざまな魅力発信の方法があると思います。次に、品川区は最重要課題の１つとして、待機児童対策として保育園の増設を支援し、待機児解消に向けて努力してきました。これに加えて、保育従事職員宿舎借上支援事業、保育士等キャリアアップ補助金など、保育士の処遇改善に動いていますが、この制度はなぜ生まれたのですか。その理由と、この事業の中身はどういうことなのか教えてください。","respondent":"福島子ども未来部長","answer":"その両方の補助金を使いまして、区の総額としましては、平成２８年度で３億１,０００万円ほど使用しているというものです。こちらの改善の理由ですけれども、もともと保育士の平均年収が少ないですとか、仕事が厳しいですとか、そういうものを改善していこうという理由です。","voiceIndex":191,"id":"exchange-089"},{"speaker":"須貝委員","kind":"質問","question":"これを実施して、保育士の離職率は減りましたか。人材確保の効果はありましたか。そして、日本の勤労者の平均年収は約４２０万円ですが、これによって私立園の保育士の平均年収は上がったのでしょうか。実際、今は幾らぐらいなのでしょうか。教えてください。","respondent":"福島子ども未来部長","answer":"こちらの事業の実施による効果ですけれども、これは確実に上がっていると思います。今度、私立保育園が４月に向けてかなりの数が開園しますけれども、１つの園として保育士が足りなくて開園できないですとか、そういうところはございません。","voiceIndex":193,"id":"exchange-090"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当にありがたいと思いますが、まだまだ全国勤労者の平均年収には到達していませんので、これからも民間の保育士のため、処遇改善のために、国や都に要望していただきたいと思います。次に、介護の崩壊についてお聞きします。今、２０２５年問題として、介護の崩壊が言われていますが、これは何のことですか。何が問題なのですか。そして、介護は崩壊するのですか。教えてください。","respondent":"永尾福祉部長","answer":"介護の崩壊の問題ですけれども、よくご存じのとおり、７５歳以上の高齢者がこれから増えていくということが背景にあります。当然のことながら、７５歳以上になりますと、要介護状態になる確率も増えてきますので、介護サービスも必要になってくる。","voiceIndex":195,"id":"exchange-091"},{"speaker":"須貝委員","kind":"質問","question":"１つどうなのかと思ったのですが、今、介護財源の話をされていました。でも、介護をする方、要は、介護士、ヘルパー、こういう方たちの人材が実際どうなっているのかと思うのです。介護施設の夜勤は毎週２回あり、勤務時間は１日で１２時間から１４時間。月額は手取りで２０万円ぐらいしかなく、経験を積んでもそんなに増えない状態、これは大変な状態ではないですか。これについてご見解をお聞かせください。","respondent":"永尾福祉部長","answer":"どうして増えたかというところですけれども、この間、地道に介護福祉専門学校で都立高校の進学ガイダンスに参加したりとか、あと、高校２年生からオープンキャンパスに参加を促して、それでそのまま３年生に継続して入学につなげるとか、あと。","voiceIndex":197,"id":"exchange-092"},{"speaker":"須貝委員","kind":"質問","question":"今、部長、そういう答弁でしたが、現実、そうなのですか。いろいろなところで私は言われます。働いている本人たちからも話を聞きます。１２時間、１４時間、そして昼夜２交代、これが週に２回ある。このような状況は改善すべきではないですか。これは保育士と同様に、宿舎借上支援事業やキャリアアップ補助金など、介護士の処遇改善に動くべきだと思いますが、それぞれについてご見解をお聞かせください。","respondent":"永尾福祉部長","answer":"品川区でも、介護人材確保・定着に向けた緊急支援ということで、遠くから人材確保をした場合には、支援金だとか、交通費等の支給を行ったりとか、あと、レスパイト・職務継続支援といいまして、常勤職員の同居のご家族、親御さんとかが介護の状態になってきたときに。","voiceIndex":199,"id":"exchange-093"},{"speaker":"須貝委員","kind":"質問","question":"働きやすい職場、それはわかります、どのような職場でも大変なことはあります。それをきちんと、やはり部長のほうで、もうわかっていると思うのですが、私は、例えば介護保険の額が上がっても、今こういう人たちを支えないと、これから２０２５年まで８０万人の介護人材が必要になるのです。それを放っておいていいのですか。もう一度お聞かせください。","respondent":"永尾福祉部長","answer":"介護人材、なかなか厳しいところは正直あるかと思いますけれども、今、国のほうでも、介護のお仕事を分割して、本当に専門の人が必要な介護と、そうではなくて、お手伝いする人を臨時職員で雇いながら。","voiceIndex":201,"id":"exchange-094"},{"speaker":"須貝委員","kind":"質問・要望","question":"区では、確かに限界はあるというのは承知しています。こういうことは、やはりこれだけ大変な人がいるのだ、若者がなぜこの職業に定着しないのか、そのようなこと、人を助ける仕事、奉仕する仕事だから、皆さん喜んで若い人が入って続けると思います。ですが、やっていけない。この現状を国や都に明確に伝えていただきたいと思います。以上で、無所属品川の総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-095"},{"speaker":"田中委員","kind":"確認","question":"総務費でも声かけ事案について伺いましたが、私の子どもと、その友達が、二度、同じ不審者から同じ場所で声かけに遭った事例から、警察と区の連携や庁内での連絡手順などに課題が見えたので質問をいたします。声かけ等の事案を発見した人から１１０番通報があった後、警察から区へどのように情報が発信され、子どもたちや保護者、学校、すまいるスクール、保育園等へ情報が届くのか確認をしました。","respondent":"堀越地域振興部長、福島子ども未来部長、本城教育次長","answer":"そのような重要事案につきましては、生活安全担当課長から子ども育成課、教育総合支援センター。子ども育成課では、すまいるスクール、各児童センターに流すという形をとってあります。学校のほうに警察のほうから直接に情報提供があった場合ですが、その場合、当該校から区内の全ての公立学校に電子回覧にて連絡するとともに。休業中の場合、一義的には警察署で対応し、実害がない場合には現場で防犯指導等を行うということでございまして、そのほか、発生後。","voiceIndex":205,"id":"exchange-096"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれ伺いました。これを機に、不審者情報の発生についての情報共有、発信の方法について、再度、三者で確認をしていただきたいと強く求めます。そこで質問です。関連して伺います。不審者に遭遇したときのまもるっちの使い方について、すぐにまもるっちを引くという指導なのか、まずは逃げて身の安全を守ってから引くという指導なのか、どちらで指導されていると認識されているのか伺います。","respondent":"福島子ども未来部長、本城教育次長","answer":"その情報をもとに、子ども育成課では、ほかのすまいるスクール、あるいは児童センターのほうに流すとともに、生活安全担当課長、さらには教育総合支援センターのほうと情報を共有するという形。事案の軽重をよく把握した上で、上司である管理職、組織としても伝達し、そしてあわせて教育総合支援センターにも必要な情報については提供するという、そういうような形で仕組みとして対応することが適切だと考えております。","voiceIndex":210,"id":"exchange-097"},{"speaker":"田中委員","kind":"質問・要望","question":"最低でも不審者情報が発生した地域周辺では情報が行き届くようにしてほしいです。そのため、教員の中でもさまざまな状況を想定し、何か起きたときには、まず子どもの身を守るための判断や行動ができるように、意識の共有がされることを強く求めます。実際にそのような場面に遭遇した子どもに対し、「なぜまもるっちを鳴らさなかったの？改めてまもるっちの指導の認識について伺います。","respondent":"本城教育次長、堀越地域振興部長","answer":"今の答弁と重なるところがありますが、例えば、市民科の授業におきましても、１・２年生を対象にして、初めにまもるっちにかかわる適切な対応をしなければいけないということで、不審者等に遭遇した場合は、まずはその場を離れること。その際も、私どもも、まもるっちの正しい使い方を説明しながら、まずは逃げるというようなことを徹底して周知をしておりますので、引き続き、そのような形で行っていきたいというふうに考えているところです。","voiceIndex":213,"id":"exchange-098"},{"speaker":"田中委員","kind":"質問・要望","question":"これは要望にします。以下、質問します。国土交通省の来省記録によると、４月には４項目について配慮を求めた旨、記載があります。３８万人の区民が落下物の危険と騒音に悩まされるという、精神的苦痛に変わる地元へのメリットとは一体どのようなものを区長が想定して要望したのかお聞きします。本当にこのようなことを交渉されたのか、メリットは、結局、インフラ整備とお考えなのか伺います。伺います。","respondent":"藤田都市環境部長","answer":"メリットの部分ですけれども、区といたしましては、メリットよりも、まず航空機による環境の変化や安全性などについて、区民の皆さんが不安を感じている中で、国としてこれらを払拭することが何よりも重要だという考え方については従来どおりです。","voiceIndex":216,"id":"exchange-099"},{"speaker":"田中委員","kind":"質問・要望","question":"合意形成がどこではかられたのかということを聞いています。そして、記録が残っていないことに関して、区はどうお考えなのかということと、あと、インフラ整備については、例として挙げたとしても、国土交通省の文書には残っているのです。これはインフラを求めたと見た人は思いますが、いかがですか。","respondent":"藤田都市環境部長","answer":"合意の形成という部分ですけれども、区として、まず合意したということではありませんので、合意形成のための別な会議が何か開かれたというものではございません。","voiceIndex":218,"id":"exchange-100"},{"speaker":"田中委員","kind":"質問・要望","question":"そのことについて伺っています。改めて、４月と５月の話し合いは仮の話であるということを申し入れ、今度こそ文書として残しておくことを求めます。見解を伺います。大阪の落下物は、本来の飛行ルートから４kmずれていたということです。つまり、落下物の危険性は、ルート直下だけではなく、４km四方の全域に危険性があるということになりますが、その認識を区はお持ちなのか伺います。見解を伺います。","respondent":"藤田都市環境部長","answer":"このしっかりした説明というのが、なかなか具体性のないお話となっていますので、私どもとしては、これを具体的な説明というような形でやってもらわなければ、区としてこのまま進めることには納得をしかねるというふうに考えてございまして。","voiceIndex":220,"id":"exchange-101"},{"speaker":"田中委員","kind":"質問・要望","question":"区民が求めているのは、命と生活と財産が守られることです。次にいきます。行政施策の計画案についての住民説明会のあり方について伺います。例えば、大崎地区の再開発事業では、住民説明会を求める区民の声が議会にも届けられ、改善してほしいと要望がありました。説明会を開いた後にパブリックコメントを求めるよりも、パブリックコメントを求める前に説明会を開いてほしいと思いますが、いかがでしょうか。","respondent":"中山企画部長","answer":"まちづくりにかかわるという、ご質問の中にもありましたけれども、区の新規事業等の立ち上げに関しましては、基本的には事業の性質ごとに地域の皆様を含めて、適宜周知を行い、説明を行う。計画等によってはパブリックコメントを行っているです。","voiceIndex":222,"id":"exchange-102"},{"speaker":"田中委員","kind":"意見","question":"区民協働についての踏み込んだお考えもぜひお聞かせください。","respondent":"中山企画部長","answer":"計画に関する区民の参加ということで理解をさせていただいてお答えしますけれども、今のような事業あるいは性質に応じて意見を聞く、こういう中で、そういう意見も反映しながら判断をしていきたい、このように考えているものです。","voiceIndex":224,"id":"exchange-103"},{"speaker":"渡部委員","kind":"提案","question":"本日の総括質疑ならびに各款別審査で、自民党・子ども未来の各委員から、要望、提案しましたふるさと納税にかかわる提言、感染症予防と対策、子育てや介護人材の確保、水辺の利活用、コミュニティ・スクールの着実な運営、そしてオリンピック・パラリンピックを契機とした国際化や観光事業、まちづくりに教育のさらなる充実など、今後の施策に生かされることを求めます。最後に２点申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":228,"id":"exchange-104"},{"speaker":"若林委員","kind":"提案","question":"品川区議会公明党の意見表明を行います。我が会派は、平成３０年度品川区一般会計、同国民健康保険事業会計、同後期高齢者医療特別会計、同介護保険特別会計、同災害復旧特別会計の各予算案について賛成いたします。今後の財政に関しては、国の税源偏在是正の適切化を求める一方、その多大な影響に鑑み、新たに導入された新公会計制度の利点を最大限に生かした財政運営に努められるよう、強く要望いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":230,"id":"exchange-105"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"日本共産党は、過去最高、一般会計１,７４５億７,８００万円に対し、暮らし破壊の安倍政治追随から、住民の命、暮らしを守る区政への転換を求めてきました。新飛行ルートに反対表明をすべきです。公立保育園の民営化はやめ、増設こそすべきと求めます。最後に、安倍政権のもと、９条改憲がねらわれていますが、区民の命、暮らしを守る自治体の本旨を貫き、憲法を守り抜く区政を求め、意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-106"},{"speaker":"石田（し）委員","kind":"提案","question":"ＡＩやＩｏＴ等の活用や情報発信のあり方、民泊、羽田空港、働き方、学校教育、東京２０２０大会などの新たな課題への積極的な取り組みも求めます。今回の予算特別委員会において、我が会派の所属議員が質問の中で指摘、提案した各項目を真摯に受けとめ予算を執行することを強く要望して、民進党・無所属クラブの意見表明とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":234,"id":"exchange-107"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区の平成３０年度予算に対する意見表明を行います。無所属品川は、平成３０年度の品川区一般会計、国民健康保険事業会計、後期高齢者医療特別会計、介護保険特別会計、災害復旧特別会計の各予算に賛成いたします。特別区税や特別区交付金の増収により、法人税と特別区税が伸びて、一般会計予算は約１,７４６億円となり、過去最大の予算となりました。以上で、無所属品川の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-108"},{"speaker":"吉田委員","kind":"提案","question":"次年度から実施予定の第５期品川区障害福祉計画、第１期品川区障害児福祉計画を遂行するに当たり、これらの課題の一刻も早い解消を強く要望します。情報弱者である障害者の立場に沿う対応ができるよう、職員研修も含めた対応を引き続き要望します。その他、各款別審査で生活者ネットワークが指摘、提案させていただいた意見を予算執行に生かしていただくことを要望し、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":238,"id":"exchange-109"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1086#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":106209,"voices":244}},{"id":"h30-20180326-10","meetingId":"h30-cm03","date":"2018年3月26日","dateIso":"2018-03-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5268#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":6724,"voices":29}},{"id":"h30-20180413-10","meetingId":"h30-cm04","date":"2018年4月13日","dateIso":"2018-04-13","committee":"議会運営委員会","time":"午後 １時００分～午後 １時５３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"今までは組織委員会等にもさまざま要望させていただいて、今回も出していくと思いますけれども、そういう形の中でやってきたわけでありますが、改めてもう一度これはやはり我々の中でいろいろ考えながら、競技も行われるわけでありますので、それは必ずやっていくべきだろうと考えていますし、あとは、５番目にあえて入れさせていただきましたが、さまざま文化も教育もそうですが、最後。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-001"},{"speaker":"塚本委員","kind":"提案","question":"オリンピック・パラリンピック推進特別委員会ですけれども、調査事項として、「オリンピック・パラリンピックの推進に関すること」、「障害者スポーツに関すること」、「文化プログラムに関すること」ということで、これは前年度からの継続的な意味合いがありますけれども、特にこれまで東京都の組織委員会に対しての要望ということが、１つの議論の中心であったというところから進んで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"私どもは、特別委員会の数としては３つです。１つ目は、羽田新ルート対策特別委員会。調査項目としては、区民への影響とか国の対応。２つ目は、震災対策特別委員会。調査項目は、避難所運営マニュアル。住宅耐震化。３つ目に、子どもの貧困対策特別委員会として、実態調査。区民に大きな影響が及ぼされる問題等々について、特別委員会としてふさわしいのではないかということで、３点に絞りました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"会派からは、３点挙げさせていただきました。１つ目は、行財政改革特別委員会として、いわゆる都区のあり方について。そして在宅での子育て支援について。子育てしやすい環境の整備について、品川区もさまざま子育ての支援をしていますが、品川区イコール子育てというイメージをもっと持ってもらうように、こういった対策について、議論をするべきではないかなということで、３つ目に掲げました。","respondent":"渡部委員長","answer":"今年度の特別委員会についての検討に入りたいと思いますが、進め方としましては、委員会名と調査事項、委員会数を固めていきたいと思います。委員会名や調査事項、数が固まりましたら、委員数および正副委員長の数を決めたいと考えておりますので、よろしくお願いします。","voiceIndex":16,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"意見","question":"我々としては、調査事項の項目は別として、特別委員会については２つ。それで、名称も我々としては、行革とオリ・パラで行くという形が、我々は望ましいのかなと。委員会室は同じような形で対応していく。委員会の人数は同じで、正副も同じというか数は委員長１人、副委員長１人ということは変えずにやっていくということのほうが、我々としてはいいのではないのかなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"うちは先ほど説明したとおりなのですけれども、特別委員会という委員会の性質を見たときに、やはりその時々の状況。区民との要求との関係。あるいは、緊急に調査を深めて、そして一定の結論、方向性を出していけるような、そういう常任委員会とは違う意味合いが特別委員会にはあると思うのです。したがって、議論の末なのですけれども、そこの点はぜひ受けとめていただきたいなとそういうふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-006"},{"speaker":"塚本委員","kind":"意見","question":"うちの会派の意見としては、先ほど言ったものが１つの案として望ましいのではないかというところでありましたので、会派の意見としてはそうなのだということしかないのですけれども、だからといって、行財政改革特別委員会では受け入れられないというところまでは、固い決意を持っているというところでもないので、もし時間があるのであれば、もう１回持ち帰って検討させていただければと思いますが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"私は、議論でいろいろなこうそれぞれ２つとか３つずつ出しているけれども、いろいろ多岐にわたって出ているではないですか。だから今、今年度何と何が必要だよねというそういうチョイスをして、それでそれの状況によって２つとか３つとか１個で足りる場合もあるかもしれない。少し数のところを私も聞き過ごしてしまったのかあれだったのですけれども、意見だけは言っておきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、塚本委員がおっしゃって、例えば会派の中で持ち帰ってということであれば、別に２０日でもいいわけだろうから、２つということが決まって、名称については２０日に決めればいいのだろうし、中身のことについて言えば、我々は意見はあるけれども、それはそれで我々も会派に持ち帰って諮らなくてはならない部分もこれから中身については出てくるかもしれないので、それは２０日に向けて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほど、人数とかそういうものも先に決めるのではなかったでしょうか。違いますか。","respondent":"渡部委員長","answer":"そのとおりだと思いますので、その部分に関しては、この辺の内容を詰めるにあたって、品川区における独自の取組みを念頭に置いて進めていくというようなやり方でもよろしいのかなというふうに。","voiceIndex":32,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"意見","question":"基本的に独自の取組みにおいては、いわゆる文化プログラムも、ボランティアも、教育も諸々を含んでの独自の取組みなので、内容に関しては、自民党・公明党から出ている内容でも、我々としては特段異議があるわけではないので問題ないと、構わないというのがあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"提案","question":"スポーツ交流ができる都市の人たちと、そういうことをもっと継続的にやれるようなことはつくっていきたいと思っているわけだけれども、いかんせんそのときのボランティアとか、観戦とか、教育とか言うと、これまではいろいろ要望を言ってきたのですが、この後は、頭ごなしに来たら受けざるを得ないみたいなところに来てしまうのかなという不安はあるのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問","question":"基本的に大項目でいいのではないですか。４つぐらい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"行革特別委員会の中で、３年間にわたり、羽田機能強化についてという項目が入ってきたのですけれども、ぜひ私たちは羽田だけでも特別委員会をつくっていただきたいということで提案をしているのですが、そういうふうなことにならないのであれば、行革委員会の中に羽田新ルートについての、機能強化についての項目をぜひ今までと同じような形で入れていただきたいということを、強く要望したいのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"そういうつもりもありますし、今、内容、話があって、我々は会派でもちろんいろいろ議論した中で、この提出をさせていただいているので、この行革について、今みたいな議論になるのだろうなと思っておりまして、それは皆さんの意見をうかがった後、我々としては、これに臨む前からそう思っておりましたけれども、こういう議論になるのだろうなと思っておりましたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"もちろん持ち帰るのは否定するものではないのですけれども、今石田秀男委員からも話が出たように、やはりこの問題は私どもはすごく品川区民の関心の高い問題だというふうに思っているし、事実そうですし。案件という言葉を使うと誤解かな。それについて、そういう認識のところを各会派の皆さんからぜひご意見出していただいて、それを持ち帰って議論するのであればしたいなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-016"},{"speaker":"南委員","kind":"意見","question":"だから、鈴木ひろ子委員も皆さんの意見を聞きたいとおっしゃっていたし、私も聞きたいというふうに思うので、この場で議論初めて俎上にのったので、ぜひ各会派の議論として、意見を聞きたい。そういうふうに思っての意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-017"},{"speaker":"塚本委員","kind":"提案","question":"先ほど、提案の説明で申し上げたところに基本的にはよるのですけれども、改めて言えば、これまで継続してやってきたというところのそういう中で、今後いわゆるそういう飛ぶか飛ばないかという局面が、一応案としては２０２０年にという話も出てきているものなので、引き続きという考え方でいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-018"},{"speaker":"石田（し）委員","kind":"意見","question":"我々としては、行財政改革の中には実は入れていないのですが、もちろん事の重要性というか、課題というのはあるという認識のもと、それを何も議会で議論しないというわけではなくて、皆さんがどうしても特別委員会でというのであれば特段強い否定をするわけでもないですし、先ほどお話があったように、常任委員会でもやれるのであれば常任委員会でやるというのも１つの選択肢なのかなと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"常任委員会だと１０席しかないので。傍聴者１０人以下ということは今までなかったのです。そういうところからすると……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"傍聴者が、やはりこれだけ多いという、それだけ関心が高いということですので、そこのところをしっかりと保障していくということも含めて、ぜひご検討いただいて、行革の中に入れていただきたいということで、お願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5270#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":17675,"voices":78}}]);
